INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000001', '.Bank Registry', 'https://www.Register.Bank', '.Bank is the only domain extension built exclusively for the banking community. When you dot your bank, you benefit from top-tier domain security, credibility, and protection of customer trust and loyalty. Schedule a call with our team to learn more or apply today to make the switch at Register.Bank.', 'Mr. Craig Schwartz', 'craig@ftld.com', '(202) 236-1154', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000002', '360 View', 'https://www.360view.com', '203 Saint Anne Way Franklin, TN 37064-6110 360 View is the CRM Platform created specifically for banks, providing the necessary tools to maximize your team’s performance. Our solution offers the best 360-degree view of your customers empowering you to make smarter decisions and grow your relationships. Our platform includes CRM, Marketing Automation, Analytics, Profitability, and Goal and Incentive Tracking. 360 View was developed by bankers for bankers and has been serving the financial industry for over 20 years.', 'Mr. Mark Schiefelbein', 'mschiefelbein@360view.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000003', '360factors, Inc.', 'https://www.360factors.com', '360factors empowers organizations to accelerate profitability, innovation, and productivity by predicting risks and streamlining compliance. Predict360, its flagship software solution, is a Risk and Compliance Intelligence Platform augmented with Artificial Intelligence technology to predict and mitigate operational risks while streamlining regulatory compliance.', 'Ms. Megan Ward', 'megan.ward@360factors.com', '(866) 385-2341', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000004', '3PR, Inc. (Third Party Resources)', 'https://www.3princ.com', '3PR Inc. specializes in Risk Management, including Regulatory Compliance, BSA/AML Compliance and Internal Control Audits. We focus on compliance, risk assessments, policy and procedures assistance, training, risk-based audits, and call report preparation, review and training. One of the things that we do best is provide hands-on consulting and reviews, including real-world recommendations and solutions. Our goal is to assist our clients, including community banks, money service businesses and even emerging reg-tech firms, in developing a sound and sustainable risk management program.', 'Ms. Lori A. Victory, CRCM, CAMS, CFSA', 'lvictory@3princ.com', '(713) 678-0898', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000005', '3Sixty Integrated', 'https://3sixtyintegrated.com', '1218 Arion Pkwy Ste 120 San Antonio, TX 78216-2813 3Sixty Integrated is a trusted security integrator specializing in access control, video surveillance, and intrusion detection. As part of the Cook &amp; Boardman Group, we provide scalable, compliance-driven security solutions for industries including banking, financial institutions, healthcare, education, and government. Our tailored approach helps banks mitigate risk, enhance security, and protect assets with innovative, reliable technology. Learn more at https://www.3sixtyintegrated.com/', 'Ms. Brenda Constantin', 'bconstantin@3sixtyintegrated.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000006', 'Abrigo', 'https://www.abrigo.com', 'Abrigo provides compliance, credit risk and lending solutions that community financial institutions use to manage portfolio risk, drive loan growth and fight financial crime. Our software automates key processes - from anti-money laundering to fraud detection to lending workflows - empowering our customers by addressing their Enterprise Risk Management needs. The company offers both ABA-endorsed solutions for CECL compliance and supports 2,300+ financial institutions.', 'Mrs. Persis Tuttle', 'persis.tuttle@abrigo.com', '(919) 851-7474', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000007', 'AccessIT Group, LLC.', 'https://www.AccessITGroup.com', '21 Waterway Ave Ste 300 Spring, TX 77380-3099 25 Years of Cybersecurity Excellence
Cybersecurity isn’t one of the things we do, it’s all we do. For 25 years, we’ve helped organizations build security programs that perform, driven by real experts, not noise. No generalists. No fluff. Just focused expertise and proven results. As threats evolve, we cut through the complexity, delivering clarity, confidence, and control.', 'Mr. Tom Cline', 'TomC@AccessITGroup.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000008', 'Acuity Knowledge Partners', '', '111 W Jackson Blvd Ste 1700 Chicago, IL 60604-3597 Acuity Knowledge Partners is a strategic outsourcing partner, and the leading provider of research &amp; analytics to the financial services industry. We currently support over 600+ financial institutions, including 3,000+ trained resources spread across 50+ commercial/regional banks &amp; 150 investment banks in the US across front, middle, and back-office functions. Given our global talent pool, we provide high level talent at a cost arbitrage to help our clients improve efficiencies and manage attrition. 
At Acuity Knowledge Partners, we specialize in supporting commercial banker tasks to facilitate enhanced client coverage, reduce speed to market, and provide overnight leverage, at a cost-efficient scale. Our highly experienced resources operate as an extension of client teams, providing support on origination, underwriting, credit monitoring, and loan operations across various asset classes and portfolios, ranging from C&amp;I to CRE, ABL, Consumer Mortgage, retail, loan operations, and more.
What sets Acuity apart is our expertise across all loan origination platforms and our proprietary automation tools developed specifically for the credit analysis value chain. We have developed robust tools that encompass financial spreading, covenant monitoring, credit reviews, and workflow management. These tools enhance efficiency in the lending process, allowing for faster decision-making and streamlined operations.We are here to support Texas Banks of all sizes to mitigate internal bottlen', 'Mr. Evan Leski', 'evan.leski@acuityanalytics.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000009', 'Adrenaline, Inc.', 'https://adrenalinex.com', 'Adrenaline is an end-to-end brand experience company serving the financial industry. We move brands and businesses ahead by delivering on every aspect of experience. From branding strategies for renaming to construction of physical spaces, our services are comprehensive, connected, and bound one goal: creating brand experiences that drive business value.', 'Mr. Sean Keathley', 'sean@adrenalineshot.com', '(404) 252-9995', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000000a', 'Advantage Health Plans Trust', 'https://AdvantageHealthPlans.com', '13431 Broadway Ext Ste 130 Oklahoma City, OK 73114-2225 Advantage Health Plans Trust is a not-for-profit health benefit solution owned by and designed specifically for community banks. Our plans are tailored to the specific needs of each bank or financial institution and are governed by a member-elected Board of Trustees.

Advantage Health Plans Trust is not a large insurance carrier, nor are we backed by one. Instead, we are community bankers who operate a pool of funds contributed directly from our member banks. The plan is self-insured and administered by The Kempton Company instead of corporate health insurance, meaning any realized healthcare savings stay in the plan – further benefitting our members.', 'Mr. Merrick Matthews', 'mmatthews@kemptongroup.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000000b', 'Advantage, Powered by JMFA', 'https://advantage-fi.com/', 'For over 40 years, ADVANTAGE has delivered measurable results to community banks. Our data-driven solutions—account acquisition, deposit growth, overdraft privilege, contract negotiations, and technology strategy—drive income growth. Trusted industry-wide, we build tailored strategies that ensure profitability, regulatory compliance, and peace of mind for sustained client success.', 'Mr. Chad Jolly', 'chad.jolly@jmfa.com', '(800) 809-2307', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000000c', 'Aeon Legal Tech', 'https://aeonlegaltech.com', 'Aeon is a secure, AI-powered platform designed by lawyers to transform transactional legal work. It automates document drafting and abstraction in minutes with unparalleled accuracy and zero hallucinations, enabling teams to work faster, reduce risk, and focus on high-value tasks. Aeon delivers the speed, structure, and security modern legal practice demands at scale.', 'Mr. Jeff Livingston', 'jlivingston@aeonlegaltech.com', '(972) 716-1888', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000000d', 'Agri-Access', 'https://www.agri-access.com', 'o	Agri-Access is a secondary market financing participant that delivers capital solutions to a nationwide network of agricultural lenders. We help strengthen and expand our lending partners’ ag portfolios through tailored, scalable solutions designed to support long-term growth.', 'Mr. Trever Hall', 'trever.hall@agri-access.com', '(515) 675-3715', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000000e', 'Alkami Technology', 'https://www.alkami.com', 'Alkami Technology, Inc. is a leading cloud-based digital banking solutions provider for financial institutions in the U.S. that enables clients to grow confidently, adapt quickly and build thriving digital communities. Alkami helps clients transform through retail banking and business banking, digital account opening, loan origination, card services and multi-payment fraud prevention solutions.', 'Mr. Chris Spohr', 'chris.spohr@alkami.com', '(469) 458-9427', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000000f', 'All Covered Inc', 'https://www.allcovered.com/industries/finance', 'All Covered is your partner in IT, cybersecurity and compliance, providing community banks with a complete suite of services engineered to mitigate security and compliance risk, reduce IT expenditures and improve operating efficiencies.', 'Mr. Amo McDonald', 'Amcdonald@allcovered.com', '(714) 990-1144', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000010', 'Alliance Advisors', '', 'tkies@allianceadvisors.com 150 Clove Rd Little Falls, NJ 07424-2138 Alliance Advisors is an independent advisory firm focused on Shareholder Meeting Advisory. Shareholder Meeting Advisory, Shareholder Engagement, Compensation, Governance &amp; Sustainability Advisory, M&amp;A - Activism, Institutional Ownership Intelligence, Proxy Logistics, Investor Relations and Retail Outreach.
We work around the world for public and private companies operating at board and C-suite levels. We go beyond the norm to develop and execute bold, client-first strategies, resulting in winning outcomes. We have a longstanding client base of over 1200 active public companies from a range of industries and market capitalization sizes. 
Our clients engage with us on multiple services on a year-round basis. We are headquartered in the US, working together as one team, around the world, in multiple locations.', 'Mr. Thomas Kies', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000011', 'Allied Payment Network', 'https://www.alliedpayment.com', '202 W Berry St Ste 410 Fort Wayne, IN 46802-2248 Allied Payment Network’s mission is to provide financial institutions with world-class payments tools that establish them as the heart of the communities they serve. With a real-time, open-network model, its suite of solutions includes its flagship bill pay product, FlexPay™, as well as FlexPay for Business™, P2P, A2A, PortalPay, and FlexFund™.', 'Mr. Doug Elser', 'doug.elser@alliedpayment.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000012', 'Allure Security', 'https://www.alluresecurity.com', 'Allure Security online brand protection-as-a-service protects brands by finding and stopping online brand impersonation attacks before customers fall victim. Our patented, artificial intelligence-powered engine finds more spoofed websites, social media accounts, and mobile apps more quickly and with greater accuracy than legacy approaches. Our unique, multi-pronged approach to managed response – blocklisting, decoy data, and end-to-end takedown – significantly reduces the lifespan of a scam and associated account takeover, fraud, customer churn, and staff burden costs.', 'Ms. Phylis Miquel', 'pmiquel@alluresecurity.com', '(877) 669-8883', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000013', 'ALM First Financial Advisors, LLC', 'https://www.almfirst.com', 'ALM First Financial Advisors is a leading, trusted strategic partner for depository institutions, offering an array of financial advisory services headquartered in Dallas, TX. Since 1995, our expertise in asset liability management, fixed income portfolio management and hedging, has allowed us to deliver deeper insights into financial institutions’ balance sheets, strengthening their financial performance and building efficiencies. ALM First Financial Advisors is an SEC-registered investment advisor, with over $70 billion of assets under management (as of March 31, 2025). ALM First Group acts as an unbiased third party, offering commission-free, fee-based advisory services for approximately 300 financial institutions across the country.', 'Ms. Taylor Klutts', 'tklutts@almfirst.com', '(800) 752-4628', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000014', 'Alston & Bird LLP', 'https://www.alston.com', 'Alston &amp; Bird''s financial services legal team, among the most recognized in the country, routinely ranks near the top of the league tables for transactional work. With lawyers who served in senior policy making and enforcement positions with the OCC and Federal Reserve, we provide meaningful bank regulatory proficiency, consumer finance and compliance experience and payment systems prowess when solving a host of complex day-to-day needs for all players in the financial services arena.', 'Mr. Sanford M. Brown', 'sanford.brown@alston.com', '(214) 922-3505', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000015', 'Alter Domus', '', 'robert.ashbaugh@alterdomus.com https://alterdomus.com/services/enterprise-credit-and-risk-analytics/ 500 5th Ave New York, NY 10110 Alter Domus provides advanced analytics tools and financial models that enhance and scale our client''s credit and model risk management process. Our product ecosystem and best-in-class service team provide extensive end-to-end enterprise credit analytics and reporting solutions. This includes risk and performance models addressing the challenges of CECL, stress-testing, capital planning, risk rating, macroeconomic forecasting, and loan behavior. The platform includes detailed model documentation, model review, back-testing, attribution, and reporting.

Alter Domus also provides loan servicing for commercial and asset-based loans, special asset management, construction draw administration and loan review.', 'Robert Ashbaugh', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000016', 'The Ambrose Group', 'https://www.theambrosegroup.com', 'With almost 30 years of experience, The Ambrose Group produces over 3,000 appraisals annually and assists its clients in making informed real estate decisions by providing market driven valuations. Our team includes real estate professionals who have obtained the highest designations from the Appraisal Institute. With offices located in Houston, Dallas, San Antonio and Lubbock, The Ambrose Group is knowledgeable in market trends and highly capable of serving its clients throughout Texas.', 'Mr. Brian Burk', 'bburk@theambrosegroup.net', '(832) 300-1721', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000017', 'Ameriprise Financial Institutions Group', 'https://www.ameriprise.com/afig', 'With more than 25 years of experience and knowledge in serving the investment program needs of local banks, Ameriprise Financial Institutions Group brings a depth of understanding as well as capabilities to help clients feel more confident, connected and in control of their financial life. We look forward to learning more about your financial institution and sharing how a successful investment program can be a competitive advantage – helping you drive customer retention and deliver incremental value.', 'Mr. Jay L. McAnelly', 'jay.mcanelly@ampf.com', '(210) 483-5073', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000018', 'Apiture', 'https://www.apiture.com', 'Apiture, now part of CSI, delivers award-winning digital banking solutions to community and regional banks and credit unions, helping them compete with the nation’s largest financial institutions. With our API-based consumer, business, digital account opening, and embedded banking solutions as well as a suite of data and marketing tools, we help our clients innovate at the speed required in today’s competitive environment. Founded in 2017, Apiture was acquired in October 2025 by CSI, a leading provider of end-to-end financial software and technology. To learn more, visit www.apiture.com and follow Apiture on LinkedIn.', 'Ms. Nicci Jenkins', 'nicci.jenkins@apiture.com', '(800) 545-4274', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000019', 'Armanino', 'http://www.armanino.com', '15950 Dallas Pkwy Ste 600 Dallas, TX 75248-6685 Armanino is a top-25 U.S. accounting and advisory firm providing audit, tax, consulting, and technology-enabled services. For community banks, Armanino offers specialized support across internal audit, SOX and FDICIA compliance, regulatory readiness, risk management, and process optimization. The firm combines deep financial-services expertise with a practical, risk-based approach to help banks strengthen controls, meet regulatory expectations, and operate more efficiently.', 'Joshua Kettler', 'josh.kettler@armanino.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000001a', 'Arriba Advisors', 'https://www.arribaadvisors.com', 'As an employee-owned strategic advisory firm with a track record of more than 2,000+ successfully negotiated contracts, Arriba Advisors is dedicated exclusively to your bank''s success. We provide partner-level engagement from the meeting room to the negotiating table, bringing over 200 years of combined experience from within banks and industry-leading vendors to address the unique challenges your bank faces. Whether you are navigating a core renewal, debit/credit evaluation or PIN network analysis, we''ll help you reset cost structures and select the technology that best supports your bank''s strategic direction.', 'Mr. George McGourty', 'gmcgourty@arribaadvisors.com', '(813) 999-0881', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000001b', 'Artificial Intelligence Risk', 'https://www.aicrisk.com', '152 E Putnam Ave Cos Cob, CT 06807-9984 Artificial Intelligence Risk (AIR) is at the forefront of AI governance, risk management, regulatory compliance, and cybersecurity. Our mission is to integrate safe, private, compliant, and customized AI platforms, deployed via a quick 14-minute ARM script, for agnostic GRCC integration with any LLM, any data repository, and all AI agents, inside a company’s internal private cloud infrastructure. 
Our single pane of glass platform serves diverse industries but specializes in "high-risk AI" for heavily regulated sectors, including finance, thereby enabling organizations to leverage enterprise AI technology securely and effectively. In 2024, AIR-GPT was recognized by Waters Technology as the #1 solution for both AI Compliance and AI Cybersecurity in a vote by thousands of members of both the buy and sell side communities. In 2025, in conjunction with our partners at Fynancial Inc., we launched Fyn for wealth management, which was recently named the #1 app for wealth-tech at RIA Edge.', 'Mr. Joe McMann', 'joemcmann@aicrisk.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000001c', 'Ascensus', 'https://www.ascensus.com', 'Ascensus is the industry leader in supporting IRAs, HSAs and other tax preferred savings plans. For more than 40 years Ascensus has delivered comprehensive IRA and HSA solutions and education to the banking industry. With one of the largest ERISA consulting teams in the country and training solutions to keep your organization informed, Ascensus’ capabilities ensure workflow compliance and efficiencies. Ascensus is the clear choice when looking to bring your IRA and HSA programs to the next level.', 'Mr. Joseph Doolittle', 'joseph.doolittle@ascensus.com', '(800) 346-3860', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000001d', 'Ascribe LLC', 'https://www.ascribeval.com', '400 N Tustin Ave Ste 410 Santa Ana, CA 92705-3834 The Ascribe family was built on the acquisition of nine industry leading companies providing exceptional services such as Valuations, Evaluations, REO, and Default services nationwide. Ascribe''s management team includes renowned, respected experts with decades of industry knowledge and expertise. We do business your way. Ascribes multiple acquisitions have imparted a flexible infrastructure that adjusts to your needs. Ascribe''s vast product line allows us to value any property, for any purpose, anywhere in the US.', 'Kelly Taylor', 'ktaylor@ascribeval.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000001e', 'Assembly Engine Inc', 'https://assemblyengine.ai/', '1305 E Houston St Ste 1400 San Antonio, TX 78205-2003 Assembly Engine is an AI-native platform that automates commercial loan closing workflows for community banks and credit unions. It replaces the slow, manual, error-prone document preparation process that slows down lending teams today with intelligent automation purpose-built for commercial lending. The result: faster closings, fewer errors, and dramatically reduced reliance on outside counsel for loan documentation.', 'Darpan Saini', 'darpan@assemblyengine.ai', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000001f', 'Associated Bank - Foreign Exchange', 'https://www.associatedbank.com/commercial/capital-markets/foreign-currency-exchange/FX-Correspondent-Banking', 'Associated Bank is focused on providing foreign exchange services throughout all of Texas. In May 2020, we partnered with Fiserv to become a foreign exchange provider on the Payments Exchange (formally WireXchange) platform. We have provided Capital Market services for over 20 years, including interest rate and commodity derivatives and foreign exchange services for businesses and correspondent financial institutions.', 'Ms. Whitney Banker', 'whitney.banker@associatedbank.com', '(800) 320-5442', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000020', 'Atris Technology, LLC', 'https://atris.com', 'Banking technology company focusing on in-house financial software and house provided network and security services, including MSP, MSSP, and item processing.', 'Mr. Dan Roberts', 'droberts@atris.com', '(352) 275-5578', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000021', 'Avannis', 'https://us.avannis.com/listen/', '6400 S Fiddlers Green Cir Ste 300 Greenwood Village, CO 80111-4955 Avannis is the ICBA preferred service provider for experience and satisfaction feedback—for both the customer and the employee. Dedicated to assisting banks since the 90s, Avannis administers the membership benefit that covers all setup costs for any of the 30+ surveys. ICBA membership literally saves your bank thousands in setup fees, and levels the playing field with your larger FI competitors. Most banks include feedback/NPS collection from many touchpoints and transactions in their customer experience program. With no contract, you can start listening actively to all of your customer segments. The Avannis/ICBA program fits banks with 2 branches, and 290 branches equally. Avannis offers every methodology technologically possible to reach customers, along with rich benchmarks not available anywhere else. Most clients also include social media integration (so you are generating more organic reviews as you listen).', 'Ms. Emily Sayer', 'emily.sayer@avannis.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000022', 'AvTek Solutions, Inc.', 'https://www.avteksolutions.com', 'AvTek Solutions is a Veteran Owned Managed Service Provider. We are the premier IT experts in the Financial Service Industry with over 10 years of experience specializing in banks. AvTek is built on the core beliefs of communication, loyalty, integrity, knowledge and continuous growth. With 100% of our support team based in Texas, we are here to serve you.', 'Mr. Wayne B. Hunter, Jr.', 'wayne.hunter@avteksolutions.com', '(214) 778-2983', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000023', 'Babich & Associates, Inc.', 'https://www.babich.com', 'Babich &amp; Associates are a team of more than 20 professional recruiters who have an average of 20 years’ experience in the recruitment industry. With specific expertise in several industry verticals, we dominate the markets we serve in Texas. In 64 years of business, we have placed more than 100,000 candidates in positions ranging from the branch to the boardroom. Our services are provided to clients on either a retained or contingency basis.', 'Mr. Anthony Potenti', 'apotenti@babich.com', '(214) 515-7609', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000024', 'Backbase', 'https://www.backbase.com', 'Backbase is known across the world as the authority on Engagement Banking, a people-first approach to financial services. With our category-leading Engagement Banking Platform (EBP), we help banks and credit unions craft the seamless user journeys that their customers and members demand.', 'Marcelo Romanelli', 'marcelor@backbase.com', '(208) 250-2415', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000025', 'Baker Hill Solutions', '', 'mike.horrocks@bakerhill.com https://www.bakerhill.com (800) 821-4455 1320 City Center Dr Ste 300 Carmel, IN 46032-3816 Baker Hill is the expert solution for loan origination, portfolio monitoring and analytics for financial institutions in the U.S. The company delivers a single unified platform with modern solutions to streamline loan origination and portfolio monitoring for commercial, small business and consumer lending. The Baker Hill NextGen® platform also delivers sophisticated analytics and marketing solutions that support sound business decisions to mitigate risk, generate growth and maximize profitability.', 'Mr. Mike Horrocks', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000026', 'Baker Tilly US, LLP', 'https://www.bakertilly.com', 'Baker Tilly is a top ten advisory, tax and assurance firm dedicated to building long-lasting relationships with our clients and our communities. With offices across Texas, we’ve been guiding banking and capital markets clients through the ever-changing business world, providing CECL model validations, regulatory compliance, BSA and AML solutions, ALM solutions, liquidity management, federal, multistate, M&amp;A and due diligence tax planning, tax credits and incentives advisory, model risk management, board and audit committee governance and more. Visit bakertilly.com/banking-capital-markets to discover what our Value Architects can do for you.', 'Ms. Veronica Biffel', 'veronica.biffel@bakertilly.com', '(972) 748-0515', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000027', 'BancCard of America Inc', 'https://www.banccard.com', 'Founded in 1997 BancCard has been focused on building bank partnerships and meeting customers in-person with our local sales and service team. We’ve earned the trust of more than 600 Banks across 28 states making BancCard one of the nation’s leading Merchant Service Providers. We offer customers the ability to accept credit card payments from five of the largest processors. This allows us to deliver the latest in technology in payments processing throughout the nation.', 'Mr. Brian Pemberton', 'bpemberton@banccard.com', '(832) 367-4292', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000028', 'The Bank Advisory Group', 'https://www.bankadvisory.com.', 'Specialists in valuations and bank mergers &amp; acquisitions. M&amp;A services include: initiating transactions for potential sellers; support,strategic advice and analysis for buyers, sellers and merger partners; issuance of fairness opinions; expert testimony for legal proceedings. Bank stock valuations of community banks for employee benefit plans, shareholder agreements, estates, and stock repurchases.', 'Mr. Stephen Skaggs', 'stephen_skaggs@bankadvisory.com', '(512) 263-8800', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000029', 'Bank Marketing Center', 'https://www.bankmarketingcenter.com', 'BankMarketingCenter.com (BMC) is a web-based marketing portal that empowers banks to produce professionally designed, bank-branded marketing materials in a matter of seconds. BMC puts you in complete control of the ad production process for your bank, saving valuable time and money.BMC has thousands of successful marketing materials including ads, direct mail, statement stuffers, flyers, posters, digital signage and more. On the site, you can select a marketing piece and customize it within seconds.', 'Mr. Neal Reynolds', 'nreynolds@bankmarketingcenter.com', '(678) 528-6688', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000002a', 'Bank Performance Report', 'https://www.bankperformancereport.com', '600 W Main St Ste 400 Louisville, KY 40202-2998 Utilizing data from the quarterly FFIEC Call Reports, the BPR is a state-specific quarterly publication providing a wealth of data carefully curated to help you quickly and easily determine your bank’s greatest strengths and opportunities. Find out where your bank’s overall performance ranks on eight different categories – Net Interest, Non-Interest Income, Non-Interest Expenses, Efficiency, NPA''s/Equity &amp; Reserve, Asset Quality Index, Return on Assets and Return on Equity. Reports available in print and electronic formats.', 'Ms. Selina Parrish', 'sparrish@kybanks.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000002b', 'The Bankers Bank', 'https://www.tbb.bank', 'The Bankers Bank provides correspondent services to community banks in Texas, Oklahoma, Kansas and New Mexico. The bank is a traditional banker''s bank owned by community banks to serve community banks. The Bankers Bank provides bank stock loans, over line loan participations, cash letter, safekeeping, etc. All we do is help banks. Not a competitor but your partner. (Member of FDIC, Federal Reserve System &amp; an Equal Housing Lender).', 'Mr. Jim Chapman', 'jchapman@tbb.bank', '(405) 848-8877', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000002c', 'Bankers Insurance Agency', 'https://www.bia.insurance', 'Bankers Insurance Agency has been serving the insurance needs of Texas banks for over 30 years. Products offered include Financial Institution Bonds, Directors &amp; Officers Coverage, Cyber Liability and Breach Response Coverage, Debit Card Fraud, Property, Auto, Umbrella and Workers Compensation Coverage. They represent all the major insurance carriers in the marketplace that specialize in insurance products for banks. Over 250 banks trust their insurance coverage and peace of mind to Bankers Insurance Agency.', 'Mr. Brien G. O''Connor', 'brien@bia.insurance', '(512) 479-6615', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000002d', 'Bankers Purchasing Group Powered by EC Purchasing', 'https://www.bankerspurchasinggroup.com/home', '601 Riverside Ave #11 Jacksonville, FL 32204-2901 Bankers Purchasing Group helps banks reduce operational expenses on products and services such as shipping, wireless service &amp; equipment, office supplies, IT products, office equipment, travel, and others which are used to run their organizations. We are no cost, no obligation program.', 'Adolfo Fernandez', 'Adolfo.fernandez@ecpurchasing.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000002e', 'BankLabs Participate', 'https://www.banklabs.com', 'Participate, a patented BankLabs innovation, revolutionizes loan trading by automating participations and syndications across a network of banks and financial institutions, handling any loan type and size. It democratizes loan trading, enabling larger loans, mitigating concentration risk, and enhancing liquidity. Automating both front and back office tasks for banks, Participate streamlines the entire loan participation process, making even smaller deals profitable and ensuring lenders can continue lending with optimum efficiency.', 'Mr. Andrew  Norton', 'andrew.norton@participateloan.com', '(501) 246-5148', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000002f', 'BankTalent HQ', '', 'bjackson@illinois.bank https://www.banktalenthq.com 524 S 2nd St Ste 600 Springfield, IL 62701-1751 In a collaborative effort, BankTalentHQ brings together an alliance of 40 state banking associations, working collectively to serve as a comprehensive resource for the industry. Whether you''re seeking a job in the financial sector or looking to fill a position within your organization, BankTalentHQ is here to assist you every step of the way.
 
BankTalentHQ has grown beyond just a job board, seeking to bring even more resources to bankers. BankTalentHQ is the exclusive talent management site of the American Bankers Association (ABA).  The partnership provides discounted pricing on all ABA online training, certificate programs, and professional certification exam prep.
 
Visit BankTalentHQ.com today to gain a competitive edge in talent acquisition, development, and retention.', 'Mr. Ben Jackson', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000030', 'Bank-Tec South', '', 'mattsanders@bank-tecsouth.com https://www.bank-tecsouth.com (318) 453-3682 4150 Viking Dr Bossier City, LA 71111-7407 Bank-Tec South (BTS) is an industry leader that provides a comprehensive portfolio of solutions tailored to the specific requirements of financial institutions. BTS specializes in offering complete and unrivaled security solutions to clients in the financial industry, as well as a varied line of modern banking equipment. BTS has maintained a strong emphasis on client service since 1987, making us a valued asset in today''s financial services industry.', 'Mr. Matt Sanders', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000031', 'BANORTE - BANCO MERCANTIL DEL NORTE SA', '', 'julian.fernandez.cortes@banorte.com https://www.banorte.com Av. Revolución 3000, La Primavera Monterrey, N.L. 64840 MEXICO Grupo Financiero Banorte is the second-largest financial group in Mexico by assets, with over USD 144 billion in total assets as of 2025. Banorte is the Group’s core banking subsidiary, which offers comprehensive retail, corporate, and institutional banking services and holds a leading position in Mexico’s financial system. Banorte also has strong international banking capabilities through its correspondent banking area, providing MXN clearing accounts, foreign exchange, and trade finance solutions to global financial institutions.', 'Mr. Julian David Fernandez Cortez', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000032', 'Banzai, Inc.', 'https://www.banzai.org', 'Banzai is a Premier Financial Literacy content provider for Banks. Banzai has all the marketing tools that you need to create engaging, unique, high-quality content for your website and to partner with community organizations, non profits, schools, and social media.', 'Ms. Katie Rigby', 'katie@banzai.org', '(888) 822-6924', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000033', 'Barcom Technology Solutions', 'https://barcoment.com/', '10443 Gulfdale St Ste 101 San Antonio, TX 78216-4117 An All-In-One Solutions Center that services Texas residents and their growing businesses. Our expertise is in technology, but we have a culture of putting people first. Whether you’re an employee here, at a partner company, or a client business, you’re part of our team. We’ll work with you to overcome challenges and find the way forward. We''re here to be part of the solution.', 'Ms. Julie Francois', 'jfrancois@barcoment.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000034', 'BCC', 'https://www.bcc-usa.com', 'BCC leads the industry with its approach to servicing its clients with a state-of-the-art plan design that assists banks in attracting, retaining and rewarding their leaders through compensation consulting; design and implementation of customized Executive and Director benefit plans; Bank Owned Life Insurance (BOLI); and ownership succession planning.', 'Ms. Kathy Smith', 'kathy.smith@bcc-usa.com', '(972) 781-2020', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000035', 'Berkley Financial Specialists', 'https://www.berkleyfs.com', 'Berkley Financial Specialists, a Berkley Company, is dedicated to providing customized, comprehensive insurance solutions and outstanding personalized service to financial institutions. We offer specialized management liability and fidelity coverages. Berkley Crime, a division of Berkley Financial Specialists, is focused exclusively on providing crime-related insurance products for commercial organizations, financial institutions, and governmental entities.', 'Ms. Tonya Lusk', 'tlusk@berkleyfs.com', '(410) 337-9260', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000036', 'BHG Financial', 'https://bhgfinancial.com', 'BHG Financial has one of the largest community bank networks in America. Over 1,650 institutions have purchased our low-risk, high-yielding loans, earning interest income in excess of $1.6B combined since 2001. BHG has originated $20B+ in loans to high-income borrowers of impeccable credit quality, offering banks reliable revenue growth and diversification.', 'Mr. Jim Crawford', 'jim@bhg-inc.com', '(315) 415-9511', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000037', 'BitLyft', 'https://www.bitlyft.com', '107 N Clinton Ave Saint Johns, MI 48879-1501 BitLyft is a leading managed security service provider, dedicated to small to mid-sized, regulated organizations with high-touch, compliant cybersecurity solutions. Our prioritization of service and security excellence, creates a holistic defense approach that allows our clients to navigate the digital world with unwavering confidence. Since 2016, our mission is to break down the barriers of cybersecurity for organizations, ensuring that every client harnesses the full potential of their investments through our evolving .', 'Ms. Michelle Hollis', 'michelle.hollis@bitlyft.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000038', 'Black Hills Information Security', 'https://www.blackhillsinfosec.com', '115 W Hudson St Spearfish, SD 57783-2342 At Black Hills Information Security (BHIS), we strive to strengthen our customers’ information security infrastructure and employees through penetration testing, consulting, and defensive security services. Since our founding in 2008, companies of all sizes, from small community banks to Fortune 100 companies, have entrusted us with their business.', 'Mr. Jason Blanchard', 'Jason@blackhillsinfosec.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000039', 'Blanchard Consulting Group', 'https://www.blanchardc.com', 'Blanchard Consulting Group has worked with over 400 community banks over the past ten years and collectively has more than twenty-five years of compensation consulting experience. Our group works with senior management and boards of directors on all facets of compensation for directors, executives and staff level employees. Our specialized focus on the banking industry sets us apart from our competitors. Our mission is to help you attract, motivate, and retain your best employees. Our consultants apply their extensive knowledge and experience to ensure your programs maintain compliance with current regulations and provide you with the greatest return on your investment in your employees.', 'Mr. Michael Blanchard', 'mike@blanchardc.com', '(770) 672-6767', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000003a', 'BluCognition', 'https://www.blucognition.com/', 'bluCognition enhances lenders’ analytics capabilities using advanced AI/ML to convert and analyze alternative data - now integrated with SBFE commercial bureau data to deliver a comprehensive 360 degree view of borrower risk. Our flagship product, bluSense, provides real-time bank statement conversion for deep cash flow insights. FraudLens detects document tampering, and our automated solutions convert financial statements, payroll records, and more. Through our managed services arm, we offer dedicated teams for underwriting, fraud review, KYC/KYB, sanctions screening, and other operational support - helping clients scale with precision and confidence.', 'Mrs. Tasha Aubey', 'tasha@blucognition.com', '(602) 390-0988', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000003b', 'Blue Orange Digital', 'https://blueorange.digital', '750 Lexington Ave New York, NY 10022-1200 Blue Orange Digital helps financial institutions modernize their data and AI strategies with secure, scalable solutions. From data engineering and analytics to intelligent automation and GenAI, we meet financial institutions where they are in their journey. Our end-to-end services enable smarter decisions, stronger compliance, and more personalized member experiences by building trust while driving efficiency and long-term growth.', 'Mr. Brett Byriel', 'brett@blueorange.digital', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000003c', 'BMO', 'https://commercial.bank', 'As a leading bank with over 200 years of service, BMO is the 8th largest bank in North America by assets that provides personal and commercial banking, global markets and investment banking services to 13 million customers.', 'Sach Bhutani', 'sach.bhutani@bmo.com', '(414) 239-1565', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000003d', 'BNY Mellon Investment Management', 'https://www.bnymellon.com', 'BNY is a global financial services platforms company at the heart of the world’s capital markets. For more than 240 years BNY has partnered alongside clients, using its expertise and platforms to help them operate more efficiently and accelerate growth.', 'Mr. Christopher Saul', 'chris.saul@bnymellon.com', '(646) 578-7481', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000003e', 'BOK Financial Institutions Group', 'https://www.bokfinancial.com/institutions', 'BOK Financial Institutions Group is a part of BOK Financial Corporation, a $50 billion regional financial services company with more than $105 billion in assets under management and administration. The Financial Institutions Group assists their community bank client base with balance sheet management and liquidity needs through a comprehensive suite of tailored solutions designed to enhance financial performance. Core services include asset/liability modeling and risk consulting, strategic portfolio management, third-party reviews, and stress-testing, and brokered funding solutions.', 'Mr. Nick Polyak', 'npolyak@bokf.com', '(918) 588-6000', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000003f', 'BOND.AI', 'https://www.bond.ai', '417 Main St Little Rock, AR 72201-3801 BOND.AI is the creator of the world’s first Empathy Engine®, an artificial intelligence (AI) and machine learning system designed to give financial institutions a holistic understanding of their products and customer bases. The Empathy Engine® gives access to powerful data analytics, optimizes revenue streams, and creates a hyper-personalized and needs-based approach to marketing efforts.', 'Mr. Jared Landrum', 'jared@bond.ai', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000040', 'Botdoc', '', '13395 Voyager Pkwy Ste 130 Colorado Springs, CO 80921-7677 Botdoc is transporting data, documents, and transactions with end-to-end encryption without imposing pins, passwords, logins, accounts, apps, or software to download on the consumer.  Furthermore, upon delivery of the data, Botdoc confirms receipt of delivery and overwrites/deletes the data, removing longterm data/storage liability. Botdoc NOW (SaaS-based product) is perfect for SMBs - Botdoc API is built into some of the largest systems in the world.', 'Mr. Tracy Fox', 'tfox@botdoc.io', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000041', 'Bracewell LLP', 'https://www.bracewell.com', 'Bracewell LLP is a national leader in serving the full range of legal needs of growth-oriented, public and private banks and other financial institutions. Bracewell advises clients on mergers, acquisitions, divestitures, capital raising activities, including initial public offerings and private placements, corporate governance matters and, in the case of its public company clients, compliance with Securities and Exchange Commission rules and regulations. Bracewell''s experienced advisors assist in all aspects of a transaction, including due diligence and risk analysis, tax, intellectual property, labor and employment, employee benefits, executive compensation, real estate, environmental matters, and litigation, including internal investigations and enforcement actions.', 'Mr. Will Anderson', 'will.anderson@bracewell.com', '(713) 223-2300', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000042', 'Builder Finance Inc.', 'https://www.builderfinance.com', '504 Mesquite Ranch Rd Denton, TX 76210-2459 Builder Finance Inc. (BFI), a subsidiary to 1st Financial USA Bank, is a senior-mortgage lender for 1-4 unit, single family residential (SFR). BFI has a 10+ year track record providing construction loans to small- and mid-sized companies building SFR with a loss rate of less than 0.1% over that same period. In this sector, BFI sees compelling market fundamentals such as an undersupply of homes and a pullback by larger bank lenders. We are providing an opportunity to fellow banks to participate in BFI’s construction lending program. BFI will perform all origination, underwriting, and servicing work while maintaining skin-in-the-game/pari-passu interests in all sales.  BFI has the relationships, the track record, and the operating infrastructure to support the continued success and growth of our business further benefiting our partner banks through the addition of high-quality assets.', 'Mr. Greg A. Hargis', 'GHargis@builderfinance.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000043', 'Built Technologies', 'https://www.getbuilt.com', 'Built is the leading provider of construction finance technology. Built connects commercial and consumer construction lenders, commercial real estate owners, commercial general contractors, residential homebuilders, specialty contractors, title companies and other industry vendors to improve the flow of capital through the construction ecosystem. By connecting all key stakeholders involved in the construction financing process in real-time, the platform helps mitigate risk, power faster draws and payments, ensure compliance and inspire customer loyalty.', 'Ms. Mikell Woodfield', 'Mikell.woodfield@getbuilt.com', '(800) 655-8138', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000044', 'Burke Stelling Group', 'https://burkestelling.com', '1000 Parkwood Cir SE Ste 810 Atlanta, GA 30339-6627 Burke Stelling Group is a prominent Atlanta investment bank focused on a diverse range of private businesses, with a deep legacy in community banking and financial services.', 'Mr. Drew Stelling', 'dstelling@burkestelling.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000045', 'Burrows Financial Holdings, LLC', 'https://burrowsfh.com', '224 Sandhill St Webster, TX 77598-2346 Burrows Financial Holdings, LLC is a Texas-based firm specializing in serving families of significant wealth, their family offices, and select institutions. Originally founded as institutional fixed income brokers and consultants, we have evolved into a comprehensive financial services platform. Today, we provide tailored solutions in wealth management, investment advisory, tax strategy, insurance, estate planning, and business consulting. Our team brings decades of experience and a deep commitment to building enduring relationships based on trust, performance, and integrity.', 'Mr. Don Burrows, Jr.', 'don.burrows@burrowsFH.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000046', 'Cain & Kiel Law, PC', 'https://www.cainlawyers.com', '508 N Ridgeway Dr Cleburne, TX 76033-5112 We are a boutique law firm located in Cleburne, Texas. Founded in 2022, we specialize in 
civil litigation and a variety of transactional areas of law included real estate, probate, 
estate planning, and banking.', 'Mr. Brent L. Kiel', 'brent@cainlawyers.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000047', 'Caird Investment Partners, LLC', 'https://www.cairdinvestments.com', 'Caird Investment Partners, LLC, a SEC registered investment advisor, launched with approximately $450 million in assets under management. The firm provides highly specialized loan (Syndicated Loans, Term Loan Bs), Securities, and Capital Markets advisory services to regulated financial institutions, addressing the particular complexities and regulatory demands of the banking sector. Additionally, Caird provides proprietary sourcing and underwriting of private credit investments suitable to a range of counterparties from regulated financial institutions to alternative asset managers.

Our Name:
In 1916, Sir Ernest Shackleton and a small crew sailed the James Caird—just 22-feet long—through 800 miles of open ocean and 66-foot waves to seek help for their stranded Antarctic expedition. Against staggering odds, they succeeded, ultimately bringing the entire team to safety.

We chose the name Caird to reflect that same spirit: navigating complexity, adapting under pressure, and finding a way forward, together.', 'Mike Schott', 'mschott@cairdinvestments.com', '(469) 729-0530', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000048', 'Calamos Investments', 'https://www.calamos.com/protection', '2020 Calamos Ct Naperville, IL 60563-3284 Calamos Investments is a diversified global investment firm offering innovative investment strategies, including alternatives, multi-asset, convertible, fixed income, private credit, equity, and sustainable equity. With more than $40.3 billion in AUM, including more than $17.9 billion in liquid alternatives as of December 31, 2024, the firm offers strategies through ETFs, separately managed portfolios, mutual funds, closed-end funds, interval funds, and UCITS funds. Clients include financial advisors, wealth management platforms, pension funds &amp; endowments, foundations, and individuals, globally. Headquartered in the Chicago metropolitan area, the firm also has offices in New York, San Francisco, Milwaukee, Portland (Oregon), and the Miami area.', 'Mr. Frank Tirado', 'ftirado@calamos.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000049', 'Cambridge Investment Research, Inc.', 'https://www.joincambridge.com', '1776 Pleasant Plain Rd Fairfield, IA 52556-8757 Cambridge is one of the nation’s largest privately owned financial solutions firms. Whether you are looking to start an investment program or enhance an existing one, Cambridge can help you build a program that meets the needs of your institution and your customers. Choose from various program structures, unique compensation arrangements that are fully adaptable to your financial institution.
Contact us to discuss the future you want to build, and how we can help guide you there.', 'Mr. Barry Schmidt', 'Barry.Schmidt@cir2.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000004a', 'Candescent', 'https://www.candescent.com', '4 Concourse Pkwy Ste 400 Atlanta, GA 30328-5397 Candescent helps banks and credit unions deliver fast, connected, and modern financial experiences—propelling them into the era of Intelligent Banking. We raise the standard of experience, trust, and service so businesses, families, and communities can grow stronger together. Our extensive portfolio and integrated ecosystem of solutions, built on an API-first architecture, enable institutions to optimize and extend capabilities by connecting custom or third-party tools. With connected in-person, remote, and digital experiences, we reinvent service across every channel. Candescent empowers financial institutions to accelerate growth, deepen engagement, and compete confidently in a digital-first world.', 'Ms. Monica Harris', 'monica.harris@candescent.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000004b', 'Capital Asset Resources', 'https://www.capitalassetresources.com', 'Capital Asset Resources provides a leasing program to community banks. As an independent leasing company, we assist banks in developing unique and profitable equipment leasing programs by providing the following benefits: -         Complete lease origination and administration services -         Quality customer service -         Product training and new product information -         Increased profitability through fee income growth -         Diversify the bank''s portfolio We help our partners establish cross-selling opportunities that will help their bottom line and expand their business customer base.', 'Mrs. Taylor Cromer', 'tcromer@capitalassetresources.com', '(817) 416-8347', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000004c', 'Capstack Technologies', 'https://www.capstack.ai', '252 NW 29th St Fl 9 Miami, FL 33127-3904 Capstack is the leading loan trading platform and the only platform that offers loan trading, participations, servicing, and bank portfolio analytics.
Our platform enables banks, credit unions, and other financial institutions to buy and sell loans regardless of size or geography, providing unmatched access to liquidity and diversification. 
Capstack has the highest volume of buyers, sellers, and transaction types, making it easy to find new trading partners and collaborate with confidence', 'Mr. Alex Ward', 'alex.ward@capstack.ai', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000004d', 'Capstone Banktech', '', '(704) 993-8195 1601 Westpark Dr Ste 4C Little Rock, AR 72204-2418 Capstone Banktech provides community banks and lending institutions with a turnkey accounts receivable lending solution that generates fee income, builds deposits, and delivers twice the profitability of a traditional line of credit. Since 2014, our proprietary software platform, CapitalExpress, has processed more than $2.6 billion in loans across 1.7 million individual transactions. Backed by a full-time support team with decades of industry expertise, CapitalExpress gives your bank a secure, profitable lending program without the operational burden.', 'Mr. Erik Trumpower', 'erik@capstonebt.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000004e', 'Carr, Riggs & Ingram', '', 'ccain@CRIadv.com https://www.CRIadv.com (936) 634-6621 3700 Colonnade Pkwy Ste 300 Birmingham, AL 35243-3213 Located in 40+ markets across the U.S., CRI is a top 25* nationally ranked accounting and advisory firm driven by relationships to cultivate growth. CRI’s industry specializations include construction, government, banking/financial institutions, healthcare, insurance, not-for-profit, manufacturing, and distribution. CRI offers traditional and specialized services, including audit and assurance*, business outsourcing and support, forensic accounting, IT auditing, retirement plan auditing, SEC compliance, business valuation, tax planning, and trusts and estates work. Additionally, the CRI Family of Companies delivers service organization control (SOC) reports*, data analytics, investment banking, business consulting, retirement administration services, wealth management, payroll services, professional athlete tax advisory services, and trust and estate services. We invite you to learn more about CRI at CRIadv.com.', 'Mr. Chris Cain', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000004f', 'Carty, Harding, and Hearn', 'https://cartyco.com', 'Carty, Harding &amp; Hearn is a full-service investment broker/dealer. We are a nationally recognized, locally owned, well capitalized firm with over 50 years of experience in fixed income trading and sales. Specializing in municipal bonds, we underwrite new offerings all over the United States as well as trade securities in the secondary market to best service our institutional and individual clients.', 'Mr. Grant Vazzano', 'gvazzano@cartyco.com', '(901) 766-6224', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000050', 'CBIZ Risk & Advisory Services, LLC', 'https://cbiz.com', '6002 Rogerdale Rd Ste 300 Houston, TX 77072-1660 CBIZ provides independent, risk-based internal audit, regulatory compliance, and advisory services to banks nationwide. We support institutions through risk assessments, outsourced and co-sourced internal audit, FDICIA and SOX readiness, IT audit, model validations, BSA/AML, NACHA audits, and governance enhancement—helping banks strengthen controls, meet regulatory expectations, and manage risk as they grow. Additional capabilities include managed IT, cybersecurity assessments, credit risk services, and other complementary offerings.', 'Mr. Jason Fuqua', 'jason.fuqua@cbiz.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000051', 'Centrant Community Capital', 'https://www.centrant.org', 'Centrant Community Capital is a mission-driven lender, leveraging the resources of the banking industry to finance the creation and preservation of quality affordable housing. Funding for Centrant''s CRA-eligible loans is provided by member banks, allowing institutions of all sizes to support community reinvestment efforts in a safe, profitable manner. Our loans consistently meet the needs of our borrowers, provide a range of benefits to our member banks, and strengthen the communities we serve together.', 'Mr. David R. Bennett', 'david@centrant.org', '(919) 981-7979', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000052', 'CFGI', 'https://www.cfgi.com', '801 Barton Springs Rd Austin, TX 78704 Austin, TX 78704-1146 CFGI, the leading global independent accounting and business advisory firm, a portfolio company of Carlyle and CVC, offers tailored solutions across more than 30 offices worldwide. With over 1,000 dedicated professionals from Big Four and executive backgrounds, CFGI delivers expertise in accounting, technology, finance transformation, IPO readiness, SEC reporting, strategic advisory services and more, helping clients navigate complex challenges and achieve success.', 'Mr. Nick Stavros', 'nstavros@cfgi.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000053', 'CGI Technologies & Solutions Inc.', 'https://www.cgi.com', 'Founded in 1976, CGI is among the largest IT and business consulting services firms in the world, with over 100,000 consultants worldwide. CGI is a key partner with TBA in the TBA Magnet program, bringing big bank services and solutions to community banks at affordable prices and positive ROI. We are insights-driven and outcomes-based to help accelerate returns on your investments.', 'Mr. Jefferson A. Boeck', 'jefferson.boeck@cgi.com', '(617) 599-9353', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000054', 'Chaindots', '', 'delfina@chaindots.com https://chaindots.com 330 Sunny Isles Blvd Tower 05 Ph 2 Sunny Isles Beach, FL 33160-5633 Chaindots is the first risk and compliance collaborative platform, where companies connect, share information and facilitate business in an agile and secure way. With our platform companies can efficiently know and monitor the risk of their clients, clients of clients, partners and vendors, gaining agility, security and scalability in their operations. With Chaindots you can automate and scale your KYC, KYB, CDD, Partner &amp; Vendor Due Diligences, Transaction Monitoring, Ongoing Screening processes and more!', 'Ms. Delfina Chain', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000055', 'Chartwell Partners', 'https://www.chartwellpartners.com', 'Founded in 2005, Chartwell Partners is a retained senior executive search and leadership advisory firm based in Dallas. Chartwell’s Financial Services Practice, led by Scott Petty, is focused on serving community, commercial, and regional banks across Texas. Our team of nine professionals conducts over 30 retained senior executive and board director assignments each year. Chartwell’s Leadership Advisory Practice, led by Dr. Julie Bell, helps clients navigate succession planning, executive assessments, coaching and onboarding.', 'Mr. J. Scott Petty', 'spetty@chartwellpartners.com', '(214) 228-0343', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000056', 'ChaseCompGroup, LLC', 'https://www.chasecompgroup.com', '1270 Caroline St NE Ste D120 Atlanta, GA 30307-2954 ChaseCompGroup, LLC is a national compensation consulting firm that delivers solutions and compensation programs tailored to our clients’ specific strategy and compensation objectives. Our consultants have worked in the executive compensation arena for the past three decades, with an exclusive focus on the community banking industry since 2003. ChaseCompGroup, LLC has advised over three hundred community banks across the United States. Our mission is to help community banks develop compensation programs that are competitive, effective, and responsible.', 'Ms. Diana Chase', 'dchase@chasecompgroup.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000057', 'CheckAlt', 'www.checkalt.com', 'CheckAlt helps financial institutions modernize how commercial clients get paid. From traditional lockbox to digital-first receivables, we reduce risk, improve visibility, and streamline workflows. Our solutions—including lockbox, electronic lockbox, online payments, and remote deposit capture—are delivered through a single portal. One login. One vendor. One contract. We make it easier to accept, process, and reconcile payments without disrupting operations.', 'Hunter Richardson', 'hunter.richardson@checkalt.com', '(213) 634-7187', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000058', 'Chimayo Consulting LLC', 'https://chimayoconsulting.com', '5318 Weslayan St PMB 147 Houston, TX 77005-1048 Chimayo Consulting LLC delivers fractional and interim risk management advisory services to banks and financial services firms, specializing in enterprise risk management, operational risk, third-party risk management, and governance.', 'Ms. Katherine Avery', 'katherine@chimayoconsulting.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000059', 'Clearinghouse CDFI', 'https://www.ccdfi.com', 'Clearinghouse CDFI is a full-service, direct lender financing projects that create jobs and services to help people work, live and thrive in healthy communities. Established in 1996, we address unmet credit needs nationwide, focusing on TX, CA, NV, AZ, NM and Indian Country. Loans include affordable housing, community facilities, small businesses and commercial real estate. Types include construction, acquisition, renovation, expansion and refinance. We offer short and long-term permanent, fixed rates, 3-25 years, fully amortizing.', 'Mr. Cesar Plascencia', 'cesarp@ccdfi.com', '(949) 859-3600', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000005a', 'CliftonLarsonAllen, LLP', 'https://www.claconnect.com', 'CLA provides integrated audit, tax and consulting services, which includes helping you monitor your progress, evaluate your results and compare your financial position to your competitors. Our team of industry professionals dedicates 100% of their time to serving banks, relying on a philosophy based on strong client relationships, responsive personnel, and timely service. From the very start of our relationship, we analyze potential scenarios so you can develop a comprehensive plan for your future.', 'Mr. Jerry McMillon, CPA', 'jerry.mcmillon@claconnect.com', '(972) 383-5700', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000005b', 'CME Group', 'https://www.cmegroup.com/', '20 S Wacker Dr Chicago, IL 60606-7431 As the world’s leading derivatives marketplace, CME Group is where the world comes to manage risk. We enable clients to trade futures, options, cash and OTC markets, optimize portfolios, and analyze data – empowering market participants worldwide to efficiently manage risk and capture opportunities.', 'Mr. Brian Gierke', 'brian.gierke@cmegroup.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000005c', 'Coconut Software', 'https://www.coconutsoftware.com', '1 University Ave Ste 1901 Toronto, ON M5J 2P1 CANADA Coconut Software is a leading customer engagement platform that orchestrates effortless digital and in-person banking experiences for financial institutions. The company’s appointment scheduling, in-branch queuing, and video banking solutions tackle critical challenges head-on, while building customer loyalty and improving CSAT. Coconut Software creates measurable business value by helping clients achieve their revenue goals, optimize workforce planning, and streamline branch traffic. Visit coconutsoftware.com to learn more.', 'Katherine Regnier', 'katherine.regnier@coconutsoftware.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000005d', 'CodeFi Solutions, LLC', 'https://codefi.com', '109 Cleveland Ave Cocoa Beach, FL 32931-4009 CodeFi’s construction loan administration software platform, Presidium Solutions, enhances liquidity, efficiency, and profitability for lenders and developers. As the most comprehensive and largest of its kind in the industry, Presidium provides innovative loan management solutions with real-time portfolio tracking and automated draw inspections, streamlining administration. A comprehensive cloud platform connects stakeholders across the real estate lifecycle, offering tools for financing, project financial optimization, construction billing simplification, and asset management. We drive transparency, automation, and smarter decision-making in construction finance.', 'Mr. Bob Scales', 'bscales@codefi.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000005e', 'Cohen & Company Securities', 'https://cohensecurities.com/', 'Cohen &amp; Co Securities specializes in capital markets, combining product knowledge with market insights to deliver customized strategies that foster growth and build lasting partnerships.', 'Mr. Rob K. Averwater', 'raverwater@cohensecurities.com', '(561) 939-1225', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000005f', 'Colliers Debt & Structured Finance', '', 'Kelsey.Friesz@colliers.com https://www.colliers.com/en/services/colliers-mortgage (612) 376-4000 90 S 7th St Ste 4300 Minneapolis, MN 55402-4108 Colliers Debt &amp; Structured Finance Bank Participation Program connects developers and participating lenders through financing solutions designed to meet both borrower and bank priorities. For borrowers, we assemble flexible debt transactions can incorporate multiple capital sources and financing alternatives. For lending institutions, we provide a complete underwriting and documentation package that supports independent credit review and efficient decision-making.', 'Ms. Kelsey Friesz', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000060', 'Column NA', 'https://column.com', '945 Steiner St San Francisco, CA 94117-1619 Column is an OCC-regulated, nationally chartered bank built to serve banks, financial institutions, and money services businesses.

Led by Founder &amp; CEO William Hockey, who previously founded and served as President of Plaid.

Today, Column manages $8BN+ of Deposits and $200MM+ run-rate net income (70%+ ROE)', 'Mr. Paolo Bernasconi', 'penrico@column.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000061', 'Commerce Street Capital, LLC', 'https://www.commercestreetcapital.com', 'Commerce Street Capital ("CSC") is a FINRA/SIPC member broker/dealer and premier investment banking firm serving financial institutions and middle-market companies. CSC''s Financial Institutions Group ("FIG") practice centers exclusively on serving the needs of the financial services sector which includes mergers &amp; acquisitions, debt/equity raises, regulatory advisory plans, private placements, valuations/fairness opinions, bank capital raising, SBIC fundraising, corporate and real estate finance, and due diligence services.', 'Mr. William D. Gross', 'tgross@cstreetholdings.com', '(214) 545-6800', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000062', 'Compass Consulting', 'https://www.compassconsulting.com', '1700 Aviara Pkwy Unit 131176 Carlsbad, CA 92013-7049 Compass Consulting helps Community and Regional Banks realize their Financial Advice platforms’ full potential and gain a competitive advantage through Metrics-Driven Strategic Ideation and Operations Consulting. If your Bank wants to create a financial advice platform or increase profitability, client &amp; employee retention, and achieve breakthrough performance in your existing advice platform, we can help. Our team of experts will deliver best-in-class strategies, assist in implementing solutions, and ensure exceptional results.', 'Ms. Hillary Salgado', 'hillary@compassconsulting.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000063', 'Compliance Alliance, Inc.', 'https://www.compliancealliance.com', 'Compliance Alliance is an all-inclusive resource, providing quality compliance documents, personalized attention by a compliance hotline and clear-cut compliance reviews. Not only does Compliance Alliance provide the documents necessary to be sure that banks are compliant, but the additional products and services serve as the bank''s researcher, advisor, reviewer, and document creations specialist.', 'Mr. Scott Daugherty', 'scott@compliancealliance.com', '(888) 353-3933', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000064', 'Computer Transition Services, Inc.', 'https://www.ctsinet.com', 'Computer Transition Services, Inc. (CTSI) is an IT Consulting Firm with over 30 years of experience in the financial industry. CTSI provides customized technology solutions for community banks including security, business continuity, disaster recovery and best practices to support desired business outcomes. Our highly trained team utilizes strategic IT planning to help you meet your long-term business goals.', 'Mr. Michael Vaught', 'mvaught@ctsinet.com', '(806) 793-8961 x222', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000065', 'Condley and Company, L.L.P.', 'https://www.condley.cpa', 'Established in 1939, the CPA firm of Condley and Company, L.L.P. has been providing comprehensive accounting and business consulting services to Texas banks for more than three decades including external audits, consulting, compliance, loan review, tax accruals, taxation guidance, internal audits and others. We offer clients the benefit of our membership in the Aprio Alliance, a national association of independent accounting firms. We serve a wide geographical region, and we would like to serve you.', 'Mr. Ryan Gibson, CPA, CIA, CFSA', 'ryan.gibson@condley.cpa', '(325) 677-6251', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000066', 'CoNetrix', 'https://www.conetrix.com', 'CoNetrix is a trusted expert in securing technology environments through evolving cybersecurity and compliance challenges. We help financial institutions with solutions designed to validate controls, maintain compliance, and improve overall security posture. CoNetrix offers managed IT services, SOC services, cybersecurity assessments, IT audits, penetration testing, M365 security, and VISO consulting. Tandem is a software developed by CoNetrix for managing information security and compliance programs. Tandem offers efficient products for risk assessment, business continuity planning, vendor management, cybersecurity assessments, policies, incident management, phishing awareness training, and more! Contact us to explore how we can support your IT strategy and regulatory compliance. Visit Conetrix.com | Tandem.app or call 800-356-6568.', 'Mr. Kyle Anderson', 'kandersen@conetrix.com', '(806) 687-8600', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000067', 'Convergint Technologies', 'https://www.convergint.com', 'Convergint offers a suite of project delivery tools to ensure that your financial assets, customers, and employees are protected. With a deep understanding of regulatory compliance requirements and internal operations, we deploy scalable solutions to meet the evolving needs of financial institutions. Convergint is committed to partnering with your branch network to optimize security and operational efficiencies while managing costs and enhancing the customer experience.', 'Mr. Reece Tarwater', 'reece.tarwater@convergint.com', '(877) 653-5252', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000068', 'Cornerstone Advisors, Inc.', 'https://www.crnrstone.com', 'Cornerstone Advisors delivers consulting services, industry insights and executive forums aimed at helping banks improve their profitability and performance, quickly and efficiently. Armed with nearly two decades of experience, the philosophy that financial institutions can''t improve what they don''t measure, and an authoritative database of performance metrics and vendor contract data, Cornerstone can show banks how laser-focus measurement can lead to more competitive business strategies, better vendor contracts, educated technology decisions and purposefully re-engineered processes.', 'Nikki Ludwig', 'nludwig@crnrstone.com', '(480) 423-2030', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000069', 'CorServ, Inc.', 'https://www.corservsolutions.com', 'CorServ provides a modern, turnkey payment card program. Community Bank Partners recognize over 6.5% ROA without adding staff. Additionally, Bank Partners value better credit card servicing options and the newest payment card technology.', 'Mr. Jonathan Wright', 'jwright@corservsolutions.com', '(817) 296-2048', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000006a', 'CPI Card Group', 'https://cpicardgroup.com', '556 Metroplex Dr Nashville, TN 37211-3133 CPI is a payments technology company that is integral to the payments ecosystem. CPI’s connections, people, and solutions enable payments for a broad and expanding customer base including thousands of U.S. financial institutions, processors, fintechs, prepaid program managers and more, and these customers count on us to deliver what''s next. Learn more at www.cpicardgroup.com', 'Mr. Joe Traynor', 'jtraynor@cpicardgroup.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000006b', 'CRC Group', 'https://www.crcgroup.com', 'CRC Group is a leading, independent pure-play brokerage and underwriting specialty insurance distributor. Our team is here to add value for clients and provide specialty insights and solutions faster, with quality service to take you further.', 'Mr. Zac Crosley, CPCU, ARM, PRC', 'zcrosley@crcgroup.com', '(214) 239-6994', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000006c', 'Credit Risk Management Technology', 'https://portfoliowatch.co', 'Portfolio Watch is a better way for commercial lenders to manage credit risk in their existing loan portfolios. Portfolio Watch provides three critical functions - automated financial statement collection, spreading and covenant testing of the borrowers, automated annual review memo creation and an algorithm driven early warning system to identify a potential problem loan before the borrower misses a payment.', 'Mr. Walt Postlewait', 'wpostlewait@portfoliowatch.co', '(936) 585-4321', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000006d', 'Crews&Associates, Investment Bankers', 'https://www.crewsfs.com', 'Crews is a full-service investment banking firm with over 130 registered representatives serving individuals and institutional accounts in all 50 states. Our firm specializes in trading fixed-income securities, including municipal and corporate bonds, government agency bonds, U.S. Treasury bonds, mortgage-backed securities, and mutual funds. With public finance offices around the country, our firm also underwrites new issue municipal bonds and private placements. Crews operates as a wholly owned subsidiary of First Security Bancorp which has over $8 billion in assets and more than $1.4 billion in capital.', 'Mr. Tim Craig', 'tcraig@crewsfs.com', '(501) 978-7948', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000006e', 'CrossCheck Compliance LLC', 'https://www.crosscheckcompliance.com', 'CrossCheck Compliance LLC is a nationwide regulatory compliance and risk management consulting firm focused on providing regulatory compliance, internal audit, fair lending, loan review, due diligence, and litigation support services for the financial services industry. The firm’s professionals have deep regulatory understanding and operations experience to develop effective compliance strategies and deliver high impact outcomes for clients.', 'Ms. Lauren Alvarado', 'lalvarado@crosscheckcompliance.com', '(972) 896-9046', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000006f', 'Crosswise', 'https://www.crosswise.io/', '8893 Meadowview Rd Park City, UT 84098-5634 Crosswise is the AI for Risk &amp; Compliance that helps banks automate compliance workflows while staying agile amid regulatory change. Its adaptive knowledge base updates weekly with federal and state regulations to keep institutions compliant and audit-ready. The automation engine turns procedures into dynamic workflows that adjust automatically as requirements evolve. With a natural language interface via Teams, Slack, email, or platform, banks empower compliance and risk teams, accelerate audits, and strengthen trust. Learn more at www.crosswise.io.', 'Mr. Alexander Statnikov', 'alexander@crosswise.io', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000070', 'Crowe LLP', 'https://www.crowe.com', 'Crowe LLP is a public accounting, consulting and advisory firm with offices around the world. Crowe uses its deep industry expertise to provide audit services to public and private entities. The firm and its subsidiaries also help clients make smart decisions that lead to lasting value with its tax, advisory and consulting services.', 'Mr. Mark Heffner', 'mark.heffner@crowe.com', '(214) 777-5200', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000071', 'CSI/Velocity', 'https://www.csiweb.com', 'CSI is a leading provider of end-to-end financial technology solutions, helping U.S. community and regional financial institutions compete and grow. Backed by more than 60 years of industry expertise, CSI delivers a comprehensive suite of capabilities spanning core banking, digital banking, lending, payments, risk and compliance, and managed IT and cybersecurity services. CSI gives financial institutions the flexibility to deploy an open, fully integrated core platform or best-of-breed, core-agnostic solutions, enabling them to modernize on their terms. Known for its high-touch service, CSI helps financial institutions navigate disruption, strengthen account holder relationships, and drive growth in an increasingly digital-first financial landscape. To learn more, visit', 'Mr. Saxon Prater', 'saxon.prater@csiweb.com', '(800) 545-4274', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000072', 'Curated Cyber', 'https://www.curatedcyber.com', 'Curated Cyber provides vCISO (Virtual Chief Information Security Officer) services, and we specialize in community baking. We help bridge the gap between business, IT, Compliance, and Governance. We help community banks with compliance and governance needs.', 'Mr. Brandon Gettert', 'brandon@curatedcyber.com', '(817) 264-7197', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000073', 'CyberAssurance', 'https://cyberassurancenow.com', '1417 Heartland St Fairfax, IA 52228-9001 CyberAssurance is a cybersecurity and IT risk advisory firm serving financial institutions nationwide. We help banks identify security gaps, reduce cyber risk, and prepare for regulatory exams through IT audits, penetration testing, social engineering, vCISO services, and risk assessments aligned to FFIEC, NIST CSF 2.0, CRI Profile or CIS Controls. Our team delivers practical, risk-based recommendations that strengthen controls, improve resilience, and give leadership clear visibility into cybersecurity posture.', 'Mr. John Moeller', 'john.moeller@cyberassurancenow.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000074', 'Cyberwolf', 'https://cyberwolf.io', '525 North Ave NE Ste 250 Atlanta, GA 30308-8006 Cyberwolf is an exclusive cybersecurity suite that protects the private lives of VIPs, such as corporate executives, board members, high-net-worth individuals and their families. Imagine having a personal bodyguard for your entire online life, without compromising on convenience or privacy, so you can relax and focus on what matters. Our personal cybersecurity service combines the best enterprise-grade security technology with a collective of cyberexperts ready by your side.', 'Ms. Tine Van Den Borne', 'tvandenborne@cyberwolf.io', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000075', 'Daitaas LLC', 'https://www.daitaas.com', 'Daitaas™ is a data science company with offices in Memphis, Texas and England. Founded by ag insiders—farmers and farm financial analysts with firsthand knowledge and ag experience, Daitaas believes that modern farm financial management is the missing ingredient to consistent profitability today. Our goal is to enhance the farmer’s knowledge of their total operation through the power of data, removing the unknown—and its accompanying stress—to make more empowered decisions and improve profitability.', 'Mr. Joe Jennings', 'joe@daitaas.com', '(901) 820-4466', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000076', 'Darling Consulting Group', 'https://www.darlingconsulting.com', '260 Merrimac St Towle Building Newburyport, MA 01950-2192 For over 40 years, Darling Consulting Group’s only business has been to help leading banks manage balance sheets effectively. DCG’s experts provide risk management consulting and strategic advisory services to institutions nationwide, including independent strategic asset liability management consulting, model risk management and validation, capital planning, behavioral modeling, education, and a suite of on-demand decision-making tools (liquidity stress testing, deposit and loan analytics, and credit stress testing). Our teams bring clarity to the complex.', 'Ms. Kelly Coletti', 'kcoletti@darlingconsulting.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000077', 'Data Business Equipment, Inc.', 'https://www.dbeinc.com', 'Data Business Equipment, Inc. (DBE), a family-owned company rooted in exceptional service, has been bringing transforming solutions to the market since 1968. DBE supports our clients through differentiating products and services to improve their position in the market. From thoughtful solution consultation, to implementation, service and ongoing support, everything DBE does is designed to drive the best possible experience and outcomes for our clients.', 'Mr. Scott Milliken', 'smilliken@dbeinc.com', '(800) 373-3000', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000078', 'Data Driven Partners LLC', 'https://www.ddplendingleads.com', '417 Main St Ste 1834 Little Rock, AR 72201-3801 We are the creators of Lending Leads, a relationship-based, lead generation and competitive intelligence platform built for bank leaders, lenders and compliance officers. Our platform provides actionable data to banks and other financial institutions to help them execute their growth strategies, compete in their market, and build relationships with prospects and customers.', 'Ms. Tammy Been', 'tammy@ddplendingleads.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000079', 'DCI (Data Center, Inc.)', 'https://www.datacenterinc.com', 'DCI is the developer of the award-winning iCore360® core banking software, plus iCoreGO® digital banking and fintech processing solutions for community financial institutions nationwide. We’re privately owned by our community bank clients, with several serving as board members and user group leaders. DCI offers private ATM network/card management, FrontLine teller software, custom data analytics, risk/vendor management, and more. And, by providing digital and Fintech deliverables that integrate with any system – even those of our competitors – we offer unique partnerships to both existing and prospective customers. For additional information about DCI, visit www.datacenterinc.com or contact info@datacenterinc.com', 'Jesse Tosten', 'jtosten@datacenterinc.com', '(620) 694-6800', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000007a', 'DeepTarget, Inc.', 'https://www.deeptarget.com/', '600 Boulevard South SW Ste 104 Huntsville, AL 35802-2175 DeepTarget is a digital experience platform that helps banks acquire
new account holders, cross-sell with precision and retain relationships
through personalized digital engagement. Powered by AI and core
data, DeepTarget delivers targeted offers across digital banking,
email and other channels—turning everyday interactions into
measurable growth. Financial institutions use DeepTarget to replace
generic outreach with timely, relevant messaging that drives
deposits, loans and long-term loyalty.', 'Ms. Cindy Davis', 'cindy@deeptarget.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000007b', 'DefenseStorm', 'http://defensestorm.com', 'DefenseStorm serves US regional banks and credit unions exclusively. Our GRID Active platform unifies MDR, risk and governance, backed by our 24×7 SOC of banking experts who act as an extension of your staff. Together, we reduce noise, simplify reporting, and strengthen institutional trust amid rising cyber threats and regulatory pressure.', 'Mia Callicutt', 'mia.callicutt@defensestorm.com', '(470) 519-0020', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000007c', 'DEI, Incorporated', 'https://www.dei-corp.com', 'DEI is a national design/build company that goes beyond the expected to turn your project into a growth opportunity. We create sales environments by incorporating all aspects of facility planning, from site search &amp; selection, strategic analysis &amp; planning through architecture, construction, interior design, branding &amp; retail concept design. At DEI, we design and build to grow your business.', 'Mr. Greg Oates', 'goates@dei-corp.com', '(325) 669-2131', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000007d', 'Deltra Systems LLC', 'https://www.deltrasystems.com', 'Deltra Systems Mission is to provide and support our customers with industry-leading IT products, procedures and services that are proven to be secure, compliant and most importantly, cost-efficient no matter the size of their organization. Deltra System provides IT Compliance that helps accomplish its objectives by systematically evaluating and assessing risk management, controls, compliance mechanisms and oversight processes.', 'Mr. Jesse Garcia', 'jesseg@deltrasystems.com', '(210) 977-8122', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000007e', 'Deluxe Banker''s Dashboard', 'http://deluxe.com/bankers-dashboard/', '303 Kings Cir Myrtle Beach, SC 29572-4719 Banker’s Dashboard offers an at-a-glance view of your latest performance metrics, enabling you to spot revenue opportunities, make informed decisions and create a culture of accountability. Powered by Deluxe, this performance management platform unlocks new possibilities for daily branch management, budgeting, forecasting, board reporting, loan price optimization and more.', 'Mr. Dick Burch', 'dick.burch@deluxe.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000007f', 'Diebold Nixdorf', 'https://www.dieboldnixdorf.com/en-us', 'o	Diebold Nixdorf, Incorporated (NYSE: DBD) is a world leader in enabling connected commerce for millions of consumers each day across the financial and retail industries. As an innovation partner for nearly all of the world’s top financial institutions and global retailers, Diebold Nixdorf delivers unparalleled solutions that are essential to evolve in an ‘always on’ consumer landscape. Diebold Nixdorf has a presence in more than 130 countries with approximately 24,000 employees worldwide. Visit www.DieboldNixdorf.com.', 'Mrs. Heather Minock', 'heather.minock@dieboldnixdorf.com', '(512) 569-5924', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000080', 'Digerati AI Inc.', 'https://digeratiai.ai', '2914 S Shepherds Gln Wichita Falls, TX 76308-5449 Digerati AI Inc creates tech to maximize engagement and value of each customer. Our flagship product, Banking Intelligence Platform (BIP) consists of modules that give community sized banks the AI tooling advantages that the mega banks like CITI, JPMC, BoA and Vanguard have to increase operational efficiency, increased revenue, and improved margins.', 'Alan Sizemore', 'alan@digeratiai.ai', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000081', 'Doeren Mayhew', 'https://www.doeren.com', 'At Doeren Mayhew, we’re fueled by our passion to help you grow confidently. A top 50 accounting firm, we serve over 500 financial institutions nationwide with a variety of tailored solutions to help drive long-term success.

Our pros put their 45-plus years of first-hand experience to work to help community banks tackle challenges, unveil opportunities and navigate regulatory complexities. Rely on us to provide a variety of services, including external and internal audits, regulatory compliance, loan reviews, M&amp;A strategic advisory and IT risk management.', 'Mr. John M. Miller, CPA', 'jmiller@doeren.com', '(248) 244-3074', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000082', 'Dormakaba USA', 'https://www.dormakaba.com/us-en/offering/products/safe-locks', '1525 Bull Lea Rd Ste 100 Lexington, KY 40511-1227 dormakaba: Scalable safe lock solutions for branch and ATM security

dormakaba helps banks and credit unions secure every access point—from teller drawers and vaults to ATMs and cash rooms. Our safe lock portfolio includes trusted electronic, mechanical, and IP-enabled options designed to support branch standardization and improve access control.

With a legacy built on brands like Kaba, La Gard, and Mas Hamilton, dormakaba solutions offer advanced features like audit trails, centralized access management, and One Time Code (OTC) support. Whether managing access at a single location or across a nationwide network, security and facilities teams can count on dormakaba to deliver dependable protection and efficient operations.

Serving customers in over 130 countries and backed by 145 years of security expertise, dormakaba is a leader in high-security access solutions for the financial sector.', 'Ms. Caitlin Bradshaw', 'caitlin.bradshaw@dormakaba.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000083', 'Dorsey & Whitney LLP', 'https://www.dorsey.com', 'More than 250 Dorsey lawyers comprise the firm''s Banking and Financial Institutions Group, advising clients on matters around the globe. Our clients include banking organizations, investment banks, broker-dealers, investment funds and other financial institutions. Our work includes representation in complex lending transactions, bankruptcy and restructuring matters, corporate trust transactions and disputes, regulatory issues, consumer financial matters and other practices specific to financial institutions.', 'Mr. Larry A. Makel', 'makel.larry@dorsey.com', '(214) 981-9916', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000084', 'Dykema Gossett PLLC', 'https://www.dykema.com/', '112 E Pecan St Ste 1800 San Antonio, TX 78205-1521 Dykema’s Financial Services practice is recognized nationally for its comprehensive legal services, encompassing litigation, regulatory compliance, transactional support, and strategic counsel tailored to the evolving needs of financial institutions', 'Mr. Jacobus M. Vollebregt', 'jvollebregt@dykema.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000085', 'Eide Bailly LLP', '', 'nhood@eidebailly.com https://www.eidebailly.com/industries/financial-services (325) 672-4000 400 Pine St Ste 600 Abilene, TX 79601-5138 At Eide Bailly, our team understands that today’s decisions impact your future. As a trusted financial services advisor for over 75 years, our team helps financial institutions ensure compliance, improve operations, and mitigate risk all while navigating consolidation and digital transformation for peak performance. We can help you simplify the complex and focus your attention where it belongs: on your customers.', 'Ms. Natalie Hood', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000086', 'Empyrean Solutions', 'https://www.empyreansolutions.com', 'Empyrean Solutions empowers the dynamic CFO with a unified treasury, FP&amp;A and analytics platform that brings ALM, liquidity, budgeting &amp; planning, profitability, CECL, and behavioral modeling together in one modern ecosystem. With ongoing investments in advanced AI-driven automation, we help financial institutions of all sizes to move faster, operate more accurately, and scale with confidence. By centralizing data and delivering connected insights, Empyrean enables institutions to strengthen performance, ensure regulatory confidence, and better serve their stakeholders and communities.', 'Ms. Andrea Chilczuk', 'andrea.chilczuk@empyreansolutions.com', '(602) 803-4520', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000087', 'ePayResources', 'https://www.epayresources.org', 'ePayResources® has been empowering financial institutions and businesses to be informed, compliant, and competitive in payments for 50 years. As an innovative Payments Association and a founding sponsor of the Center for Payments, we provide emerging and legacy payments expertise, professional development, and industry leadership through education, publications, compliance support, risk management, and advocacy. Our staff of nationally accredited payments and risk professionals provides situational analysis and response guidance on our Payments Answerline™ and keeps you informed of industry developments that impact operational processing, fraud detection, and your bottom line. Our subsidiary, ePayAdvisors™, provides payments audits, risk assessments, and consulting. Visit epayresources.org and follow us on X (@ePayResources_), LinkedIn, Facebook, Instagram, and YouTube.', 'Ms. Yasmin Porcaro, AAP', 'yporcaro@epayresources.org', '(800) 475-0585x1201', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000088', 'Equifax', 'https://www.equifax.com', 'Equifax provides market leading solutions in data, analytics and technology.  Equifax is engaged in helping financial institutions make critical decisions in: 
·       Consumer and Commercial credit risk
·       Identity &amp; Fraud
·       Data-Driven Marketing:  Prescreen and ITA for new credit products, deposit &amp; Wealth Management growth, for consumer and commercial prospects
·       Verification &amp; Workforce Management
·       Automotive specific solutions for competitive benchmarking
We’re more than credit reports at Equifax.  If you haven’t spoken to us recently, please reach out.', 'Mr. Scott Anderson', 'scott.anderson1@equifax.com', '(972) 565-3151', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000089', 'Equipifi', 'https://www.equipifi.com', '8660 E Hartford Dr Ste 100 Scottsdale, AZ 85255-2581 equipifi is a fintech company providing the credit infrastructure for modern banking. Trusted by leading banks and credit unions, equipifi delivers Buy Now, Pay Later (BNPL) as a native banking capability embedded within digital banking platforms. The result is durable customer engagement, sustainable growth, and a more competitive consumer lending experience delivered within the institution’s own ecosystem.', 'Jazzy Zhu', 'jazzy.zhu@equipifi.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000008a', 'Ernst & Young LLP', 'https://www.ey.com', 'EY is building a better working world by creating new value for clients, people, society and the planet, while building trust in capital markets.

Enabled by data, AI and advanced technology, EY teams help clients shape the future with confidence and develop answers for the most pressing issues of today and tomorrow.

EY teams work across a full spectrum of services in assurance, consulting, tax, strategy and transactions. Fueled by sector insights, a globally connected, multidisciplinary network and diverse ecosystem partners, EY teams can provide services in more than 150 countries and territories.

All in to shape the future with confidence.
              
EY refers to the global organization, and may refer to one or more, of the member firms of Ernst &amp; Young Global Limited, each of which is a separate legal entity. Ernst &amp; Young Global Limited, a UK company limited by guarantee, does not provide services to clients. Information about how EY collects and uses personal data and a description of the rights individuals have under data protection legislation are available via ey.com/privacy. EY member firms do not practice law where prohibited by local laws. For more information about our organization, please visit ey.com.', 'Mr. Maurice Berbel', 'maurice.berbel@ey.com', '(917) 593-4718', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000008b', 'Estateably', '', '100 N Addison Ave Elmhurst, IL 60126-2848 Estateably is a cloud-based platform that empowers organizations to transform their trust administration and estate settlement practices. We help over 1,000 firms across the US and Canada streamline estate work, manage fiduciary tasks and workflows, track stakeholders and assets, and deliver exceptional client service. With SOC2 Type II certification, and a commitment to the highest security standards, we''ve earned the trust of professionals who demand both security and excellence in their fiduciary practice management', 'Graeme Jones', 'gjones@estateably.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000008c', 'EverFi, Inc.', 'https://www.everfi.com', 'Since 2008, Everfi has connected businesses to communities by providing
essential education that builds trust and drives measurable impact. Using
digital and offline resources, the company delivers personal finance and
life skills education to millions of learners annually in both K-12 schools
and broader communities. Today, hundreds of organizations, including
financial institutions, professional sports leagues, and healthcare systems,
rely on Everfi to deliver measurable outcomes that benefit learners and
drive business impact.', 'Ms. LaFaith Washington', 'lwashington@everfi.com', '(713) 503-2439', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000008d', 'Evo Asset Consulting', 'https://www.joinevo.com', '114 S 140 W Lindon, UT 84042-1968 Evo Asset Consulting assists financial institutions in their REO disposition process by providing asset consulting services. They handle distressed assets, coordinate property maintenance, and facilitate transactions to maximize recovery value, ensuring smooth operations while limiting liability. We work closely with financial institutions to streamline foreclosure processes, optimize asset disposition, and provide expert guidance in real estate-owned (REO) property management.', 'Ms. Madisyn Mower', 'maddy@joinevo.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000008e', 'Federal Home Loan Bank of Dallas', 'https://www.fhlb.com/home', 'The Federal Home Loan Bank of Dallas (FHLB Dallas), with total assets of $129.4 billion as of September 30, 2024, serves approximately 800 members and associated institutions across our five-state District of Arkansas, Louisiana, Mississippi, New Mexico and Texas. FHLB Dallas provides financial products and services including advances (loans to members) and grant programs for affordable housing and economic development.', 'Mr. Stephen Otto', 'steve.otto@fhlb.com', '(214) 441-8711', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000008f', 'Federal Protection, Inc.', 'https://www.federalprotection.com', 'Federal Protection is trusted as the Financial Industry Security Specialists. Serving since 1969 Federal is a proven innovator in security, bank equipment and ATM/ITMs. Today, we offer the latest solutions for branch development, ATMs, ITMs and physical &amp; electronic security. With over 300 security specialists, Federal Protection is the largest security provider of its type in the Central United States. With an in-house 24/7/365 Federal Response Center Monitoring Stations, as well as Federal Construction, Inc. specializing in financial construction; Federal is truly a turn-key solution.', 'Mr. Eric Hoover', 'ehoover@federalprotection.com', '(918) 857-4525', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000090', 'Fenimore Kay Harrison LLP', 'https://www.fkhpartners.com', 'We are a law firm built for community banks. We specialize in providing legal services to banks, thrifts, and other financial institutions throughout the United States on a full range of corporate, securities, governance and regulatory matters. We believe that clients have a right to expect the exceptional from us - in service, value and results - and our goal is to not only meet but exceed that expectation on every matter for every client.', 'Mr. Chet A. Fenimore', 'cfenimore@fkhpartners.com', '(512) 583-5900', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000091', 'FHN Financial', 'https://www.fhnfinancial.com', 'For 160 years, FHN Financial has been dedicated to helping our customers achieve their fixed income goals. Whether you want to buy or sell securities, need help managing your balance sheet, or seek to limit interest rate risk, we can deliver the appropriate products and services, precisely tailored to your needs. We’re confident you won’t find a more responsive, customer-focused fixed income shop anywhere.

FHN Financial is an industry leader in fixed income sales, trading, and strategies for institutional customers in the US and abroad. We also provide investment services and balance sheet management solutions. With an average daily trading volume of $4.2 billion, FHN Financial transacts business with approximately 45% of all US banks with portfolios over $100 million. (For 24 month period ending 4Q24.)', 'Mr. Trae Winston', 'trae.winston@fhnfinancial.com', '(901) 435-8757', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000092', 'Fibertown Data Centers', 'https://fibertown.com', '110 N Main St Bryan, TX 77803-3234 Fibertown Data Centers ensure mission critical data is safe and accessible 24/7/365.  Our Data Centers are located outside of the FEMA 500-year floodplain and storm impact zones in Bryan and Houston and provide high performance, maximum reliability, and best in class redundant infrastructure, maintaining 100% survivability during ALL “weather impacting events” for 28 years.  Fibertown delivers 100% uptime SLA for power, cooling, and connectivity; FREE remote “hands and eyes” services 24/7/365; and 1 minute human response time.', 'Ms. Jill Rowe', 'jrowe@fibertown.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000093', 'Finance. Risk. Unified.', 'https://www.financeriskunified.com', 'Two words – Strategic Visibility. 
 
It’s what today’s growth-oriented regional and community bank executives need to manage today’s growing headwinds, exponential change, and unprecedented opportunities. And it’s Strategic Visibility that will bring much-needed growth, efficiency, agility, and overall relevance into focus.
 
And Strategic Visibility is what Finance.Risk.Unified delivers. 
 
Built from a consortium of experienced ex-bankers who have pooled together over four decades of collective expertise and resources, Finance.Risk.Unified. provides unprecedented forward-looking insights by unifying Risk Quantification and Finance Optimization into a single view.
 
This is achieved through our technology solution suite, which includes, but is not limited to, enterprise-wide products that improve how our customers achieve their strategic objectives and comply with regulations in a rapidly evolving environment that requires digital transformation, data-driven insights, and the modernization of inefficient processes.
 
This is, and has always been, our primary goal –– to provide these bank leaders the freedom to get out of react mode and back into the highly-strategic role they signed up for so they can focus precious energy toward optimizing risk, executing strategy, and achieving their goals.
 
We know what your bank is up against. We’ve been there. And we’re here for you.', 'Mr. John Drew', 'john@financeriskunified.com', '(713) 515-1285', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000094', 'Financial Systems Corp', 'https://financialsystemscorp.com', '1701 Quincy Ave Ste 5 Naperville, IL 60540-6688 Financial Systems Corp has been in the financial services business for 40 years selling and servicing all equipment in our portfolio. We specialize in ATM’s and ITM’s installation and core integrations. Financial Systems Corp is a one stop dealer that can help with the build out of a new branch by providing all the physical security equipment needed to the cash handling and even security cameras. 
 Equipment/Systems.', 'Mr. Bobby Combs', 'bobbycombs@financialsystemscorp.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000095', 'FinCyberTech', 'https://www.fincybertech.com', '210 S Old Woodward Ave Birmingham, MI 48009-6120 Many local community banks struggle to afford a full-time cybersecurity expert. FinCyberTech provides seasoned professionals and tailored cyber solutions without full-time overhead. Our Cyber Techs implement robust strategies, ensuring your measures evolve with threats, safeguarding assets, reputation, and trust. Additionally, our cloud-hosted Cyber Risk Compliance platform, designed for financial institutions, ensures a smooth transition from FFIEC''s Cybersecurity Assessment Tool (CAT) to NIST CSF 2.0 framework.', 'Ms. Jennifer Fiebelkorn', 'jen@fincybertech.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000096', 'Finley', 'https://www.finleycms.com', '2261 Market St San Francisco, CA 94114-1612 Finley’s software simplifies credit management banks and credit funds. By automating due diligence, ensuring compliance, and streamlining ongoing reporting, Finley helps ensure that capital is always available when companies need it. Finley’s investors include CRV, Bain Capital Ventures, Y Combinator, Haystack, and Nine Four Ventures.', 'Mr. Bryant Massey', 'bryant@finleycms.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000097', 'Finovifi', 'https://finovifi.com', '14302 Spanish River Ln Cypress, TX 77429-6898 Finovifi is redefining the future of financial technology, equipping community financial institutions with AI-powered fraud prevention, compliance automation, and core processing solutions. As a fintech innovator, we provide financial institutions with cutting-edge technology to protect their customers, streamline operations, and future-proof their banking infrastructure.', 'Mr. Gilbert Elizondo', 'gelizondo@finovifi.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000098', 'First Bankers'' Banc Securities, Inc.', 'https://FBBSinc.com', '1714 Deer Tracks Trl Ste 110 Saint Louis, MO 63131-1838 FBBS is a full-service broker dealer with a specialization in the fixed income marketplace. We actively trade and position securities, deploying our capital to best-fit client needs. FBBS employees possess decades of experience that allow us to identify and interpret market conditions to anticipate potential impact on the investment portfolio.', 'Giovanny Rozo', 'grozo@FBBSinc.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000099', 'First Rate, Inc.', 'https://www.firstrate.com', 'First Rate is a trusted WealthTech partner serving bank trust and wealth management institutions with performance reporting, data aggregation, and integrated analytics solutions. With more than 30 years of experience supporting trust departments nationwide, our platform enhances transparency, strengthens client relationships, and drives operational efficiency across the front, middle, and back office. Privately owned and built for long-term partnership, First Rate is committed to stability, service, and practical innovation for today’s bank trust environment.', 'Mr. Phil Gobble', 'philgobble@firstrate.com', '(817) 525-1893', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000009a', 'FIS', 'https://www.fisglobal.com', 'For more than 50 years, leading financial institutions and businesses have relied on FIS financial technology to power their mission-critical operations and drive innovation to propel their growth.  FIS technology unlocks opportunities by bringing clarity to complexity, uniting the disconnected, and allowing businesses to scale. Technology to create harmony in the experience of how money is stored, moved, and put to work.', 'Mr. Marcus Givens', 'marcus.givens@fisglobal.com', '(800) 822-6758', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000009b', 'Fiserv, Inc.', 'https://www.fiserv.com', 'Fiserv, Inc. aspires to move money and information in a way that moves the world. As a global leader in payments and financial technology, the company helps clients achieve best-in-class results through a commitment to innovation and excellence in areas including account processing and digital banking solutions; card issuer processing and network services; payments; e-commerce; merchant acquiring and processing; and the Clover® cloud-based point-of-sale and business management platform.', 'Mr. Kevin M. Tweddle', 'kevin.tweddle@fiserv.com', '(713) 249-1546', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000009c', 'Flock Safety', 'https://www.flocksafety.com', '1170 Howell Mill Rd NW Atlanta, GA 30318 Shaping the Future of Safety, Together.To solve and eliminate crime – you need evidence. Protect your community, business or school 24/7 with coverage that never sleeps.', 'Mrs. Liz Mfoud', 'lizola.mfoud@flocksafety.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000009d', 'FormativGroup', '', '1 N Lexington Ave Ste 450 White Plains, NY 10601 FormativGroup is a technology consulting and implementation partner that helps mid-market organizations modernize workflows, connect fragmented systems, and unlock the full value of their data. We specialize in Salesforce, application integration, data architecture, automation, and AI readiness across regulated industries including banking, insurance, healthcare, and the public sector. By combining strategic consulting, hands-on implementation, and staff augmentation services, we design scalable technology ecosystems that improve operational efficiency, customer experiences, and business decision-making.', 'Mr. Jonathan Tatman', 'Jtatman@formativgroup.io', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000009e', 'Forvis Mazars', 'https://www.forvismazars.us/', 'Forvis Mazars, LLP is an independent member of Forvis Mazars Global, a leading global professional services network. Ranked among the largest public accounting firms in the United States, the firm’s 7,000 dedicated team members provide an Unmatched Client Experience® through the delivery of assurance, tax, and consulting services for clients in all 50 states and internationally through the global network.', 'Mr. Cale Breneman', 'cale.breneman@forvis.com', '(713) 499-4600', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000009f', 'Foundation Risk Partners, Corp', 'https://www.FoundationRP.com', '780 W Granada Blvd Ormond Beach, FL 32174 Foundation Risk Partners is a top-20 national insurance brokerage specializing in tailored risk management and insurance solutions. Our expertise extends to banks, offering comprehensive Employee Benefits, Property/Casualty, Management Liability, and Executive Benefits programs. We understand the unique challenges financial institutions face, delivering innovative, cost-effective strategies to protect assets, mitigate risks, and attract top talent. With a consultative approach and strong carrier partnerships, we help banks achieve stability and growth in an ever-changing financial landscape.', 'Mr. Scott Stevenson', 'scott@foundationrp.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000a0', 'FPS GOLD', 'https://www.fpsgold.com', 'FPS GOLD provides fully customizable banking software products, that are paired with an unmatched customer service team. Our mission is to help your institution meet and exceed your customer''s needs. Allowing your institution to compete, profit and thrive. With over 60 years of experience, our commitment hasn''t changed. Providing you with the best software and services so you can provide your customers with the best experience possible.', 'Mr. Jeff Bosgraaf', 'jbosgraaf@fpsgold.com', '(801) 429-2253', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000a1', 'Fravity Inc', 'https://fravity.ai', '251 County Road 257 Liberty Hill, TX 78642-0000 Fravity''s Agentic AI Copilot can transform Fraud Risk and AML (FRAML) Operations by embedding a team of specialized AI agents directly into your existing workflow.
From consumer onboarding to business fraud, from dispute operations to AML Sanctions - with a single click, our AI agents can automate your investigation process, performing deep check - like KYC/KYB doc analysis, enhanced due diligence, financial analysis, policy and compliance risk, and synthesizing all findings into a clear, actionable recommendation for Analyst or take decisions. All while opening up a Copilot experience for interactive analysis.
This empowers your team to significantly reduce manual work, make faster, more accurate decisions, and scale your operations with confidence, all while using your existing tools and app.
By automating over 80% of the investigative effort, we help you protect your revenue, safeguard your reputation, and turn your onboarding process into a true competitive advantage.', 'Kedar Samant', 'kedar@fravity.ai', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000a2', 'Freedom Profit Recovery, Inc.', 'https://www.fprus.com', 'FPR uniquely stands out with 3 key differentiators: independence, cost-recovery focus, and hands-on consultancy in the areas of document output, telecommunications and electricity management. As independent consultants, FPR’s recommendations are tailored to your needs, free from external influence. Their cost-recovery approach emphasizes cost reduction and process improvements. Unlike typical consultants, FPR partners closely with their clients, ensuring successful goals and cost-effective outcomes.', 'Mr. Brent Newton', 'bnewton@fprus.com', '(972) 650-0700', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000a3', 'FTI Consulting Inc', 'https://www.fticonsulting.com', '2001 Ross Ave Ste 650 Dallas, TX 75201-2923 FTI Consulting is the leading global expert firm for organizations facing crisis and transformation, with more than 8,100 employees in 32 countries and territories.
 
FTI Consulting is dedicated to helping organizations manage change, mitigate risk and resolve disputes: financial, legal, operational, political and regulatory, reputational and transactional. FTI Consulting professionals, located in all major business centers throughout the world, work closely with clients to anticipate, illuminate and overcome complex business challenges and opportunities.', 'Steven Hansen', 'steven.hansen@fticonsulting.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000a4', 'FTSI', '', 'ddulay@ftsius.com https://www.ftsius.com 406 E Huntington Dr Ste 100 Monrovia, CA 91016-3662 FTSI is a minority-owned company and the largest independent provider of custom digital and branch solutions for financial institutions. FTSI offers a full suite of solutions including digital, app development, hardware, software, electronic security, software professional services, project management, service maintenance, cash services, and a range of consultative services. Visit http://www.ftsius.com to learn more.', 'Devin Dulay', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000a5', 'Gallagher', 'https://www.huntfinancialgroup.net', 'Hunt Financial Group is a regional firm, headquartered in Charlotte, North Carolina, with two regional offices and two regional partners. We work exclusively with banks to create, manage, finance (with BOLl), and service supplemental benefit plans for top executives and directors. Through our regional partners and staff, we have extensive experience in the financial services, accounting, qualified, non-qualified benefits, and the banking industry. We are exclusively focused on benefits for banks and BOLl financing of these plans.', 'Mr. Timothy N. Hunt', 'tim_hunt@ajg.com', '(980) 335-2285', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000a6', 'Garnet Capital Advisors', 'https://www.garnetcapital.com', '500 Mamaroneck Ave Harrison, NY 10528-1633 Garnet is a 29-professional, 20-year-old firm focused entirely on loan sale advisory, counting 40+ of the top 50 banks among our clients. We have completed 1800+ transactions with $144+ Billion sold for banks of all sizes. Garnet is active in all loan sale markets: commercial, residential and consumer;  and all performance levels: performing, subperforming, charged-off and bankrupt.  Garnet has been vetted by the FDIC, NCUA and many major banks regarding compliance and information security.', 'Mr. Ernesto Diaz', 'ediaz@garnetcapital.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000a7', 'GCS Technologies, Inc.', 'https://www.gcsaustin.com', 'GCS Technologies designs, deploys and supports technology solutions to ensure your bank runs smoothly and securely. Covering the spectrum of IT needs from cloud migrations to internal and telecommunications systems, and the prevention and remediation of security events, GCS is able to supplement existing teams and infrastructures. Texas Bankers Association has trusted GCS to support their own IT teams and infrastructure since 2013.', 'Mr. Shane Gronniger', 'shane@gcstechnologies.com', '(512) 249-6080', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000a8', 'General Informatics', 'https://geninf.com/', 'Unicom specializes in full-managed and co-managed IT services. Depending on your in-house expertise, we can work with your existing staff to offload burdensome repetitive tasks (like monitoring, vulnerability management, tech support), or we can add value to your existing staff by providing compliance, technology roadmaps and virtual CIO/virtual CISO services. At Unicom, we make IT compliant.', 'Mr. Derek Bell', 'derek.bell@geninf.com', '(281) 496-3606', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000a9', 'Genesys Technology Group, LLC', 'https://www.genesystg.com', 'Genesys was founded in 2007 to be an advocate for the community banker and provides technology consulting that community banks can afford. Genesys takes the guesswork out of core contract negotiations and offers fully managed renewal negotiations as well as core vendor due diligence services. Genesys also specializes in the evaluation of mission-critical Fintech and third-party systems. Furthermore, Genesys provides on-going support such as invoice audit services, conversion management, new product installation and project management.', 'Mr. Chip Ormond', 'chip@genesystg.com', '(678) 208-6030', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000aa', 'GenServe LLC', 'https://genserveinc.com', 'GenServe is the leader in commercial generator maintenance, repairs, upgrades, sales, and emergency response. Our expert team has extensive experience with all makes and models of industrial generators and backup power systems. We are dedicated to ensuring your facility operates efficiently, providing unmatched reliability and peace of mind.', 'Christian Whigham', 'cwhigham@genserveinc.com', '(737) 397-5509', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000ab', 'GMR', 'https://www.gmr1.com', 'Since inception in 1991, GMR has been a pioneer in the field of ATM lighting surveys and has expanded our suite of services to include custom facility inspections, engineered lighting designs and 3D scanning for properties and facilities nationwide. With a commitment to quality, integrity, and customer satisfaction, our proprietary methodologies and seasoned team ensure precise, data-driven results for every project. A certified woman-owned business based in the Dallas-Fort Worth metroplex, we value quality service, innovation, and long-term partnerships, and we are continually evolving to meet the needs of our customers while driving operational excellence.

GMR Security Consulting Group provides independent, proven security consulting with tailored solutions to safeguard organizations from emerging threats and vulnerabilities. We offer services ranging from risk assessments and executive protection to program development and managed services. Our expertise helps clients meet your organization’s unique needs and provide the best protection for your people, property and assets.', 'Adam Guess', 'adguess@gmr1.com', '(972) 772-1284', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000ac', 'Go Abacus Corporation', 'https://www.goabacus.co', 'Go Abacus provides secure, enterprise-grade, on-prem AI infrastructure for financial institutions and regulated enterprises. Our platform enables organizations to centralizing policies, SOPs, model validation documentation, and operational risk controls into a governed decentralized index. With role-based access and immutable audit-grade logs, Abacus ensures AI answers are always proven, compliant, and traceable — helping banks and financial services teams accelerate productivity without compromising security or regulatory confidence.', 'Mr. Jacob Nolen', 'jacob.nolen@goabacus.co', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000ad', 'GoodLabs Studio', 'https://www.goodlabs.studio', '901 N Market Street Suite 100 Wilmington, DE 19801-3041 GoodLabs Studio is a business-first AI engineering firm that combines deep fraud expertise with advanced applied research. Our team unites ex-law enforcement professionals, PhD-level AI researchers, and seasoned engineers to build practical, intelligence-driven solutions for financial crime detection.', 'Mr. Hussain Jaber', 'hjaber@goodlabs.studio', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000ae', 'Grip Security', 'https://www.grip.security', '10308 Table Bluff St Aubrey, TX 76227-3794 Grip Security is a pioneer in SaaS Identity Risk Management, helping organization gain unified visibility and control over every app, credential, and OAuth grant. It detects and prevents risks from shadow software, stale accounts, weak authentication, and misconfigured applications. By integrating with existing tools it empower teams to secure SaaS complexity at scale.', 'Mr. Jonathan Giddings', 'jonathan.giddings@grip.security', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000af', 'Guardian Technology Group', 'https://mygtg.com', '807 Canada St Jacksonville, TX 75766-2719 At Guardian Technology Group (GTG), we deliver more than checklists - we build cybersecurity programs that leadership teams can rely on, employees respect, and boards understand. From vCISO advisory to audit readiness, our modular services are designed to meet you where you are and take you where you want to be. Veteran-Owned. Mission-ready. Leadership-driven. Keys words: IT Services, Security Services/Fraud Prevention, Technology Audits &amp; Risk Assessments', 'Mr. Dan Sitton', 'dan.sitton@mygtg.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000b0', 'Guild Mortgage', '', 'https://www.guildmortgage.com 8074 Precinct Line Rd Colleyville, TX 76034-7547 Guild Mortgage is a leading independent mortgage lender with more than 60 years of experience, known for combining local service with a broad range of home financing solutions. In Texas, Guild supports borrowers whose needs may extend beyond traditional lending, including Non-QM options for self-employed or credit-complex clients and reverse mortgage solutions for older homeowners seeking added flexibility in retirement.', 'Ms. Angie Aldredge', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000b1', 'Gulf Coast Business Credit', 'https://www.gulfcoastbc.com', 'Gulf Coast Business Credit ("GCBC") is one of the largest accounts receivable finance and asset-based lending firms in the U.S. GCBC provides commercial lenders with a solution that allows them to say "yes" more frequently. We partner with banks throughout the country, offering referral programs designed to help institutions achieve growth through new accounts, non-interest income, higher profitability and increased client retention.', 'Ms. Meg Roberson', 'megroberson@gulfbank.com', '(512) 345-4900', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000b2', 'Haberfeld', '', 'kmorgan@haberfeld.com https://www.haberfeld.com (402) 323-3605 206 S 13th St Ste 1500 Lincoln, NE 68508-2019 Haberfeld is an employee-owned company with over three decades of experience helping community banks profitably grow by acquiring more profitable customers and increasing core deposits. Haberfeld helps banks more than double new customer acquisitions and increase profitability using a disciplined activity system that embraces technology-based, ROI-focused marketing. Haberfeld provides banks with an extensive, on-site training regimen and assists banks in product development, policy and procedure evaluations and enhanced service through mystery shopping.', 'Ms. Kristin Morgan', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000b3', 'HAL Docs', 'https://haldocs.com/', 'Attorney-Prepared Commercial Loan Documents — Faster Turnaround, Lower Cost.  
HAL Docs specializes in delivering attorney-customized commercial loan documents with unparalleled speed and price certainty. Leveraging Aeon technology, we provide attorney customized loan documentation within three business days, offering tiered pricing based on loan amounts.  HAL Docs is a subsidiary of the banking centric law firm Higier Allen &amp; Lautin, P.C. and is led by experienced banking lawyers who together represent more than 25 banks.', 'Mr. Jeff Livingston', 'jlivingston@aeonlegaltech.com', '(972) 716-1888', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000b4', 'Ham, Langston and Brezina LLP', 'https://www.hlb-cpa.com', 'Ham, Langston and Brezina, LLP provides external and internal audit, tax preparation and consulting, loan review, merger, acquisition and compliance services to financial institutions throughout Texas. HLB has enjoyed great success by implementing the simple principle of providing clients an experienced engagement team committed to quality and timely service for a reasonable fee.', 'Mr. Robert Brezina', 'brezina@hlb-cpa.com', '(281) 481-1040', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000b5', 'Hamby & Hengeli LLC', 'https://www.hambyhengeli.com', 'Hamby &amp; Hengeli LLC provides accounting and consulting services exclusively to independent banks. Services include financial statement audits, director examinations, internal audits, tax preparation, regulatory compliance, loan reviews and risk assessments. We believe the needs of each institution are unique. Our approach is client-driven, not product-driven. We design our services to fit your needs. Hamby &amp; Hengeli LLC is your partner in banking.', 'Mr. Robert L. Hamby, CPA', 'robert@hambyhengeli.com', '(325) 949-2567', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000b6', 'The Hanover Insurance Group', 'https://Hanover.com', '8003 Bellona Ave Towson, MD 21204-1902 The Hanover Insurance Group is a leading property and casualty carrier, offering broad and innovative insurance protection for small and mid-sized businesses, as well as for homes, automobiles, and other personal items, through a select group of many of the best independent agents and brokers in the country.  The group’s first company was founded in 1852, and the group’s stock is traded on the New York Stock Exchange.', 'Barbara Ewing', 'BEWING@HANOVER.COM', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000b7', 'Hapax', 'https://www.askhapax.ai', '10124 Lake Creek Pkwy Austin, TX 78729-1711 Hapax is an institutional AI operating layer built for banks and credit unions. It enables financial institutions to apply AI to real work in a governed and repeatable way by executing institutional procedures and regulatory requirements consistently. Hapax supports critical workflows across lending, compliance, and operations, producing results that can be reviewed, explained, and relied on. Designed for regulated environments, Hapax helps institutions achieve immediate operational impact while building long-term capacity to scale without adding risk.', 'Ms. Crisda Bergers', 'cbergers@askhapax.ai', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000b8', 'Hawk', '', '240 Park Ave New York, NY 11702-1623 Hawk is an AI-native financial crime platform built for banks, credit unions, fintechs, and payment firms. It helps teams detect AML and fraud risk faster, cut false positives, streamline alerts, cases, and SAR/CTR workflows, and act with greater precision. With agentic AI and its AML Investigative Agent, Hawk automates data gathering, case analysis, typology detection, and narrative drafting so investigators can focus on stopping real financial crime.', 'Mr. Bryan Smythe', 'Bryan.smythe@hawk.ai', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000b9', 'Hedgehog', 'https://www.hedgehog.tech', '254 Chapman Rd Ste 208 Newark, DE 19702-5422 Hedgehog lets banks of any size build their own models for asset liability management (ALM) and interest rate risk (IRR). Our application integrates with your policies and data to deliver tailored, accurate insights with complete documentation in seconds.', 'Ms. Rayce Coyne', 'rayce.coyne@hedgehog.tech', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000ba', 'Henry & Peters, P.C.', '', 'MWilliamson@henrypeters.com https://www.henrypeters.com (903) 597-6311 3304 S Broadway Ave Tyler, TX 75701-7818 Henry &amp; Peters, PC, with over 120 employees and offices in Tyler, Longview and Frisco, currently provides services to more than 25 financial institution clients with assets sizes ranging from $50 million to $4.0 billion. Services include tax preparation, external, internal, NACHA and trust audit services, directors'' exams, regulatory compliance and FDICIA consulting. We regularly consult with bank clients in holding company formations, reorganizations, mergers, acquisitions, litigation, S Corp elections, ESOP plans and internal audit design.', 'Ms. Melissa Williamson', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000bb', 'Higginbotham', 'https://www.higginbotham.net', 'Higginbotham is the largest independent insurance broker based in Texas. Thousands of companies and financial institutions across the state trust our single source solution for employee benefits. We have more than 30 offices in Texas to serve your regional insurance needs. Our size ranks us among the largest brokers in the nation, yet our local concentration keeps us accessible. In fact, we''re always by your side. Getting you covered is just what we do on day one. We support you and your employees on day two and every day after. It''s what we call Day Two Services® because we deliver everything you need to manage your plans and control your benefits throughout the year.', 'Mr. Mark Rutherford', 'Mrutherford@higginbotham.net', '(817) 797-0556', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000bc', 'Hilltop Securities', 'https://www.hilltopsecurities.com', 'HilltopSecurities is a full-service municipal investment bank and wealth advisory firm providing financial services for public entities, institutional investors, housing finance agencies, broker-dealers, and individual investors. Founded in 1946, HilltopSecurities’ primary areas of focus include public finance, capital markets, structured finance, retail brokerage, clearing services, and securities lending. Member: NYSE/FINRA/SIPC.', 'Mr. Matt Harris', 'matt.harris@hilltopsecurities.com', '(214) 855-2177', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000bd', 'Holland & Knight LLP', 'https://www.hklaw.com', 'Holland &amp; Knight specializes in representing and counseling financial institutions ranging in size from large, publicly-traded banks and bank holding companies to smaller, closely-held community banks to de novo institutions. Our services include bank creation, mergers, acquisitions, divestitures, regulatory and governmental compliance, commercial finance, bankruptcy, electronic payments and FinTech, intellectual property, data privacy, cybersecurity, third-party vendor services, troubled bank and problem asset resolutions, and litigation and real estate.', 'Mr. James C. Chadwick', 'james.chadwick@hklaw.com', '(512) 472-1081', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000be', 'Hollerbach & Associates, Inc.', 'https://www.hollerbach.com', 'With a reputation for accuracy and fast turn-around, the company provides lenders with comprehensive title research, abstracting and a wide range of settlement services to include flood zone determinations, tax certificates, real estate appraisal products, pre-foreclosure and Trustee services; providing title due diligence for the energy sectors of oil and gas exploration and renewables. A family-owned business based in San Antonio since 1985, the company''s reach expands throughout Texas, the Southwest and Latin America.', 'Mr. James L. Hollerbach', 'jhollerbach@hollerbach.com', '(210) 226-2556', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000bf', 'HUB | Taylor Advisors', 'https://www.tayloradvisor.com', 'HUB | Taylor Advisors is a balance sheet management-consulting firm and an SEC registered investment advisor servicing financial institutions. They are not affiliated with brokers/dealers. The cornerstone of their service is delivering objective/independent advice, strategies, and education in the areas of investment, liquidity, asset/liability, and risk management.', 'Mr. Omar Hinojosa', 'omar.hinojosa@hubinternational.com', '(502) 814-5656', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000c0', 'Hudson Technology Systems', 'https://www.hudsonts.com', '276 5th Ave Rm 803 New York, NY 10001-4509 The most valuable commercial relationships your bank has — or could win — are usually those with the most sophisticated daily treasury management needs. Multi-party disbursements. Conditional releases. Money movement is governed by contract terms that standard banking core solutions weren''t built to handle. 

Hudson builds the treasury infrastructure that makes these relationships possible at scale. We work with you to configure the financial logic your clients require — the conditions, the rules, the contractual obligations — so your bankers can say yes to your most demanding commercial clients, and deliver.', 'Ms. Lola Mora', 'lola.mora@hudsonts.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000c1', 'Hunton Andrews Kurth LLP', 'https://www.hunton.com', 'Hunton Andrews Kurth LLP has counseled institutions on more than 375 M&amp;A transactions and dozens of nonbank acquisitions. The group is number one in cumulative M&amp;A transactions since 2000. The firm assists on regulatory matters, securities offerings, capital planning, cybersecurity, compliance and BSA/AML issues, dozens of IPOs, and secondary offerings, over 100 de novo banks, fintech, nonbanking activities and myriad compliance issues before all federal bank regulatory authorities.', 'Mr. Peter G. Weinstock', 'pweinstock@hunton.com', '(214) 979-3000', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000c2', 'Husch Blackwell LLP', '', 'Christine.Deacon@huschblackwell.com https://www.huschblackwell.com (512) 479-1179 111 Congress Ave Ste 1400 Austin, TX 78701-4093 Husch Blackwell is an AmLaw 100 law firm and a leading provider of legal services to the banking and finance industry. Drawing on deep and industry-leading experience, our financial services team understands the nuances, concerns, and demands of the market and advises clients in navigating complexity in an ever-changing legal and business environment. Our law firm''s capabilities and reliability enable us to provide clients with personalized, value-adding, and cost-effective service.', 'Christine Deacon', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000c3', 'I2c', 'https://www.i2cinc.com/', '100 Redwood Shores Pkwy Redwood City, CA 94065-1226 An award-winning global financial technology innovator powering credit, debit, prepaid, core banking, and money movement solutions, i2c unifies banking and payments in an all-in-one platform, transforming product personalization with a customer-centric architecture and accelerating speed-to-market with composable building-block solutions. Financial institutions and fintechs globally trust i2c to help them quickly and efficiently configure and scale differentiated financial offerings in an evolving, competitive market. Powered by innovation and driven by trust for more than 25 years, i2c blends modern ingenuity with expert reliability to supercharge exceptional banking and payments experiences for millions of users and billions of transactions worldwide. 
Technology Audits &amp; Risk Assessments', 'Ms. Megan Folkman', 'mfolkman@i2cinc.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000c4', 'IBT Apps', 'https://www.ibtapps.com', 'IBT Apps is a core partner, delivering a fully integrated core banking system equipped with an adaptable and comprehensive suite of products, scalable to the individual needs of each client. Our i2Suite platform is the total solution for community financial institutions, providing them the ability to meet the various challenges of the marketplace by reducing costs, improving efficiencies, and lowering compliance risks. Additionally, we support our clients with MNS services, responsive website design, and more.', 'Mr. Mark C. Dittman', 'mdittman@ibtapps.com', '(512) 616-1115', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000c5', 'IBusiness Funding', 'https://ibusinessfunding.com', 'iBusiness Funding offers innovative technology, services, and products that enable lenders of all sizes to help borrowers obtain SBA and commercial funding. With our LenderAI and Lending as a Service solutions, we focus on helping banks and other lenders provide funding solutions for small business owners and helping small business owners connect with lenders to access funding solutions.', 'Mr. Marco Perim', 'marco@ibusinessfunding.com', '(757) 232-0512', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000c6', 'Identicomm, Inc.', 'https://www.inklesspads.com', 'Identicomm, Inc., located in Omaha, Nebraska, manufactures and sells inkless fingerprint pads nationally as well as internationally to private sector, banking institutions and government agencies. Our patented one-step fingerprint pad will take a permanent black fingerprint on any plain piece of paper without leaving any residue on the finger. This product provides a simple yet efficient method of positive fingerprint identification. The pad is ideal for use of check identification or in any other instance where positive identification is needed.', 'Ms. Susan Stolinski', 'sales@inklesspads.com', '(402) 392-1234', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000c7', 'Identifi', 'https://identifi.net', '701 Enterprise Rd E Ste 900 Safety Harbor, FL 34695-5342 Identifi is an enterprise content management company that specializes in electronic document storage, business process improvement, and document tracking. Their solutions streamline document workflows, enhance efficiency, and improve organizational productivity. By offering secure storage and robust tracking tools, Identifi helps businesses optimize processes, reduce costs, and maintain compliance. Whether managing documents or automating business processes, Identifi provides the tools necessary to handle critical information more effectively and securely.', 'Ms. Mariah Bradshaw', 'mbradshaw@identifi.net', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000c8', 'IMS Cloud Services INC', 'https://imscloudservices.com', '1029 Lower Peninsula Loop Georgetown, TX 78633-2343 IMS Cloud Services is a trusted provider of secure, fully managed data backup, disaster recovery, and cyber-resilience solutions for financial institutions. For more than 25 years, we’ve helped credit unions and banks safeguard their most critical systems using Rubrik-powered technology and white-glove support. Our solutions ensure immutable backups, rapid recovery, regulatory compliance, and continuous protection—allowing IT teams to reduce risk, streamline operations, and maintain uninterrupted service for their members and customers.', 'Aaron Wilson', 'aaron.wilson@imscloudservices.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000c9', 'IncumbentFI', '', '4741 Central St Kansas City, MO 64112-1533 IncumbentFI is a B2B SaaS company that provides embedded fintech solutions to financial institutions, specializing in programmable payments, fee notification compliance, teen banking, budgeting and payment card solutions, and white-label merchant rewards programs.

The IFI platform allows you to "unlock" the binary limitations of your existing debit cards and transform those cards into "programmable payment" cards.

Programmable payment functionality enables debit cardholders to seamlessly link additional internal accounts (ie. checking, savings, HELOC) AND external accounts; (ie. a health savings account (HSA), BNPL, micro LOC) to fund transactions made using their debit card.', 'Mr. Mike Miroslaw', 'mmiroslaw@incumbentfi.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000ca', 'Innovative Financing Solutions', 'https://innovativefinancingsolutions.net', 'Innovative Financing &amp; Consulting Group, LLC t/a Innovative Financing Solutions (IFS) is a lender consulting and business advisory firm specializing in the development and implementation of government guaranteed loan programs (primarily SBA and USDA loan guaranty programs) for community banks located throughout the U.S.    IFS also specializes in the arrangement of commercial conventional and alternative financing for business clients ranging in size from small and growing entrepreneurial companies to established middle market firms.', 'Mr. Michael Ryan', 'mryan@innovfs.net', '(610) 228-4654', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000cb', 'Insperity', 'https://www.insperity.com/tba', 'At Insperity, it’s not just HR outsourcing, it’s HR that makes a difference. Our comprehensive, scalable HR solutions offer an optimal blend of service and technology to facilitate growth by streamlining processes related to payroll, benefits, talent management and HR compliance. We provide the tools to help you lighten your administrative load, maximize productivity, and manage risks – so you can focus on growth. Because that’s what it means to have a true HR partner.', 'Mr. Aaron DelBosque', 'aaron.delbosque@insperity.com', '(281) 348-2955', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000cc', 'Integris', 'https://www.integrisit.com', 'Committed to providing best-in-class service, Integris specializes in optimizing technology for financial institutions by designing unique business-aligned IT strategies. Our services are customized to increase your financial institution’s profitability and efficiency while ensuring the security of your business.', 'Mr. Brad Giddens', 'brad.giddens@integrisit.com', '(877) 223-6401', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000cd', 'IntraFi', 'https://www.IntraFi.com', 'Chosen by over 3,000 financial institutions, IntraFi has provided deposit placement and wholesale funding services for more than 20 years. IntraFi’s network—the largest of its kind—brings scale, giving each participant access to tens of billions of dollars in funding, the highest per-depositor and per-bank capacity, and the peace of mind of being able to make large-dollar placements. The company invented reciprocal deposits and its tested, trusted solutions are utilized by financial institutions of all sizes. IntraFi helps its network participants grow strong, loyal customer relationships, fund more loans, earn fee income, and seamlessly manage liquidity through all market conditions.', 'Mr. Chuck McBrayer', 'cmcbrayer@intrafi.com', '(866) 776-6426 x3432', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000ce', 'Invictus Analytics', 'https://www.invictusgrp.com/', 'Invictus Analytics is a strategic advisory firm that helps community banks unlock capital, prepare for emerging risks, and satisfy regulatory expectations with confidence. By combining deep regulatory insight with proprietary, SOC-certified technology and loan-level analytics, Invictus delivers customized stress testing, CECL calculations, and capital planning that go far beyond "check-the-box" compliance.
Invictus has partnered with over 125 institutions with many high CRE concentrations or ambitious growth strategies helping them reduce capital requirements, justify increased lending limits, navigate M&amp;A, and secure regulatory approvals for dividends and stock repurchases.
Our team provides white-glove, audit-friendly support that is intuitive, actionable, and built to withstand scrutiny from boards, auditors, and regulators alike. Whether your bank is managing aggressive CRE growth, preparing for a trade-war-driven recession, or looking to optimize its ACL under CECL, Invictus offers the tools, expertise, and deliverables to position your institution for long-term success.', 'Ms. Patti Casaleggio', 'pcasaleggio@invictusgrp.com', '(862) 228-3954', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000cf', 'Ironcore', 'https://www.ironcore-inc.com', 'Ironcore, Inc. is an FFIEC examined provider of leading edge hosted &amp; managed IT, cybersecurity, business continuity and compliance services for community banks. Since 2008 Ironcore has assisted banks in developing strategic IT plans that secure, simplify and strengthen their individual technology systems. Ironcore develops technology landscapes that not only fully address the requirements of today but are able to withstand the demands of the future.', 'Francine Guenther', 'francine.guenther@ironcore-inc.com', '(512) 484-8406', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000d0', 'Ironwood', 'https://teamironwood.com/', '410 Enterprise Dr Oxford, MS 38655-2763 Ironwood is a national payments processor delivering tailored, boutique solutions that drive growth. We’re pleased to support the Texas Bankers Association and expand our presence across the great state of Texas, partnering with community banks to strengthen the communities they serve. By listening first, then designing, we reduce friction and help reduce attrition. We manage operational support, risk, and underwriting on both TSYS and Fiserv, building scalable programs for our bank partners.', 'Denise Manley', 'dmanley@teamironwood.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000d1', 'J.B. Lloyd & Associates, LLC', 'https://www.igpspecialty.com/programs/financial-institutions/', 'J.B. Lloyd &amp; Associates is an insurance agency that provides lender placed hazard &amp; flood and mortgage impairment / mortgage errors &amp; omissions insurance to Texas banks. J.B. Lloyd &amp; Associates delivers unique web-based reporting capabilities, broad insurance carrier options, and excellent customer service.', 'Mr. Aaron Cardwell, RPLU, CIC', 'aaron.cardwell@igpspecialty.com', '(972) 207-7855', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000d2', 'Jack Henry Banking', 'https://www.jackhenry.com', 'Jack Henry™ is a well-rounded financial technology company that strengthens the connections between people and their financial institutions through technology and services that reduce the barriers to financial health – with the purpose of empowering people and communities to gain the financial freedom to move forward.', 'Mr. Rob Thompson', 'rthompson@jackhenry.com', '(417) 235-6652', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000d3', 'JRBT', 'https://www.jrbt.com', 'JRBT, a public accounting firm in Waco, offers extensive experience with audits, directors'' examinations, internal audits, mergers, acquisitions, tax preparation and other specialized services for banks. JRBT Bank Consulting (formerly CWC Bank Services) provides loan review and other credit risk management services. Together, we serve many clients in the financial institutions industry throughout the State of Texas with a long-term commitment to personalized service.', 'Mr. Stephen Spencer, CPA', 'stephen_spencer@jrbt.com', '(254) 776-4190', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000d4', 'K2 Integrity', 'https://www.k2integrity.com', 'K2 Integrity provides trusted financial crime compliance, investigations, and risk management solutions for the banking industry. Our team of former regulators, compliance officers, and industry experts helps banks navigate complex regulatory landscapes, ensuring robust anti-money laundering (AML) programs, fraud prevention strategies, and operational resilience. With tailored advisory services, we support bankers in managing emerging risks, enhancing compliance frameworks, and safeguarding reputations in an ever-evolving financial environment.', 'Mr. Nolan McCarthy', 'nmccarthy@k2integrity.com', '(212) 845-7535', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000d5', 'Kane Russell Coleman Logan PC', 'https://www.krcl.com', 'Formed in 1992, Kane Russell Coleman Logan PC is a full-service law firm with offices in Dallas, Houston, and Austin. The firm provides professional services for clients ranging from Fortune 500 companies to medium-sized public and private companies to entrepreneurs. KRCL handles a wide array of transactional, litigation, employment, and bankruptcy matter in Texas and throughout the country.', 'Ms. Leslie J. McKee Schmidt', 'LSchmidt@krcl.com', '(214) 777-4200', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000d6', 'Keefe, Bruyette & Woods, A Stifel Company', 'https://www.kbw.com', 'Keefe, Bruyette and Woods, Inc. (KBW) is a full service investment bank and broker-dealer with a specialty in super-community and regional banks.  KBW has been committed to Texas banks for over 30 years which has resulted in the firm being a leader in M&amp;A Advisory, IPO’s and Debt Capital Markets.  KBW has built a reputation of excellence.  Our relationship-based approach and longstanding presence in the industry has led to unparalleled success for our clients.', 'Mr. Craig R. McMahen', 'cmcmahen@kbw.com', '(512) 813-7243', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000d7', 'Kennedy Sutherland LLP', 'https://www.kslawllp.com', 'Kennedy Sutherland, LLP is a Texas-based law firm with a 30-year history of representing banks and bank holding companies on corporate, securities, regulatory and transactional matters. Our focus is on providing prompt, actionable advice to our clients. Because of our extensive experience in the industry, we are always searching for ways to drive value through innovation and creative solutions.', 'Mr. Patrick J. Kennedy, Jr.', 'pkennedy@kslawllp.com', '(210) 228-9500', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000d8', 'KlariVis', 'https://www.klarivis.com', 'KlariVis is a data intelligence platform built by former bankers for financial institutions. The technology transforms siloed data across the institution into actionable insights and delivers it to every person across the institution who needs it. With more than 150 implementations and a proven track record of measurable results, KlariVis is the trusted partner financial institutions choose to start and grow their data journey. For more information, visit KlariVis.com.', 'Ms. Meaghan Kincaid', 'MeaghanKincaid@klarivis.com', '(540) 206-3734', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000d9', 'Kroll Bond Rating Agency', 'https://www.kbra.com', 'Kroll Bond Rating Agency, LLC (KBRA) is a global full-service rating agency with a mission to set a standard of excellence and integrity. Established in 2010, KBRA remains dedicated to the restoration of trust in credit ratings by creating new standards for assessing risk and offering timely and transparent ratings.', 'Ms. Caitlin Fitzpatrick', 'caitlin.fitzpatrick@kbra.com', '(646) 731-1268', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000da', 'KRT Security', 'https://www.krtsecure.com', '454 Soledad St Ste 100 San Antonio, TX 78205-1555 KRT Security delivers expert cybersecurity solutions to banks of all sizes across Texas, with a focus on protecting financial institutions from evolving digital threats. Our veteran-led team provides tailored services including risk assessments, penetration testing, and regulatory compliance support. We understand the unique challenges banks face and help ensure systems are secure, resilient, and audit-ready. At KRT Security, we partner with financial institutions to strengthen defenses and build long-term cybersecurity strategies that inspire trust and confidence.', 'Mr. Kris Trumble', 'kris@krtsecure.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000db', 'Kunstrux, Inc.', '', 'Randy.McCauley@Kunstrux.com https://kunstrux.com 550 Reserve St Ste 390 Southlake, TX 76092-1603 Kunstrux is laying the foundation for modern construction lending by connecting lenders, builders, and trades on a single, trusted platform. By digitizing and verifying the flow of funds, Kunstrux enables lenders to deploy capital faster, reduce risk, and realize interest sooner. Builders gain speed through streamlined draws, while trades receive instant, fee-free payments. The result is a more efficient, transparent, and scalable construction finance ecosystem that works for everyone.', 'Randall McCauley', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000dc', 'Langley & Banack, Inc.', 'https://www.langleybanack.com', 'Langley &amp; Banack is a full-service south and central Texas law firm based in San Antonio. As part of our banking industry group, Langley &amp; Banack''s Financial Institutions Corporate and Regulatory practice provides innovative and efficient legal advice on a wide variety of corporate and bank regulatory matters, including M&amp;A transactions, securities offerings, corporate governance, Subchapter S elections, regulatory compliance, strategic planning, and other matters affecting community banks, their directors and owners.', 'Ms. Katy Akin Corrigan', 'kcorrigan@langleybanack.com', '(210) 736-6600', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000dd', 'LemonadeLXP', 'https://www.lemonadelxp.com', '', 'Mr. John Findlay', 'jfindlay@lemonadelxp.com', '(647) 687-4963', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000de', 'LenderBox', 'https://lenderbox.ai', '5646 Milton St Ste 675 Dallas, TX 75206-3978 LenderBox is an AI-powered commercial real estate lending intelligence platform that transforms manual underwriting from 25+ hours to 35 minutes with 99.9% accuracy. Built for community banks, regional banks, credit unions, and private credit teams, LenderBox liberates trapped loan data - turning years of filed appraisals and loan documents into searchable market intelligence. Founded by a 20-year CRE technology veteran and active real estate investor, LenderBox gives Texas lenders the same AI firepower as the nation''s largest banks.', 'Mr. Vijay Mehra', 'vijay@lenderbox.ai', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000df', 'LocalPay', 'https://localpay.com', '228 Hamilton Ave Fl 3 Palo Alto, CA 94301-2583 LocalPay provides Local Banks with a patented Pay-by-Bank solution that allows Consumers to pay local Merchants directly from their bank accounts without any intermediaries. Merchants are directly connected with paying banks through seamless integration with banking cores to achieve much lower transaction fees with real-time capable settlement and greater Consumer Rewards. LocalPay puts Local Banks at the center of their local economies to increase their Revenue, Deposits, and Consumer lending.', 'Mr. Alan Tam', 'alan.tam@localpay.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000e0', 'London Consulting Group', 'https://londoncg.com', 'The company description is:
London Consulting Group is a business transformation partner with an obsession to shape organizations together so they can adapt and thrive in an ever-evolving environment. We strive to become the business transformation partner trusted by leading organizations to design and execute holistic transformations to get more of their business. A holistic transformation involves defining a flexible, forward-looking strategy, evolving the operating model, optimizing existing technology, adopting new technologies, developing your people, and transforming your culture to achieve material outcomes such as improved financial results (non-interest income growth and non-interest expense reduction), reduction in employee and customer turnover, and adoption of data-driven decision making (through the design of analytical dashboards).
 
Strategic Planning', 'Mr. Enrique J. Cervantes', 'enrique.cervantes@londoncg.com', '(210) 316-9716', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000e1', 'Mabus Agency', 'https://mabusagency.com', '71 S Green St Tupelo, MS 38804-4724 Mabus Agency was formed in 2008 with a focused mission: to help people and raise the creative bar. Nearly two decades later, we''ve done this for 39 banks in 34 states. We combine banking experience with marketing expertise to help banks build marketing strategies that grow deposits, increase business relationships, and take market share. Our 30-person help banks build brands, budgets, strategies, and tactics that win.', 'Josh Mabus', 'josh@mabusagency.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000e2', 'Magnet Geological', '', 'magnetoil657@gmail.com https://www.magnetgeological.com (325) 473-4400 402 S State St Bronte, TX 76933 R.S. Bud Johnson, 20-year Texas Licensed Geologist #3772 through Magnet Geological, provides a short assessment of real estate geohazard risk analysis and real estate geological asset potentials.  Georisks include such things as sinkholes; expansive clays; naturally or artificially contaminated waters and soils; wildfires. Geo-assets include groundwater potential, sand, gravel, petroleum; and geostatistical rain forecasts. As principal, Mr. Johnson used these skills to grow his assets and is now offering to assist others as a consultant.', 'Mr. Robert Johnson', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000e3', 'MANTL', 'https://www.mantl.com', 'MANTL is a financial technology firm offering omnichannel account origination software for banks and credit unions. Consumer Deposit Origination by MANTL is among the fastest and most performant solutions on the market, empowering net-new prospects to open accounts in under three minutes, enabling existing account holders to open additional accounts with just one click, and reducing fraud by as much as 67%. Commercial Deposit Origination by MANTL is a first-of-its-kind solution that reimagines account opening for businesses of all sizes by automating up to 97% of application decisions. MANTL’s customers have raised billions in core deposits to date. Founded in 2016, MANTL is a privately held company headquartered in New York with the backing of prominent venture capital investors. For more information, visit mantl.com.', 'Ms. Taina Biggs', 'taina@mantl.com', '(469) 458-9427', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000e4', 'Mauldin & Jenkins, LLC', 'https://www.mjcpa.com', 'Mauldin &amp; Jenkins is annually recognized as a Top 100 Firm by Accounting Today and Inside Public Accounting and currently provides over 65,000 hours each year to over 175 financial institutions throughout the country. Whether your needs include audit and tax services, advisory services, risk management, compliance issues from BSA to SBA, commercial loan reviews, mergers, and acquisition assistance, or you want to outsource specific functions, you can rely on the experts at Mauldin &amp; Jenkins.', 'Mr. Jay Lucas', 'jlucas@mjcpa.com', '(800) 277-0080', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000e5', 'McCormack & Associates, Inc.', 'https://mccorm.com', 'McCormack and Associates, a Vantage Point Company
MAi, now part of Vantage Point Solutions, provides specialized, comprehensive support to banks across the country. Our experienced team offers expertise in audit, compliance, asset and liability management, model validation, loan review, and strategic planning; as well as IT audits and assessments, cybersecurity, risk mitigation, and marketing services. These integrated resources are customized for every scenario, helping financial institutions strengthen operations, navigate regulatory complexity, and elevate organizational performance. We are committed to our customers and supporting your long-term success.', 'Ms. Laurie Bethune, CRCM', 'laurie@mccorm.com', '(605) 359-2374', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000e6', 'McDermott + Bull', 'https://mbexec.com', 'McDermott + Bull Executive Search partners with community and regional banks + credit unions to identify and recruit VP to C-Suite executives for permanent roles. Known for being thorough and balancing the need for urgency, McDermott + Bull provides personalized solutions to those who value contribution over pedigree. Leveraging deep vertical experience, innovative thinking, and proven time-saving methodologies, the company challenges the norm and thrives in the recruitment of difficult-to-find, culture critical executive talent.', 'Ms. Rachel Crisi', 'rloye@mbexec.com', '(949) 753-1700', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000e7', 'Merchants PACT', 'https://www.merchantspact.com', 'Merchant''s PACT (MPACT) is a fintech, payments firm that integrates with core and digital platforms to empower financial institutions with software, data, and payment solutions through an open platform. Our solutions keep financial institutions at the center of the accountholder experience, modernize their SMB and commercial client payment offerings, maximize revenue, minimize disintermediation by Square and others, and interweave payment acceptance services into digital and business banking like never before.', 'Ms. Ashley Noland', 'anoland@merchantspact.com', '(502) 964-6030', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000e8', 'Mhp.Si', 'https://mhp.si/', '705 Gean Trl Keller, TX 76248-1235 Company bio: mhp.si, a nationally award-winning marketing agency with 50+ years of experience, specializes in data-driven digital strategies for banks. As a Google Premier Partner, mhp.si delivers measurable ROI through performance marketing and end-to-end reporting, allowing clients to know exactly how much they pay for each application by tactic and campaign. The agency leverages digital techniques, taking over the household where 88% of financial decisions are made. 100% FLA Compliant. We help smart banks win in the attention economy. Learn more at mhp.si.', 'Mr. Tim Whitley', 'twhitley@mhp.si', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000e9', 'Midwestern Securities Trading Company, LLC.', 'https://midwesternsecurities.com/', '235 Everett St East Peoria, IL 61611 Midwestern Securities is a boutique Broker-Dealer and Registered Investment Advisory company started in 2000 by a father and son financial advisor team.  It is privately owned by financial advisors, bankers and employees and works exclusively with community financial institutions.  We partner with banks to start competitive wealth management programs, or take over an existing program and help to build a more competitive, compliant and collaborative program to offer to your communities.', 'Ms. Anne Schutt', 'Aschutt@midwesternsecurities.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000ea', 'Moody''s', 'https://www.moodysanalytics.com', 'Moody''s empowers financial institutions with cutting-edge intelligence and analytical tools to drive informed decision-making. Our award-winning solutions encompass comprehensive research, robust data, advanced software, and professional services, all designed to deliver a seamless and integrated customer experience. With a focus on innovation and excellence, we support thousands of organizations globally, helping them navigate complex financial landscapes and achieve their strategic goals. Our commitment to meeting customer needs and fostering an open mindset ensures that we remain at the forefront of the industry. As a trusted partner, we provide the insights and tools necessary for bankers to thrive in today''s dynamic market.', 'Ms. Allyson Beback', 'Allyson.Beback@moodys.com', '(415) 874-6009', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000eb', 'Morphis, Inc.', 'https://www.morphisinc.com', 'Morphis helps banks reduce cash—and never run out. Our AI-enabled platform forecasts net demand across the organization—vaults, branches, and ATMs—and automates cash ordering, so institutions carry only the cash they need. For a bank, excess cash means added risk, insurance, and transportation expense—reduce the cash,&nbsp;and those costs fall with it. Treasury teams get one live view of cash—and the control to act on it. Industry-proven, Morphis retires spreadsheets for good.
Morphis® is a Microsoft® Gold Certified Partner.', 'Mr. Gary Faulkner', 'gfaulkner@morphis.com', '(214) 378-2772', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000ec', 'MPA Systems, LLC', 'https://www.mpasystems.com', 'MPA Systems LLC specializes in leasing and selling high-security modular, transportable buildings to financial institutions and other office/service organizations, providing disaster recovery programs and full turnkey services across the United States. MPA Systems LLC is a BOXX Modular company that rents, leases, and sells temporary and permanent modular buildings, including mobile offices, office complexes, classrooms, lavatories, medical centers, bank facilities, disaster recovery programs, blast resistant buildings, and storage containers to customers in North America. We also provide full turnkey major project solutions and ancillary services for diverse sectors including industry and government, for both urban and remote locations.', 'Mr. David Strong', 'dstrong@mpasystems.com', '(940) 458-2600', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000ed', 'Multi-Bank Securities, Inc.', 'https://www.mbssecurities.com', 'Multi-Bank Securities, Inc. (MBS), a veteran-owned business, has specialized in the sales, trading and underwriting of fixed income securities since 1988. We underwrite for Fannie Mae, Freddie Mac, Farmer Mac, the Federal Farm Credit Banks and the Federal Home Loan Banks. MBS also offers a proprietary web-based platform, eConnectDirect®, to help institutional investors easily compare, select and manage offerings with more confidence and more control.', 'Ms. Terrye Saliba', 'tsaliba@mbssecurities.com', '(248) 291-1100', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000ee', 'Nasdaq Verafin', '', 'Daniel.Christian@nasdaq.com https://www.verafin.com (709) 752-3050 18 Hebron Way St. John''s, NL A1A 0L9 CANADA Nasdaq Verafin provides cloud-based Financial Crime Management Technology solutions for Fraud Detection, AML/CFT Compliance, High-Risk Customer Management, Sanctions Screening and Management, and Information Sharing. More than 2,500 financial institutions globally, representing more than $8T in collective assets, use Nasdaq Verafin to prevent fraud and strengthen AML/CFT efforts. Leveraging our unique consortium data approach in targeted analytics with artificial intelligence and machine learning, Nasdaq Verafin significantly reduces false positive alerts and delivers context-rich insights to fight financial crime more efficiently and effectively.&nbsp;To learn how Nasdaq Verafin can help your institution fight fraud and money laundering visit&nbsp;www.verafin.com or call 1-877-368-9986.', 'Mr. Daniel Christian', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000ef', 'Navanta', 'https://www.bankonitusa.com', 'Navanta™ is the trusted technology and services partner for community financial institutions, delivering purpose-built solutions with heart, soul, and extraordinary service. Its offerings include Bankers Private Cloud®, core banking, managed IT and advisory services, cybersecurity, infrastructure, and customer engagement solutions. Navanta empowers community bankers and their people to thrive together. Go Bankers, Go.', 'Mr. Jason McCoy', 'jmccoy@bankonitusa.com', '(800) 498-8877', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000f0', 'Navari', 'https://www.navari.com', '215 S Center St Royal Oak, MI 48067-3870 Navari is a technology and solutions platform designed to help leaders navigate complexity and achieve more. Through connected software, insights, and services, Navari delivers expert guidance and intuitive tools that enable confident decision making and stronger organizational performance. 
 
&nbsp;Serving more than 2,200 financial institutions, universities, hospitals, and other organizations nationwide, Navari combines smart technology with human insight to help leaders drive stronger outcomes. 
 
Learn more at navari.com.', 'Ms. Jessica Bradley', 'Jessica.Bradley@Navari.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000f1', 'NBID', 'https://www.nbid.com/', '27 W 24th St Suit 701 New York, NY 10010 National Bank InterDeposit Company (NBID) is a reciprocal deposit network. Member institutions can leverage NBID’s deposit network to offer access to millions in aggregate insurance across network banks to attract large-value depositors, retain key relationships, and grow new business lines. All participating depository institutions receive a membership interest in NBID.', 'Mr. Tony Karalekas', 'tony@modernfi.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000f2', 'nCino', 'https://www.ncino.com', 'Founded in 2012 and headquartered in Wilmington, North Carolina, nCino (NASDAQ: NCNO) is the worldwide leader in Intelligent banking, purpose-built for financial institutions of all sizes — from community banks and credit unions to the world''s largest enterprise lenders. Our platform unifies people, artificial intelligence, and data into a single, end-to-end operating system that empowers banks to modernize how they lend, onboard customers, manage portfolios, and grow their businesses.

For Texas banking institutions specifically, nCino represents a proven, trusted path to replacing outdated legacy systems, reducing operational friction, improving examiner-ready documentation, and building the kind of intelligent, scalable infrastructure that supports long-term growth.', 'Mr. Baxter Loesch', 'baxter.loesch@ncino.com', '(888) 676-2466', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000f3', 'Ncontracts', 'https://www.ncontracts.com', 'Ncontracts is a leading provider of SaaS-based compliance and risk management software and services to financial institutions. Our GRC solutions cover vendor management, enterprise risk management, business continuity, compliance, audit and findings management, and cybersecurity. We provide seamless management of the complete lifecycle of risk and compliance, backed by dedicated support, unlimited training, and guaranteed accuracy.', 'Mr. Samuel R. Desmond', 'sam.desmond@ncontracts.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000f4', 'NETBankAudit', 'https://www.netbankaudit.com', 'Formed by a team of IT bank executives and regulatory specialists, NETBankAudit is a unique audit and network security testing firm specializing in providing GLBA, FFIEC, SOX and Consumer Affairs assessment, audit and network vulnerability testing services to community financial institutions. Quality of service, focus and affordability has allowed us to grow to over 600 clients, supported by our services. NETBankAudit''s goal is to address technology risk management and compliance concerns, while reducing regulatory uncertainty.', 'Ms. Melissa Morrell', 'mmorrell@netbankaudit.com', '(800) 243-0416', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000f5', 'Netchex', 'https://netchex.com/', 'Netchex offers businesses a comprehensive, web-based suite of payroll, human resource and benefit administrative services backed by dedicated support specialists. Regardless of the number of employees or your payroll complexity, Netchex can tailor solutions to fit your needs. This rare combination of comprehensive solutions, dedicated support and flexible offerings helps you easily manage employee information and simplify your entire payroll process.', 'Mr. Alec  Duncan', 'aduncan@netchexonline.com', '(985) 220-1410', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000f6', 'Newcleus', 'https://www.newcleus.com', 'The power of Newcleus: combining decades of experience to redefine what''s possible in designing and administering compensation, benefits, investment and financing strategies. We generate the uncommon insights that ensure you retain the people who power your company.', 'Mr. David F. Soto', 'dsoto@newcleus.com', '(512) 796-8242', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000f7', 'NextBranch', 'https://nextbranch.com', '498 N Kays Dr Ste 110 Kaysville, UT 84037-4151 NextBranch is a leading provider of ATM and Branch Transformation technologies and services for financial institutions. Solutions include full ATM and ITM outsourcing, core-integrated ITMs with an expanded self-service transaction set, video banking solutions, and teller cash recyclers. NextBranch is part of the Grant Victor family of companies. Founded in 2000, Grant Victor is the largest distributor of Hyosung equipment in the United States and wholly owns four Strategic Business Units (SBUs) specializing in outsourced ATM management solutions, wholesale distribution of Financial and Retail ATM equipment, ATM parts and supplies, ATM component repair, and transaction processing solutions.', 'Ms. Ginger Dearing', 'ginger.dearing@nextbranch.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000f8', 'NFP, an Aon Company', 'https://executivebenefits.nfp.com', 'NFP, an Aon company, provides creative solutions to attract and retain key talent. Banks count on NFP to design, implement, and administer these important compensation, executive benefit, nonqualified benefit, and BOLI programs. In addition, NFP has had a longstanding relationship with the ABA and has recently become a Premier Partner. As further evidence of its leadership role in the industry, TBA and several state banking associations also exclusively endorse NFP.
Contact Ken Derks* at ken.derks@nfp.com  
Trey Deupree* at trey.deupree@nfp.com  

*A Registered Representative of Kestra Investment Services, LLC, member FINRA/SIPC.', 'Mr. Kenneth F. Derks', 'ken.derks@nfp.com', '(612) 845-2256', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000f9', 'Norton Rose Fulbright US LLP', 'https://www.nortonrosefulbright.com', 'Norton Rose Fulbright is a global law firm providing legal services to leading corporations and financial institutions. With more than 3,000 lawyers worldwide, the firm advises clients across the Americas, Europe, Asia-Pacific, the Middle East, and Africa. It is recognized for client service in key industries including financial institutions; energy, infrastructure and resources; technology; transport; life sciences and healthcare; and consumer markets. Norton Rose Fulbright Verein coordinates member firms and does not provide legal services.', 'Mr. Michael G. Keeley', 'mike.keeley@nortonrosefulbright.com', '(713) 651-5151', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000fa', 'Nueve Solutions', 'https://nuevesolutions.com', '13706 N Highway 183 Ste 304 Austin, TX 78750-1840 Nueve Solutions is a fintech company delivering embedded digital banking solutions for community banks and credit unions. Its products integrate directly into platforms like Q2, Banno, and Candescent, enabling seamless user experiences. Key offerings include Self-Service CDs, which let customers open, manage, and renew certificates; Automate Banking, which drives user segmentation and notifications; and Refer-a-Friend, a fully automated referral program that boosts deposit growth while reducing customer acquisition costs through targeted incentives and streamlined workflows.', 'Ravi Kallepalli', 'ravi@nuevesolutions.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000fb', 'NuSource Financial', 'https://www.nusourcefinancial.com', 'Cutting edge technology solutions and exceptional customer service make NuSource one of the fastest growing bank technology companies in the country. NuSource''s innovative ATM, Branch Transformation and Security Solutions help financial institutions improve their operational performance and enhance the customer experience with improved speed and convenience. Through partnerships with highly regarded companies like Hyosung, NuSource provides tailored strategies for financial institutions that create an optimal experience for their customers.', 'Mr. Mark A. Johnson', 'markj@nusourcefinancial.com', '(612) 805-7122', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000fc', 'Oculus Software', 'https://www.oculus-software.com', 'Oculus Software''s BNControl is a data analytics platform empowering financial institutions with actionable insights. It unifies reporting, financials, CRM, and compliance, offering an interactive, user-friendly interface. BNControl transforms raw data into strategic tools, enhancing decision-making, optimizing efficiency, and improving productivity and profitability through comprehensive performance tracking.', 'Ms. Leah Mccann', 'Lmccann@oculus-software.com', '(877) 484-9666', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000fd', 'ODP Business Solutions', '', 'Jorge.Montalvo@odpbusiness.com https://www.odpbusiness.com/banksignup (512) 651-2579 9501 Amberglen Blvd Ste 200 Austin, TX 78729-1156 TBA’s partnership with ODP Business Solutions is part of a national state bankers association discount program accessed by hundreds of banks across the country. The program has proven to deliver an average cost savings of 20-30% to participating members.', 'Jorge Montalvo', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000fe', 'Olsen Palmer LLC', 'https://www.olsenpalmer.com', 'Olsen Palmer LLC is an independent investment banking firm that exclusively advises community banks across the spectrum of mergers &amp; acquisitions out of offices in Washington DC, Chicago, Denver and Birmingham. By design, the firm combines the full M&amp;A expertise of a traditional investment banking firm with the specialization, agility, and responsiveness of an independent firm.', 'Ms. Kathleen Flahive', 'kflahive@olsenpalmer.com', '(202) 808-3306', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-0000000000ff', 'On The Mark Strategies', 'https://www.markarnold.com/', '1001 E Hebron Pkwy Ste 118 -274 Carrollton, TX 75010-1015 On The Mark Strategies is a team of Avengers helping community financial institutions become the powerhouses they are destined to be. When you work with us, you get a group of experts who customize solutions to the particular needs of your institution. Services offered include strategic planning, branding, marketing help, training and more. Solve your growth problems when you book a free consultation today.', 'Mr. Sean Galli', 'sean@markarnold.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000100', 'ON2IT Inc.', 'https://www.on2it.net', 'Easily embrace the protective power of Zero Trust security through ON2IT’s Zero Trust-as-a-Service. ON2IT applies Zero Trust, as defined by Creator of Zero Trust and ON2IT SVP, John Kindervag, to your cybersecurity in a convenient and comprehensive managed security services model. ON2IT safeguards your environment through the innovative AUXO™ Zero Trust platform and a team of seasoned cybersecurity analysts with 24x7 eyes-on-glass, who continuously monitor your network, act proactively, and execute threat countermeasures in real-time.', 'Karin Muller', 'karin.muller@on2it.net', '(214) 206-8446', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000101', 'OnBoard', 'https://www.onboardmeetings.com', 'OnBoard is a secure cloud-based board management software designed to make board meetings more informed, effective, and uncomplicated. Built for bank leaders, boards, and their committees – OnBoard is trusted by 100''s of banks across the country and the only board management software endorsed by the Texas Bankers Association.', 'Mr. Sean Larkin', 'slarkin@onboardmeetings.com', '(765) 535-1880', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000102', 'Onsetto', 'https://www.onsetto.com', '330 2nd Ave S Ste 200 Minneapolis, MN 55401-2289 Onsetto powers Structured Activation for business banking, helping financial institutions turn new business accounts into fully activated operating relationships.

Opening a business account is only the beginning. The real value comes when operating activity moves; payroll, receivables, payables, and funding. When those flows transition, deposits follow and the relationship becomes primary.

Onsetto’s platform seamlessly guides businesses through the process of switching their operating account while giving financial institutions real-time visibility into activation and funding progress. Delivered as a secure, white-label solution that operates alongside existing systems, Onsetto requires no core integration and can be implemented quickly.

By helping banks activate operating relationships faster, Onsetto enables financial institutions to capture the Core Operating Account, accelerate business deposit growth, and deepen commercial relationships.', 'Lindsey Johnston', 'Lindsey@Onsetto.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000103', 'Optria', 'https://www.optria.com', 'Company description - Optria helps financial institutions optimize statement delivery and marketing outreach with secure, digital-first solutions while maintaining reliable print options. We streamline workflows, enhance engagement, and ensure compliance through seamless digital document delivery and advanced mail tracking. With decades of industry expertise and redundant facilities across the U.S., Optria provides the reliability and innovation needed to improve operations and meet evolving customer expectations.', 'Mr. Pete Stoughton', 'pete.stoughton@optria.com', '(407) 430-2181', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000104', 'Orion', '', '17605 Wright St Omaha, NE 68130-2095 Orion is a premier provider of the tech-enabled fiduciary process that transforms the advisor-client relationship by enabling financial advisors to Prospect, Plan, Invest, and Achieve within a single, connected, technology-driven experience. Combined, our brand entities, Orion Advisor Tech, Orion Portfolio Solutions, Brinker Capital Investments, Redtail Technology, and Orion OCIO create a complete offering that empowers firms to attract new clients seamlessly, connect goals more meaningfully to investment strategies and outcomes, and ultimately track progress toward each investor’s unique definition of financial success. Orion services $4.4 trillion in assets under administration and $69.4 billion of wealth management platform assets (as of June 30, 2024) and supports over six million technology accounts and thousands of independent advisory firms. Today, 12 out of the Top 15 Barron’s RIA firms rely on Orion’s technology to power their businesses and win for investors. Learn more at Orion.com.', 'Ms. Stephanie Bridges', 'stephanie.bridges@orion.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000105', 'OSC Insurance Services', 'https://www.oscis.com', 'OSC is a leading provider of compliance-driven tracking technology and insurance products and services for traditional and community banks, credit unions, auto and finance companies, mortgage servicers and property investors. From on-demand manual lender-placed programs to hybrid insurance tracking solutions using our proprietary IrisX technology, OSC delivers timesaving, customizable and scalable portfolio protection programs nationally. We offer competitive property coverage as well as blanket, mortgage impairment and more from top-rated, international insurance carriers.', 'Mr. Russell Hall', 'rhall@oscis.com', '(972) 984-0993', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000106', 'Otteson Shapiro LLP', 'https://www.os.law', 'Otteson Shapiro LLP was founded in 2001 by former partners of national and regional law firms. We provide companies and individuals with superior legal expertise in a broad range of commercial litigation and other business matters. Across the Southwest and Rocky Mountains, our lawyers represent financial institutions, including community banks, providing comprehensive services from litigation and bankruptcy to regulatory and transactional counsel. We work in partnership with our clients to evaluate potential risks and solve problems, and we appreciate the importance of understanding our clients'' businesses to achieve the desired solution or result.', 'Mr. John Podvin, Jr.', 'jpodvin@os.law', '(214) 377-0147', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000107', 'Paladin Fs, LLC', 'https://www.paladin-fs.com', 'Paladin fs, LLC is a research and consulting firm possessing a proprietary knowledge base of market intelligence and pricing data on all outsourced services sold by every Core &amp; IT service provider in the U.S.  CEOs and CFOs improve their negotiating strength by calling Paladin before their vendor when considering a contract renewal or purchasing new services and products.', 'Mr. Aaron Silva', 'asilva@paladin-fs.com', '(877) 746-4859', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000108', 'Parkhill', 'https://parkhill.com', '5844 John Hickman Pkwy Ste 500 Frisco, TX 75034-1383 We are a full-service design firm of extraordinary planners, designers, architects, and engineers. Our vision is to enhance lives and inspire people in the communities we build by prioritizing human experiences in every decision. Together, we develop collaborative relationships with clients that produce inventive, relevant solutions to complex challenges. By considering all aspects of a well-functioning community in our design, we create built environments that promote flourishing lives. And that’s something worth pursuing together.', 'Candace Barron', 'cbarron@parkhill.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000109', 'Pattillo, Brown & Hill, L.L.P.', 'https://www.pbhcpa.com', 'Established in 1923, Pattillo, Brown &amp; Hill, L.L.P. provides auditing, tax, small business, and employee benefits services to clients in many industries. Specific to community banks, our services include the following audits: ACH, bank secrecy act, fair lending, internal controls, regulatory compliance, and tax services. We also offer loan reviews, cafeteria plan and 401K plan administration, payroll processing, financial statement opinion audits, holding company financial reporting and reporting assistance and other requested services.', 'Mr. Dan H. Jackson, CPA, CRCM, CAMS', 'djackson@pbhcpa.com', '(254) 772-4901', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000010a', 'Payroc', 'https://payroc.com', '1776 Peachtree St NW Ste 700S Atlanta, GA 30309-2308 Founded in 2003, Payroc WorldAccess, LLC, is a&nbsp;global&nbsp;payments ecosystem&nbsp;that helps businesses accept payments and optimize commerce. Payroc ranks among the top merchant acquirers in North America, processing more than $125 billion in volume annually and operating&nbsp;across 50 regions with direct connections to the major card networks. Its proprietary full-stack technology supports vertically tailored&nbsp;card-present, card-not-present, and omnichannel&nbsp;solutions for software providers, financial institutions, and merchants of all sizes. With a focus on innovation, scalability, and award-winning support, Payroc makes&nbsp;payments seamless and drives growth for partners&nbsp;worldwide. For more information, visit&nbsp;payroc.com&nbsp;', 'Bob Balogh', 'bob.balogh@payroc.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000010b', 'PCBB', 'https://www.pcbb.com', '1255 Treat Blvd Ste 240 Walnut Creek, CA 94597-7997 Our Mission — We believe in the power of local financial institutions to be the catalyst of small business growth and to enable communities to thrive. Our talented team is committed to providing not only the tools and knowledge our customers need to serve their clients, but also the partnership and trust they deserve.
With a robust suite of competitive services, PCBB helps community financial institutions maximize revenue, increase efficiency, and manage risk. To learn more about our services, visit www.pcbb.com or call us at 888-399-1930', 'Mr. Chuck C. Floyd, Jr.', 'cfloyd@pcbb.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000010c', 'Pentegra Retirement Services', 'https://www.pentegra.com', 'Pentegra is a leading provider of retirement plan and fiduciary outsourcing solutions to banks nationwide. As one of America’s oldest independent fiduciaries, we deliver retirement plans that run with less risk, greater efficiencies, and improved outcomes. With an 80-year legacy of fiduciary expertise and oversight unmatched in the industry today, we partner with firms at the advisor, sponsor, and enterprise level to bring maximum flexibility to every opportunity, offering a comprehensive array of retirement plan solutions, plan consulting, TPA services and fiduciary support.', 'Mr. John J. Schafer', 'john.schafer@pentegra.com', '(303) 921-3109', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000010d', 'Performance Trust Capital Partners LLC', 'https://www.performancetrust.com', 'Performance Trust helps community financial institutions make better balance sheet decisions so they can serve their communities and help fuel small businesses by using revolutionary strategies, tools, and insights to measure the risk and rewards of cash flows across the entire balance sheet. Education is the cornerstone for all they do which allows their clients to deepen their expertise as they work alongside Performance Trust. Today, Performance Trust is the largest full-service investment bank focused on community depository institutions.', 'Ms. Pamela Shanahan', 'pshanahan@performancetrust.com', '(713) 446-1413', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000010e', 'PhaseOne Design Builders, L.P.', 'https://www.phaseonebuilders.com', 'PhaseOne Design Builders is a Texas based design-build firm focused on building strategic future ready banking facilities throughout the nation. PhaseOne provides complete turnkey services including facility consulting, architecture, construction, branch transformation and branding to achieve our clients’ growth goals.', 'Mr. Jeff Taylor', 'jtaylor@phaseonebuilders.com', '(800) 972-6443', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000010f', 'PIKA RMS LLC', 'https://pikarms.com/', 'PMB 244 190 E Stacy Rd Allen, TX 75002-8738 Ste 306 PIKA RMS delivers integrated risk management solutions that strengthen resilience, improve operational performance, and protect organizational trust. Our expertise spans governance, risk and compliance (GRC), cybersecurity, operational resilience, business continuity, crisis communication, vendor risk, and continuous process improvement. We partner with financial institutions and businesses to build practical, future-ready frameworks that reduce risk, enhance decision-making, and prepare organizations to navigate disruption, regulatory change, and evolving operational challenges with confidence.', 'Ms. Mirka Clavel', 'mirka.clavel@pikarms.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000110', 'Piper Sandler & Co.', 'https://www.pipersandler.com', 'Piper Sandler is a leading investment bank and institutional securities firm driven to help clients Realize the Power of Partnership®. Through a distinct combination of candid counsel, focused expertise, and empowered employees, we deliver insight and impact to each and every relationship. Our proven advisory teams combine deep product and sector expertise with ready access to global capital.', 'Ms. Terry Weber', 'terry.weber@psc.com', '(212) 466-7800', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000111', 'Plante Moran', 'https://www.plantemoran.com', 'Plante Moran builds strong relationships with our clients by cultivating a collaborative experience and applying our extensive banking industry expertise to each engagement. The full resources of our firm are available to support your needs in external/internal audit, cybersecurity, regulatory compliance, technology, risk management services, and more.', 'Mr. Ryan Abdoo', 'ryan.abdoo@plantemoran.com', '(303) 846-3474', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000112', 'PNC Capital Markets LLC', 'https://www.pnc.com', 'PNC Financial Services Group, Inc. (NYSE: PNC) is one of the nation''s largest diversified financial services companies with assets of $370 billion and more than 57,000 employees in the U.S and abroad. The Financial Institutions group (FIG) is an experienced team of professionals focused on building partnerships with financial institutions across the country. With a broad product set, the FIG group assists bank managers in enhancing investment and loan portfolio performance, managing interest rate risk, expanding commercial product offerings, controling operating costs and strengthening liquidity positions.', 'Ms. Courtney Ritter', 'courtney.ritter@pnc.com', '(317) 750-1539', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000113', 'Primax', 'https://www.primax.us', '615 Channelside Dr Ste 204 Tampa, FL 33602 Primax provides payment processing services and an expansive array of technology and solutions. Customizable solutions include risk management, mobile and online card management, data and analytics, loyalty programs, strategic consulting, delinquency management and contact center services, helping banks profitably grow their portfolios and deliver an unparalleled experience to their accountholders.  primax.us', 'Peter Rae', 'peter.rae@primax.us', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000114', 'Prothro, Wilhelmi & Company, PLLC', 'https://www.pw-tx.com', 'PW''s Risk Advisory services include the development of operational risk assessments and the implementation of internal audit plans for a diverse client base of financial institutions. These services include consulting related to risk assessments, outsourcing and co-sourcing of the internal audit function. Our unique approach of collaborating with stakeholders has proven to be effective in obtaining buy-in and consensus on the prioritization of operational risks and overall risk management strategy.', 'Mr. Walter K. Wilhelmi, CPA', 'walter@pw-tx.com', '(903) 534-8811', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000115', 'Proximitty Inc.', 'https://www.proximitty.ai', '505 Montgomery St Ste 1100 San Francisco, CA 94111-2585 Proximitty is the regulator-grade AI agent platform purpose-built for commercial lending. We help banks automate the highest-friction workflows across C&amp;I, CRE, and SBA lending — from borrower document collection and reconciliation to financial spreading, credit memo generation, and covenant monitoring. Our agents operate on any system without API integration, deploying in under two weeks with full SR 11-7 governance, audit trails, and human-in-the-loop. We''re backed by Y Combinator (first investors in Airbnb, Stripe, OpenAI), CRV.', 'Wye Yew Ho', 'wyeyew@proximitty.ai', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000116', 'PTMA Funding', 'https://www.pmafunding.com', 'PMA Funding (PMA) is a leader in providing institutional funding options. One call gains access to our experienced funding team (over 100 years of combined experience) and our large sources of political subdivision depositors (4,000+ public entities). PMA works in tandem with your institution to understand funding needs and identify diversified solutions, both on a primary and contingent basis and can deploy a variety of deposit options, both brokered and non-brokered.', 'Mr. Todd Terrazas', 'tterrazas@pmanetwork.com', '(630) 835-9193', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000117', 'PULSE', 'https://www.pulsenetwork.com', 'PULSE® is a leader in debit payments, global cash access, and account transfers, and we deliver exceptional value, choice, and convenience to clients across the payments ecosystem. We enable reliable and secure digital money movement for a wide variety of debit card programs through our PULSE Network, the Discover® Debit program, an advanced fraud-detection platform, and partner-support services. Our commitment to continuous improvement, innovation, and prioritizing the unique business needs of our clients empowers payment solutions that meet the evolving demands of consumers. PULSE is part of the Discover Global Network. For more information, visit PulseNetwork.com.', 'Mr. Jeremy Vice', 'jeremyvice@pulsenetwork.com', '(800) 420-2122', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000118', 'Q2', '', 'carly.baker@q2.com https://www.q2.com (833) 444-3469 10355 Pecan Park Blvd Austin, TX 78729-1784 Q2 is a financial experience company dedicated to providing digital banking and lending solutions to banks, credit unions, alternative finance, and fintech companies in the U.S. and internationally. With comprehensive end-to-end solution sets, Q2 enables its partners to provide cohesive, secure, data-driven experiences to every account holder–from consumer to small business and corporate. Headquartered in Austin, Texas, Q2 has offices worldwide and is publicly traded on the NYSE under the stock symbol QTWO.', 'Carly Baker', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000119', 'Q6 Cyber', 'https://www.q6cyber.com/', '6100 Pines Blvd Ste108 Miami, FL 33024 Q6 Cyber is a leading provider of e-crime intelligence to financial institutions worldwide. We monitor the “Digital Underground,” including Dark Web and Deep Web forums, malware networks, botnets, and private messaging apps where fraudsters operate. Our 24/7 coverage delivers actionable intelligence that identifies threats before they become fraud losses. Q6 Cyber helps prevent account takeovers, check fraud, new account fraud, and payment card fraud, consistently providing high ROI and proactive protection to global financial institutions.', 'Mrs. Koral Berman Smith', 'kberman@q6cyber.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000011a', 'QSI Banking', 'https://qsibanking.com', '107 Schuler Dr Bardstown, KY 40004-3201 QSI is NCR’s largest financial partner. We offer turnkey ATM and ITM solutions, including outsourcing and in-house financing. Other solutions include TCRs, video, alarm, security and branch equipment. Availability and security are assured with QSI maintenance, cybersecurity and managed services. QSI is the nation’s largest financial reseller of NCR products and services.', 'Kendall Tungate', 'kendall.tungate@qsibanking.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000011b', 'Quantum Data Engines LLC', 'https://www.qde.ai', '1415 Marigold Ct Mountain View, CA 94040-3069 Quantum Data Engines (QDE) is a technology company specializing in building transaction monitoring and financial crime detection solutions for the banking and financial services industry. With over 15 years of experience, QDE products process more than a billion transactions daily across 18 countries. Our solutions focus on speed, scale, and performance, leveraging AI/ML capabilities to provide financial institutions with the tools necessary to effectively combat money laundering, terrorist financing, fraud, and other regulatory challenges.', 'Jonathan Sanam', 'jonathan@qde.ai', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000011c', 'Quantum-Infinite', 'https://www.Quantum-Infinite.com', 'Quantum Infinite is a technology company dedicated to guiding organizations through the rapidly approaching quantum era. As advances in quantum computing threaten to undermine existing encryption, the company focuses on the urgent adoption of NIST-aligned Post-Quantum Cryptography standards. By delivering quantum-safe strategies, expertise, and tools, Quantum Infinite enables businesses to mitigate emerging risks and secure critical data before current cryptographic protections become obsolete.', 'Mr. Nick Mistry', 'nmistry@ProDefenseUSA.com', '(628) 400-1805', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000011d', 'Quasar Capital Partners, Inc.', 'https://www.quasarcapitalpartners.com', '1210 Cottonwood Creek Trl Ste 500 Cedar Park, TX 78613-2689 We provide custom funding solutions tailored for your clients in need. We provide solutions with integrity, transparency, and professionalism. We service clients, in the US and Canada, who have needs of $20M (facility size) We work with both factoring and ABL clients and see what others may not. We can help with immediate needs and short-term solutions until you find more permanent pathways to solve your business cash flow problems. In the long run, we are really good at creating value for your company.
We learn your business inside and out so that when you need execution, we are there to answer the call to action. Period.

We''re in the business of making business better.', 'Mr. Sam Tork', 'Sam@quasarfunds.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000011e', 'QwickRate/IntelliCredit', 'https://www.qwickrate.com', 'QwickRate’s affordable solutions include: IntelliCredit™ for an online Loan Review tool that makes processes repeatable and fast, and a powerful Portfolio Analysis tool that helps identify emerging hotspots and detect risk earlier; QwickAnalytics® for online access to industry research, peer analysis and regulatory tools such as CECLSolver™ and Credit Stress Test; and the premier CD Marketplace for non-brokered funding and investing.', 'Ms. Ricki Dagosta', 'ricki.dagosta@qwickrate.com', '(678) 797-4088', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000011f', 'R&T Deposit Solutions', 'https://www.reichandtang.com', 'R&amp;T Deposit Solutions (R&amp;T) offers an expanded suite of innovative products and services to help banks and financial institutions meet their unique cash sweep, deposit funding, and securities-based lending needs. By delivering consistent results on behalf of their clients since 1974, R&amp;T has achieved sustained business growth and earned a reputation in the market for exceptional client service, collaborative engagement, and flexibility.', 'Mr. Stephen Brown', 'sbrown@rnt.com', '(212) 830-5242', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000120', 'RADD LLC', 'https://raddllc.com/', '3553 Atlantic Ave Ste 1612 Long Beach, CA 90807-5606 RADD LLC is a consulting firm specializing in internal auditing and regulatory compliance for financial institutions. They offer services such as BSA/AML compliance, risk management, internal audits, regulatory exam preparation, and virtual staffing for roles like Compliance or BSA Officer. RADD helps banks, credit unions, fintechs, and mortgage providers stay compliant, reduce risk, and improve operations through tailored support and expert guidance.', 'Mr. Brian Montes', 'brian@raddllc.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000121', 'RADER Solutions', 'https://www.radersolutions.com', 'RADER Solutions is a managed information technology (IT) service provider specializing in cybersecurity risk management, regulatory &amp; compliance services, integrated solutions, Microsoft Office 365 &amp; Azure consulting services, all with SLA-backed responsiveness. For 25 years, RADER Solutions has delivered innovative and reliable IT services across the United States. We hold top accreditations such as SOC 2 Type 2, which is required by our bank customers.', 'Mr. Tye Miller', 'tye@radersolutions.com', '(337) 233-5010', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000122', 'Raisin', 'https://www.raisin.com/en-us', 'Raisin is a global financial technology company that partners with banks. Raisin’s efficient digital platform for raising retail deposits enables U.S. banks to expand their reach and source deposits from savers nationwide. We offer a flexible funding solution, allowing these institutions to actively manage deposit volumes and terms to optimize their balance sheets. Our platform delivers the full deposit value chain – from marketing and KYC/AML to reporting and customer service — reducing partners’ “brick and mortar” and other administrative costs.', 'Mr. Jonathan Kim', 'Jonathan.kim@raisin.com', '(917) 353-6283', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000123', 'Ray, Feighny & Hartle PLLC', 'https://www.rfhfirm.com', 'RFH is a national law firm representing clients in the banking, finance, and oil &amp; gas industries across the United States. RFH’s attorneys are adept at various types of lending transactions, including SBA loan documentation packages, commercial loan documentation packages, hard money loan documentation packages, modifications, forbearances, foreclosures, and other banking-specific practices and needs.', 'Ms. Staci Griffin', 'sgriffin@rfhfirm.com', '(713) 641-5563', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000124', 'Raymond James – Financial Institutions Division', 'https://www.raymondjames.com', 'Raymond James is the largest investment banking firm providing a broad array of services to community and regional banks. Our approach involves establishing long-term relationships with high-performing organizations and providing customized advice on topics including capital formation, whole bank and branch acquisitions and divestitures, stock repurchases and capital deployment. Our bank and thrift practice are supported by research coverage for over 130 depository institutions and a dedicated sales and trading desk.', 'Mr. Matt Paramore, CFA', 'matthew.paramore@raymondjames.com', '(919) 755-2600', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000125', 'Reativ', 'https://reativfi.com', '5331 S Macadam Ave Portland, OR 97239 Reativ is a cloud-based treasury management system purpose-built for banks. It delivers real-time cash visibility, predictive forecasting, and automated workflows — integrating market data to drive faster, more informed decisions. By replacing spreadsheets and fragmented systems, reativ helps treasury teams optimize liquidity, improve earnings, reduce costs, and meet regulatory expectations from a single, secure platform.', 'Jarryd Briggs', 'jarrydbriggs@reativfi.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000126', 'Red Siege, LLC', 'https://redsiege.com', '1421 Rosedown St Longview, TX 75604-3637 Red Siege is a globally recognized offensive security firm, founded in 2017, specializing in offensive penetration testing and cybersecurity training. Red Siege is trusted by organizations to reduce real, business-impacting cyber risk by tailoring our offensive security approach to threats that matter most.
Known for elite our team of qualified and experienced information security experts, tradecraft, and real-world tools, Red Siege actively advances the security community through research, education, and participation at top global events.', 'Mr. Tim Medin', 'hq@redsiege.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000127', 'RelPro', 'https://relpro.com', '2675 Black Bear Dr New Braunfels, TX 78132-4179 Here at RelPro we are a targeted intelligence for sales, marketing and business development professionals. We comprehensively cover companies with revenues of &gt;$1MM including details on filings / loans (UCC, PPP, SBA 7A &amp; 504, Commercial Real Estate), Form5500, Non-profit Form 990, MBE, buyer intent data, "look alike" companies, industry research integration (Vertical IQ and IBISWorld), and certain CRM integration. As well as accurate contact details for the decision makers at those companies &gt;200M; including wealth insights on &gt;8M high and ultra-high net worth individuals (RelPro Wealth Management).', 'Mrs. Rosemary Hopkins, MBA', 'rhopkins@relpro.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000128', 'Remedy Consulting', 'https://www.remedyconsult.net', 'Remedy Consulting helps financial institutions (FI) thrive through best-in-class consulting services specializing in Technology Contract Negotiation, Technology Pricing &amp; System Assessments, Contract Terms &amp; Conditions Improvements, and FI Strategic Planning. As a trusted advisor to community financial institutions, the Remedy Team has executed over 700 system selection and vendor negotiations since 2016. Our clients receive a cost reduction on their core vendor contracts and increased efficiency with Remedy’s Price Repository.', 'Jordan Kelly', 'jkelly@remedyconsult.net', '(262) 955-7776', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000129', 'Rivel, Inc', 'https://www.rivel.com', 'Rivel uses a data-driven approach to give banks and credit unions a deeper understanding of their customer key-decision drivers. Rivel Banking Research conducts 280,000 interviews annually to clarify consumers’ experiences and pain points with financial institutions, measuring over 90 perception metrics. With the capability to target that information down to the zip code, Rivel helps financial institutions determine vulnerabilities and opportunities within their territories, empowering them with data that helps them better understand their customers’ needs and efficiently develop strategies for new business growth.', 'Ms. Melissa Randi', 'mrandi@rivel.com', '(203) 226-0800', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000012a', 'Rivial Data Security', 'https://www.rivialsecurity.com/', 'PO Box 2824 West Lafayette, IN 47996-2824 Rivial Data Security offers banks the only cybersecurity platform that seamlessly integrates IT risk management and security compliance into a single automated solution. This enables CISOs and IT leaders to easily quantify the financial impact of their IT risk, compliance, and security decisions. Backed by industry-leading security experts, our platform ensures your security program continuously matures and consistently exceeds examiner expectations.', 'Mr. Lucas Hathaway', 'lucas@rivialsecurity.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000012b', 'Rocket Pro', 'https://www.rocketpro.com', '1050 Woodward Ave Detroit, MI 48226-3573 Rocket Pro is a division of Rocket Mortgage and a part of Rocket Companies, Inc. (NYSE: RKT). It works exclusively with mortgage brokers, correspondent lenders, community banks and credit unions. Rocket Pro''s partners provide the face-to-face service their clients desire, while tapping into the technology, expertise and award-winning process from Rocket Mortgage. The partner loan officer creates, and maintains, the relationship with the client. Rocket Mortgage approves, underwrites, processes and closes the loan in its name – or sells the loan to Rocket after the mortgage closes if it was originated as a correspondent loan.', 'Ms. Stephanie Nunn', 'StephanieNunn@rocketmortgage.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000012c', 'RSM US LLP', '', 'Sandina.Heckert@rsmus.com https://www.rsmus.com/what-we-do/industries/financial-services.html (512) 864-9656 19026 Ridgewood Pkwy Ste 400 San Antonio, TX 78259-5502 With more than 95 years of experience serving more than 2,500 financial institutions across the country, RSM develops industry-specific solutions designed to comprehensively reduce risk and help to achieve your goals. Our professionals provide exemplary technology, security, consulting, accounting, tax, audit, and compliance services while keeping abreast of the changing regulatory environment and challenges facing your company.', 'Ms. Sandina Heckert', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000012d', 'Russell & Associates', 'https://www.russellandassociates.co/', '4231 Westlake Dr Austin, TX 78746-1421 Advisory firm providing senior expertise (former large bank executives and regulators) from running, changing, protecting, securing, governing and managing a bank to all things risk, regulatory, audit and compliance. Highly competent with technology and cyber security.', 'Mr. Stephen Russell', 'stephen.russell@russell.associates', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000012e', 'SaferMobility', 'https://www.safermobility.com/', '6000 Lake Forrest Dr Ste 425 Atlanta, GA 30328-3877 SaferMobility offers mobile app solutions that safeguard employees during vulnerable times, ensuring compliance with the Bank Protection Act while reducing costs and liability. The system, compatible with both Android and iOS devices, is installed on employees’ everyday smartphones.', 'Mr. Walter Davis', 'walt@safermobility.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000012f', 'Salt Edge', 'https://www.saltedge.com', '5900 Balcones Dr Ste 100 Austin, TX 78731-4298 Salt Edge is a global provider of open banking APIs and financial technology infrastructure.&nbsp; With connections to over 5,000 banks, certifications for ISO27001-level security protections, and over a decade of experience supporting consumer banks, business banks, and other EMIs and MSBs, we are the internationally-chosen provider for the future growth of banking along with meeting today''s regulatory requirements and challenges.', 'Mr. Bradley M. Gold', 'bradley.gold@saltedge.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000130', 'Saris Al', 'https://www.saris.ai/', 'We specialize in streamlining backend operations in areas like Lending, Deposit Operations, Services, and Collections by automating manual, repetitive workflows. These tasks are often disliked by employees and pose significant challenges for traditional RPAs.', 'Mr. Chris Killeen', 'chris@saris.ai', '(469) 585-0664', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000131', 'SBS CyberSecurity, LLC', 'https://www.sbscyber.com', 'SBS CyberSecurity helps business leaders identify and understand cybersecurity risks to make more informed and proactive business decisions. Since 2004, SBS has been dedicated to assisting organizations with the implementation of valuable risk management programs and mitigating cybersecurity risks. SBS provides turnkey offerings tailored to each client’s needs, including risk management solutions, network security, consulting, auditing, and education. The company has worked with thousands of organizations globally, including financial institutions ranging in asset size from $12 million to over $130 billion.', 'Mr. Robb Nielsen', 'robb.nielsen@sbscyber.com', '(605) 923-8722', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000132', 'Scorpion 101, INC', '', 'marcus@scorpion101.com https://realceservices.com/realce-portfolio 2401 Glenhaven Dr Plano, TX 75023-7869 Scorpion101 Services is a Texas-based commercial renovation firm specializing in occupied banking environments. The company was formed to continue and expand institutional renovation work previously performed through Realce Services, where we supported retail banking projects across Texas, including extensive work with PNC Bank.

With over five years of experience in live-branch remodels, security-coordinated scopes, and phased construction within active financial facilities, we bring proven expertise in maintaining operational continuity during renovation projects.

We are committed to delivering high-quality work and building long-term partnerships within the Texas banking community.', 'Marcus Lima', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000133', 'Secure Guard Consulting LLC', 'https://www.secureguardconsulting.com', 'Secure Guard Consulting performs full-service cybersecurity/IT auditing and consulting. This includes internal security assessments, external security assessments and external penetration testing, IT general control reviews, and social engineering. Certified Social Engineer™ is a financial institution employee certification developed and offered by SGC. The company was founded in 2012 by Kaushal Kothari, a certified ethical hacker and former FDIC IT examination analyst.', 'Ms. Lynn Linenberger', 'lynn@sgcsecure.com', '(515) 229-5674', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000134', 'Securities Transfer Corporation', 'https://www.stctransfer.com', 'Securities Transfer Corporation is a full-service, S.E.C. registered stock transfer agent providing comprehensive, individually tailored shareholder management solutions to public and private companies for 40 years.', 'Mr. Matthew Smith', 'smith@stctransfer.com', '(469) 633-0101', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000135', 'The Security Center, Inc.', 'https://www.securitytexas.com', 'The Security Center, Inc., headquartered in Dallas, is a Woman Owned Business and a full-service Alarm and Video and Access Control Systems Integrator specializing in financial institutions since 1963. They are licensed in Texas and New Mexico with approximately 60 employees providing equipment sales and installation, central station alarm monitoring, locksmithing as well as preventive maintenance services. Bank branch equipment products include vault doors, safe deposit boxes, cash safes, lock work, drive-thru equipment, ATM barriers and acrylic barriers.', 'Mr. David McCabe', 'dmccabe@securitytexas.com', '(214) 349-0480', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000136', 'Segra', 'https://www.segra.com/', 'Segra owns and operates a wide and dense fiber-optic infrastructure footprint that provides state-of-the-art connectivity, cybersecurity, voice, cloud and colocation solutions, all backed by industry leading service and reliability. Serving over 20,000 connected customer locations in 24 states and 44,000 fiber route miles, Segra has been providing customer focused solutions for over 125 years. Segra is a standalone fiber company owned by Cox Communications. For more information, visit segra.com. 
 
Through Segra, Cox Business, RapidScale and Hospitality Network, Cox Communications provides a broad commercial solutions portfolio including advanced cloud and managed IT solutions and fiber-based network solutions that create connected environments, unique hospitality experiences and support diverse applications for nearly 370,000 businesses nationwide.', 'Ms. Ashlynn Devall', 'ashlynn.devall@segrafiber.com', '(469) 504-7828', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000137', 'SEI Sphere', 'https://www.seic.com/sphere', 'As a managed security services provider (MSSP), SEI Sphere provides comprehensive business solutions that deliver cybersecurity, network operations, and cloud services. Supporting and securing the evolving IT needs of today’s regulated and fast-growing businesses, SEI Sphere helps them build and maintain a secure technology foundation. For more than 50 years, SEI has provided technology platforms and solutions that enable clients to focus on strategic initiatives and drive future growth.', 'Mr. Mark Norcini', 'mnorcini@seic.com', '(610) 676-3541', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000138', 'Sendero', 'https://senderoconsulting.com', 'Sendero is a management consulting firm delivering the “how” behind business transformation. Sendero empowers clients to identify operational challenges, plot valuable and effective solutions, and drive tangible results at business speed. Anchored in deep domain expertise and fueled by an award-winning culture, Sendero partners with clients nationwide across a diverse range of industries. With offices in six strategic markets—Atlanta, Austin, Dallas, Houston, Nashville, and Phoenix—Sendero moves beyond the why and achieves the crucial how.', 'Ms. Susanne  Turnbo', 'susanne.turnbo@senderoconsulting.com', '(972) 388-5760', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000139', 'Sentry Management, Inc.', 'https://www.sentrymanagement.com', 'Sentry Management, Inc. is one of the largest, most experienced investment advisory firms specializing in asset/liability management for community banks in the U.S. The firm offers objective, fee-based-only management for banks ranging in size from $25 million to over $7 billion in assets with bank clients located in six states. By eliminating implicit and/or explicit conflicts of interest of broker/dealers, Sentry''s goal is to help independent banks remain independent through enhanced, risk adjusted management and investment strategies. Sentry''s money managers have over 95 years combined experience in writing policies, implementing investment programs, applying rate shock analysis and developing profitable asset management strategies. Please call if you want a team of professionals working as part of your management team, not selling you the next great deal.', 'Mr. Murphy Davis, Sr., CFA', 'murphy@sentrymanagement.com', '(940) 696-2100', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000013a', 'The SERO Group', 'https://www.theserogroup.com', '2000 Mallory Ln Ste 130-707 Franklin, TN 37067-7282 For over 25 years, companies have trusted The SERO Group to keep their SQL Servers healthy, secure, and reliable. Our mission is to equip companies with SQL Server expertise, DBA team processes, and data insights so that they can focus on growth and innovation. Some of our services include DBA as a Service, SQL Health Checks, and consulting for performance tuning and optimization, security and troubleshooting, high availability and disaster recovery, and cloud migrations.', 'Mr. Joe Webb', 'joew@theserogroup.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000013b', 'ServisFirst Bank', 'https://www.servisfirstbank.com', 'ServisFirst Bank is a full-service commercial bank focused on commercial banking, correspondent banking, treasury management, private banking, and the professional consumer market, emphasizing competitive products, state-of-the-art technology, and a focus on quality service. The Bank offers sophisticated treasury management products, Internet banking, home mortgage lending, remote deposit express banking, international banking, and highly competitive rates.', 'Mr. Rodney E. Rushing', 'RRushing@servisfirstbank.com', '(713) 865-3023', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000013c', 'Shadell Consulting & HR Solutions', 'https://www.shadellhr.com/', 'Dallas, Texas Shawna O’Dell is the founder of Shadell Consulting &amp; HR Solutions, a boutique firm specializing in strategic HR for small banks and growing businesses. With over two decades of executive-level experience and certifications including SPHR and SHRM-SCP, Shawna is known for her direct, decisive leadership and deep understanding of organizational dynamics. Her style is both analytical and action-oriented — blending logic with the ability to motivate teams and drive results.
Shawna brings a rare balance of structure and intuition to every engagement, guiding clients through transitions like mergers, compliance shifts, and team scaling with clarity and confidence. Resilient under pressure and focused on tangible outcomes, she helps clients turn complexity into opportunity and builds HR infrastructure that supports sustainable growth.', 'Ms. Shawna O''Dell, SPHR, SHRM-SCP', 'shawna@shadellhr.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000013d', 'Shred-it', 'https://www.shredit.com/en-us/national-accounts/state-bankers-association-program', 'Shred-it specializes in providing a tailored document and media destruction service that allows businesses to comply with legislation and ensure that the client, employee and confidential business information is kept secure at all times. Through their strict chain-of-custody processes, reliable on-time service and a global network of local service centers, Shred-it provides the most secure and efficient confidential information destruction service in the industry.', 'Mr. Kevin Kroboth', 'kevin.kroboth@stericycle.com', '(917) 582-7940', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000013e', 'Sigma Ratings Inc', 'https://www.sigma360.com', '40 Wall St New York, NY 10005-1304 The Sigma360 platform combines AI-driven intelligence, flexible workflows, and global data coverage to streamline risk management and strengthen financial crime defenses.', 'Mr. Skip Trachtman', 'Skip@sigmaratings.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000013f', 'Single Point Capital', 'https://singlepointcapital.com', '9810 Fm 1960 Bypass Rd W Ste 205 Humble, TX 77338-3537 Single Point Capital is a Houston-based commercial finance company specializing in accounts receivable factoring for transportation, staffing, manufacturing, and other small-to-mid-sized businesses. For over 20 years, we’ve provided reliable working-capital solutions, disciplined credit and underwriting practices, and strong portfolio performance. Our service model features dedicated account management, same-day funding, and proven risk controls, enabling clients to stabilize cash flow, support growth, and strengthen their financial position.', 'Mr. Terence F. O''Connor', 'toconnor@singlepointgroup.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000140', 'SLI Group, Inc.', 'https://www.sligroup.com', 'The SLI Group is a Texas-based design/build firm that offers turnkey services for the development of financial facilities. Our services include site analysis and selection, architecture, interior design, construction contracting and furniture purchasing/installation. We''ve been providing a single source of responsibility for our clients since 1976.', 'Mr. Chris Adams', 'cadams@sligroup.com', '(713) 465-4650', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000141', 'Sophinvest LLC', 'https://www.sophinvest.com', '304 S Jones Blvd Suite 300 Las Vegas, NV 89107-2623 Sophinvest invites Texas Bankers Association members to sell their non-performing commercial real estate loans to us. We purchase CRE, multifamily and mixed use loans on our own account and offer a smooth, fast and reliable closing process to eliminate your problem assets. Where sufficient equity exists, we can often pay up to par.
Get these assets off your balance sheet, recycle your capital and focus on core banking and new loans - not workouts.', 'Jean Gottschalk', 'jean@sophinvest.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000142', 'Sophos', 'https://www.sophos.com', 'Sophos is a cybersecurity leader defending 600,000 organizations globally with an AI-powered platform and expert-led services. It adapts to organizations at any stage of security maturity, combining machine learning, automation, and real-time threat intelligence with human expertise from Sophos X-Ops for 24/7 threat monitoring, detection, and response.

Sophos delivers industry-leading managed detection and response (MDR) and a broad portfolio of solutions, including endpoint, network, email, and cloud security, extended detection and response (XDR), identity threat detection and response (ITDR), and next-gen SIEM. Paired with expert advisory services, Sophos helps reduce risk, accelerate response, and outpace evolving cyber threats.', 'Ms. Sarah Messenger', 'sarah.messenger@sophos.com', '(512) 665-8882', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000143', 'Sprouse Shrader Smith PLLC', 'https://www.sprouselaw.com', 'Sprouse Shrader Smith PLLC is a multi service law firm in Amarillo that strives to provide excellent legal services with a team of professionals focused on exceeding client expectations through hard work, efficiency, and innovation, while maintaining our commitment to family and community.', 'Matt Sadler', 'matt.sadler@sprouselaw.com', '(806) 468-3324', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000144', 'Spry Inc.', 'https://www.sprybrands.com', 'Spry helps you market and manage your brand with absolute efficiency. Spry is a brand optimization partner for its clients and believes in the wisdom of disciplined budget management, smart solutions that win team compliance, and thoroughly efficient brand management.', 'Mr. Jeff Williams', 'jeffw@sprybrands.com', '(765) 649-4888', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000145', 'SQN Banking Systems', 'https://www.sqnbankingsystems.com', 'SQN Banking Systems is a leading worldwide provider of fraud detection solutions for the financial industry.  SQN offers real-time fraud analysis, exception item processing, cross-channel transaction analysis, check fraud detection, automated signature verification and safe deposit management.  SQN''s modular applications offer flexible, cost effective fraud protection for your financial institution.', 'Ms. Toni Nippins', 'tnippins@sqnbankingsystems.com', '(609) 261-5500', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000146', 'SRM', 'https://www.srmcorp.com', 'SRM has helped 1,000+ financial institutions add billions to their bottom line across payments, digital transformation, core processing, digital assets, and operational efficiency. SRM’s decades of vendor negotiation and advisory experience have lowered costs, increased productivity, and provided a competitive edge for clients in an environment of constant change.', 'Mr. Richard Whiddon', 'rwhiddon@srmcorp.com', '(901) 692-4860', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000147', 'SS&C Technologies', 'https://www.ssctech.com/', '80 Lamberton Rd Windsor, CT 06095-2136 SS&amp;C is a global provider of services and software for the financial services and healthcare industries. Over 20,000 financial services and healthcare organizations, from the world''s largest companies to small/mid-market firms, rely on SS&amp;C for expertise, scale and technology. SS&amp;C EVOLV solves financial institutions’ most complex challenges through a cloud-based, comprehensive platform that integrates and automates all risk and finance processes related to a loan portfolio—from data capture to back-end reporting and analytics.', 'Mr. Michael Therrien', 'michael.therrien@sscinc.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000148', 'Stablecore', 'https://www.stablecore.com', '9458 Gatetrail Dr Dallas, TX 75238-1854 Stablecore is a technology platform that enables regional and community banks and credit unions to offer stablecoin, tokenized deposit and digital asset products without changing their existing digital banking and core instructure. Stablecore’s approach gives banks complete control, ownership, and flexibility over their digital asset offerings, enabling them to work with any underlying digital asset', 'Mr. Nick Elledge', 'nick@stablecore.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000149', 'Star Lending Group', 'https://starlendinggroup.com/', '4308 Mineral Creek Trl Prosper, TX 75078-9604 We partner with banks that either cannot or choose not to offer a full assortment of residential mortgage loans. 
By doing this we not only provide a steady revenue income stream that is currently non-existent but also provide a way for these banks to keep their current customers from becoming poached by their competition. 
Key Works: Loan Services', 'Mr. Shad Marshall', 'shad@starlendinggroup.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000014a', 'Stephens Investment Banking', 'https://www.stephens.com', 'Founded in 1933, Stephens Inc. is a privately held, independent, full-service investment bank with a dedicated depository investment banking group offering advisory services for mergers and acquisitions as well as debt and equity capital markets. Since 2015, Stephens has advised on 50 Texas bank transactions totaling $8.8 billion. In addition, Stephens provides fixed income services, equity capital markets and equity research to depository institutions across Texas.', 'Mr. Kade N. Machen', 'Kade.machen@stephens.com', '(214) 258-2711', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000014b', 'Stovall, Grandey & Allen, LLP', 'https://www.sga-cpas.com', 'Stovall, Grandey and Allen, LLP has provided services to financial institutions for more than 40 years. In addition to audits, tax, compliance, BSA, ACH, internal audit, IT and loan reviews, the firm offers a wide range of accounting and consulting services to financial institutions, employee benefit plans and commercial entities. SGA has extensive experience in S Corporation taxes as 50% of our current financial institution clients are S Corporations. We are a PCAOB registered firm. Our lengthy involvement with banking associations and our long history with regulatory agencies provides us the expertise our banking clients have learned to rely upon and value. SGA emphasizes year-round relationships that provide consistent personal attention and exceptional service that we think our clients deserve. This has allowed us to expand our practice into Washington, Alaska, Oregon, California, and Idaho.', 'Ms. Brenda J. Young', 'byoung@sga-cpas.com', '(817) 271-1418', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000014c', 'Strata Decision Technology', 'https://www.stratadecision.com/solutions/financial-institutions', 'Strata Decision Technology, LLC provides innovative enterprise performance management software, data, and intelligence solutions for financial institutions. Its powerful budgeting and planning, profitability, and analytics solutions — including robust reporting and visualization tools — help institutions elevate performance and transform vision into reality. Hundreds of leading banks, credit unions, and farm credit associations rely on Strata’s Axiom solutions and proven industry expertise to acquire insights, accelerate decisions, and advance their business plans. For more information, please visit https://www.stratadecision.com/solutions/financial-institutions', 'Mr. Gavin Sheridan', 'gsheridan@stratadecision.com', '(847) 441-0022', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000014d', 'STRATA Trust Company', 'https://www.stratatrust.com', 'For nearly two decades, STRATA Trust Company has helped banks leverage private bank stock to raise capital quickly through self-directed retirement accounts. Renowned for superior service and holding a wide range of alternative investments, we are supported by a team of IRA experts familiar with IRS regulations. Based in Texas, STRATA operates under the Texas Department of Banking''s direct oversight and is a wholly owned subsidiary of Horizon Bank.', 'Mr. Dan Rupper', 'dan.rupper@stratatrust.com', '(512) 221-4853', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000014e', 'StrataDefense, LLC', 'https://www.stratadefense.com', 'With our Managed Security Services and Managed Network Support, your bank can adapt to the changing needs of the competitive financial landscape, keeping your data secure and reducing the risk of threats', 'Mr. Matthew Hildebrandt', 'matth@stratadefense.com', '(715) 842-7665', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000014f', 'StrategyCorps, LLC', 'https://www.strategycorps.com', 'Since 2001, nearly 400 financial institutions have generated billions of consumer-friendly revenue from our retail checking solutions, which are based on actionable analytics and a proprietary merchandising formula combined with value-added checking products that employ dynamic pricing - all delivered with an unbeatable digital user experience.', 'Mr. Clay Crenshaw', 'clay.crenshaw@strategycorps.com', '(888) 577-6933', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000150', 'Stratman Solutions, LLC', 'https://www.stratmansolutions.com', 'Stratman Solutions has been a trusted advisor to financial institutions since 1996. Stratman''s Bank Sweep Manager is considered the gold standard in overnight (sweep) repurchase solutions. Our Asset Quality Manager tool provides all-in-one Loan/CECL reporting. Our solutions are easy to maintain, are 100% compliant, and provide the best value.', 'Ms. Ann Bailey', 'Abailey@StratmanSolutions.com', '(563) 388-2692', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000151', 'Summit Financial Group', 'https://www.yoursummit.com', '5420 Lyndon B Johnson Fwy Ste 1940 Dallas, TX 75240-6251 We are a national full-service benefits firm offering innovative and comprehensive solutions that cover the benefits, insurance and investments landscape. We are passionate about building relationships, providing experienced and thoughtful professional guidance that helps secure a healthy financial outlook.', 'Mr. Aaron Barnett', 'abarnett@yoursummit.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000152', 'Sympera Inc.', '', '(203) 536-1840 15 Augusta Ct Greenville, SC 29605-1952 Sympera is an Agentic-AI platform built specifically for for relationship banking. We provide intelligent banker-ready actions to help bankers focus on the timely prospecting, driving meaningful conversations, and delivering exceptional results, regardless of RM experience or client size.', 'Mr. Tom Roberts', 'tom.roberts@sympera.ai', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000153', 'Synergy by Association', 'https://www.synergybai.com', 'TBA’s partnership with ODP Business Solutions is part of a national state bankers association discount program accessed by hundreds of banks across the country. The program has proven to deliver an average cost savings of 20-30% to participating members.  New Customers:  Register for an account at www.odpbusiness.com/banksignup.', 'Cheryl Krawczyk', 'cheryl.krawczyk@odpbusiness.com', '(503) 581-3522', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000154', 'Syntrio', 'https://syntrio.net', '918 Lamar St Wichita Falls, TX 76301-3444 Syntrio is part of the fabric of rural Texas and Southern Oklahoma communities, connecting businesses and households to the rest of the world via fast, affordable, and reliable digital services; minimizing the confines of modern technology; and treating customers the way we want to be treated, like the good neighbors we are.', 'Brooke Christensen', 'brooke.christensen@syntrio.net', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000155', 'TCC Consulting Services, LLC', 'https://www.tccconsultingservices.com', 'Our compliance consulting services are designed to meet the ongoing demands of regulatory requirements of smaller financial institutions. TCC Consulting Services'' compliance consulting professionals can complement your internal compliance staff on an outsourced basis, periodically update and train your staff on new developments, or handle all the regulatory compliance needs for your institution. We also provide a full range of compliance and internal audit reviews including Fair Lending, regulatory compliance reviews, BSA/AML reviews, ACH reviews, Loan Reviews, and internal control reviews.', 'Ms. Tammy Gill, CPA, CFE', 'tammy@tccconsultingservices.com', '(325) 656-2247', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000156', 'Teremark CIO, LLC', 'https://www.teremarkcio.com', 'Teremark CIO delivers Fortune 500-experienced IT leadership to community banks through a high-impact fractional model. Our CIOs and CISOs, all veterans of large-scale financial institutions, specialize in IT strategy, cybersecurity governance, and digital transformation. By aligning technology investments with business growth, we mitigate fiduciary risk and navigate complex regulatory landscapes. We provide the sophisticated oversight necessary to protect your Board and institution, ensuring elite enterprise-level security and operational excellence without the full-time executive expense.', 'Mr. Mark Blazek', 'mblazek@teremarkcio.com', '(210) 792-7799', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000157', 'Texas Republic Life Insurance', 'https://www.texasrepubliclife.com', 'In 2015 over $32 billion in life insurance and annuity premium was paid by Texas residents; however, over 91% of it went to out-of-state companies. Our goal is simple: to keep that money here and to put it to work in the great state of Texas. Texas Republic Life Insurance Company was founded by the state''s top business, professional and agricultural leaders. Our principles are guided by the conservative values that this state was founded upon. We are committed to providing innovative financial products that meet the needs of today and fulfill the promise of tomorrow. Providing security and vision for tomorrow''s future; In Texas, By Texans, For Texans.', 'Mr. Scott Gately', 'sgately@texasrepubliclife.com', '(512) 330-0099', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000158', 'TIER4 Technologies', 'https://tier4.com', '2900 Saint Michael Dr Ste 301 Texarkana, TX 75503-5210 TIER4 Technologies is a Texas-based IT and cybersecurity solutions partner. We help banks navigate technology procurement with confidence. Delivering infrastructure, cybersecurity, AI, cloud, data protection, licensing, and compliance-ready solutions—all backed by responsive, senior-level support. Founded by a former CIO for Texas banks, we understand the frustration of constant account manager turnover and the disruption it causes. At TIER4, you get a fast, reliable, and proven partner, who understands your environment, and stays with you for the long haul.', 'Mr. Jeremy Lacey', 'jeremy@tier4.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000159', 'Total Lender Solutions, Inc', 'https://totallendersolutions.com/', '10505 Sorrento Valley Rd San Diego, CA 92121 Total Lender Solutions (TLS) is a national default management company specializing in foreclosure processing, trustee sales, UCC sales, and reconveyances. For more than 30 years, TLS has guided banks and lenders through complex, state-specific foreclosure requirements, ensuring regulatory compliance, asset protection, and timely resolution of defaulted loans. In addition to operational support, TLS provides ongoing education and guidance to help lenders navigate evolving laws, mitigate risk, and make informed decisions.', 'Mr. Dean DeSana II', 'dean@tlsemails.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000015a', 'TPS Thayer', '', 'mark.heffner@tps.cpa https://tpscpas.com 1600 Highway 6 Ste 100 Sugar Land, TX 77478-4927 TPS Thayer is a tax and consulting firm located in Sugar Land, TX. The firm provides consulting services for small community banks in Texas.', 'Mr. Mark Heffner', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000015b', 'TraceSecurity, LLC', 'https://www.tracesecurity.com', 'TraceSecurity, LLC, has been a leading provider of cybersecurity and compliance solutions for over 22 years, having served over 3,700 organizations across the United States. We provide a comprehensive portfolio of solutions that allow organizations to manage their information security program, including IT risk assessments and audits, social engineering, penetration testing, configuration reviews, security training, and more.', 'Ms. Marissa Adams', 'marissaa@tracesecurity.com', '(225) 636-5205', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000015c', 'TransFund', '', '(918) 588-6707 1 One Williams Ctr Ste 15NE Tulsa, OK 74172-0140 TransFund has been making money move since 1975 and is one of the leading ATM/EFT networks and debit card processors in the nation. For over 50 years, TransFund has been technology driven and provides ATM, Debit Card, Merchant Services, Fraud Protection and customized marketing to community banks and businesses throughout Texas. We are focused on serving community banks with the same face-to-face service that makes them successful.', 'Ms. Stephanie Hill', 'stephanie.hill@transfund.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000015d', 'Travelers Insurance Company', 'https://www.travelers.com/business-insurance/financial-institutions/banks-diversified-institutions', 'With dedicated policies for financial institutions, Travelers offers a range of  insurance protection, including D&amp;O, cyber, professional liability, financial institution bonds, employment practices liability, fiduciary liability, ID fraud expense reimbursement and a full portfolio of property/casualty coverages. Choose either standalone coverage or a suite of coverages. Travelers has the flexibility to adapt to you and your business.', 'Mr. Todd Overstreet', 'toverstr@travelers.com', '(214) 570-6512', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000015e', 'TriData US Inc', 'www.tridatainc.com', '532 Highway 114 Ste 120 Fort Worth, TX 76177 TriData is a leading turnkey solutions provider in the Central U.S. financial equipment and logistics market. The Company delivers a unified service offering across the entire equipment lifecycle—from product introduction to certified decommissioning—creating a strategic partnership model that extends beyond traditional transactional services.', 'Mr. Christian Ranke', 'cr@tridatainc.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000015f', 'Trinity Real Estate Solutions, Inc.', 'https://www.trinityonline.com', 'Trinity Real Estate Solutions has been America''s Trusted Digital Draw Solution(TM) for over two decades, serving over 500 construction and renovation lenders nationwide. Our suite of construction lending solutions streamlines operations, mitigates risk, and ensures projects are completed on time and within budget. We offer pre-close risk mitigation reviews, Draw Inspections, loan administration services, and asset monitoring. Our unique value proposition includes dedicated client success managers, API connectivity, and SOC 2 certification for compliance. Partner with Trinity for your construction lending needs.', 'Mr. Brad Meyer', 'brad.meyer@trinityonline.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000160', 'Trintech', 'https://www.trintech.com', '5600 Granite Pkwy Ste 10000 Plano, TX 75024-4179 Trintech gives people time back for what matters most. Our AI Financial Close and enterprise reconciliation solutions enable financial institutions worldwide to lead productivity transformation across their finance, accounting and operations organizations — driving efficiencies, ensuring accuracy to mitigate risk, and empowering strategic decision-making. Make time count with Trintech.', 'Ms. Diane Saucier', 'dsaucier@trintech.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000161', 'True Digital Group', 'https://www.truedigitalgroup.com', '12333 Sowden Rd Ste B PMB 69747 Houston, TX 77080-2059 The True Digital Platform is a collaborative network designed for banks to optimize vendor relationships. By utilizing this insights-driven platform, banks can discover new vendors, manage, and optimize their vendor relationships, diligence and monitor their vendors, and connect with their peers across the industry. True Digital streamlines the process of finding suitable vendors for banks, resulting in improved decision-making, onboarding, monitoring, and innovation.', 'Mr. Patrick Sells', 'patrick@truedigitalgroup.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000162', 'TtcInnovations', '', '13319 Ferguson Forest Dr Charlotte, NC 28273-6996 ttcInnovations helps banks perform at their best by supporting the people who do the work and the way that work gets done. During mergers, acquisitions, and system conversions, we work closely with leadership, process redesign and technology teams to translate and train how employees will work in their new environment. We also support day-to-day operations through onboarding, new hire, upskilling, new product, and compliance learning solutions — backed by 25 years inside highly regulated financial environments.', 'Ms. Teresa Chiapputo', 'teresa.chiapputo@ttcinnovations.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000163', 'Turner Consulting Services, LP', 'https://www.Turnerbankconsulting.com', 'Turner Consulting Services has been a leading provider of auditing and consulting services since 1992, focusing primarily in the areas of asset quality reviews and regulatory compliance. Our client base consists of community banks throughout Texas, with most having asset sizes of under $1B, as our specialty is in providing hands-on service to smaller banks.', 'Mr. Bruce Turner', 'turner_consulting@sbcglobal.net', '(817) 860-2898', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000164', 'Tyler Technologies', 'https://www.tylertech.com', '5101 Tennyson Pkwy Plano, TX 75024-3525 Tyler Technologies is a leading provider of software and technology services for the public sector, helping local governments, courts, and schools operate more efficiently. Its solutions support areas such as finance, public safety, justice, data, and cloud services to improve transparency and community outcomes.', 'Mike Perico', 'mike.perico@tylertech.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000165', 'UBS Financial Services, Inc', 'https://advisors.ubs.com/agt/', 'Team AGT is a Plano, TX based UBS financial advisor team. Our 16-person team has more than 180 years of collective experience supporting affluent families and institutions, and their trusts, estates, foundations and pensions on all matters around capital markets. With the power of the UBS’s global breadth and depth, we deliver wealth management, tax and estate planning, concentrated stock positions, and the sales of privately held businesses for our clients and their Trustees.', 'Mr. Henry Jordan', 'henry.jordan@ubs.com', '(214) 981-0522', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000166', 'UFS Tech', 'https://ufstech.com', '717 Wood Mesa Ct Round Rock, TX 78665-1253 UFS, the bank technology outfitter improves IT efficiency with bank-exclusive technology solutions while providing exceptional customer experiences. UFS empowers banks through Managed IT Services, Core Banking, Cybersecurity as a Service, IT Regulatory Compliance, Regulated Cloud Hosting, Advisory Services, Infrastructure as a Service, Digital Banking and more! www.ufstech.com', 'Mr. Ruben Flores', 'rubenf@ufstech.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000167', 'UMB', 'https://www.umb.com', 'UMB Bank is a dedicated partner to Texas community banks. As your strategic balance sheet management partner, we can provide access to a comprehensive suite of solutions including budgeting and forecasting, interest rate risk reporting, capital planning and management, liquidity risk management and contingency funding, and investment portfolio management and safekeeping services. Products, Services and Securities offered through UMB Bank, n.a. Capital Markets Division, are: NOT FDIC INSURED | MAY LOSE VALUE | NOT BANK GUARANTEED', 'Mr. Michael Kolb', 'michael.kolb@umb.com', '(816) 860-7000', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000168', 'UniSec  Cybersecurity', '', 'thowlett@unisectx.com https://www.unisectx.com 2101 E Fm 1431 Marble Falls, TX 78654-3363 UniSec specializes in providing an innovative range of IT security, audit and compliance offerings to Texas community banks.  We also offer virtual Information Security Officer (ISO) services for Banks who need assistance preparing for audits, exams and maintaining security programs.  UniSec principals have over 60 years of combined experience serving Texas community banks with the staff and experience to provide cutting edge cybersecurity and compliance at a reasonable price.', 'Mr. Tony Howlett', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000169', 'United Data Technologies, Inc', 'https://www.udtonline.com', 'UDT is a privately-owned minority business headquartered in Miramar, Florida, with thirteen locations across five states. We focus on delivering advanced technical solutions to small, mid-market and enterprise customers. UDT is recognized as an industry-leader in the technology solutions arena. Founded in 1995, UDT subscribes to a Total Solutions Approach that includes traditional Consulting, Design, and Engineering Services; as well as a unique approach to Managing Infrastructure, Security, Cloud, and Device Lifecycles for our customers.', 'Mr. Guillermo Benites', 'gbenites@udtonline.com', '(954) 308-5100', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000016a', 'Unity FI Solutions LLC', '', 'nellie.schlachter@unityfisolutions.com https://unityfisolutions.com 508 W 5th St Ste 100 Charlotte, NC 28202-1886 For the past 27 years, Unity FI Solutions has been a trusted provider of Treasury Management and Merchant Processing solutions for banks nationwide. Our programs combine competitive pricing, scalable infrastructure, and advanced payment capabilities to help banks expand treasury services, reduce operational overhead, and deliver modern digital payment solutions to their business and commercial customers. We pride ourselves on responsive support and long-term partnerships with the institutions we serve.', 'Ms. Nellie Schlachter', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000016b', 'Upgrade Inc', '', 'knoyola@upgrade.com https://www.upgrade.com/institutions (303) 210-6954 275 Battery St Ste 2300 San Francisco, CA 94111-3366 Upgrade partners with banks for access to prime consumer assets as a complement to internal banking strategies and goals, including liquidity management, balance sheet diversification, or NIM pressure. Through technology and a nationwide platform, Upgrade provides FIs access to consumer loans, card receivables, auto refi loans, and a loan-for-deposit sweep program. With several offices in the US &amp; Canada, Upgrade has facilitated $21 billion in loans for 200+ partners.', 'Ms. Karla Noyola', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000016c', 'UPSTACK Holdco Inc.', 'https://upstack.com', '250 Greenwich ST 7 World Trade Ctr New York, NY 10007-2140 UPSTACK is the leading full-service technology brokerage that empowers businesses to make smarter technology investments. Through a vendor-neutral approach, UPSTACK delivers expert advisory and execution services across the entire technology landscape—including data center colocation, cloud, connectivity, networking, cybersecurity, AI, and more—at no additional cost to our clients.', 'Ms. Catherine Arel', 'catherine.arel@upstack.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000016d', 'USI Insurance Services', 'https://www.usi.com', 'USI is a leading insurance brokerage and consulting firm with approximately 200 local offices specializing in employee benefits, property/casualty, and specialty products. USI’s unique approach integrates proprietary analytics, deep industry expertise, and comprehensive services to deliver strategic, impactful insurance solutions.', 'Ms. Katie Eubanks', 'katie.eubanks@usi.com', '(713) 490-4684', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000016e', 'Valor', 'https://www.onevalor.com', 'Valor is a comprehensive professional services provider that uses technology and innovation to ease the burdens of asset management in the oil and gas industry. We place the client first, providing flexible solutions and leveraging our team of experts to maintain the security, clarity, and optimization of privately owned assets. Valor manages just over eight million gross mineral acres across 32 states, which generate over $100 million in annual revenue for its clients.', 'Mr. Joseph DeWoody', 'jpd@onevalor.com', '(817) 370-0612', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000016f', 'Vantage Point Solutions', '', 'Rebecca.Lange@vantagepnt.com https://www.vantagepnt.com (605) 359-2374 2211 N Minnesota St Mitchell, SD 57301-5521 Vantage Point Solutions has industry experts and comprehensive services to help financial institutions face compliance, audit, technology, and security challenges. Our team stays up to date on recent regulatory changes, significant and emerging IT and security risks, and state-of-the-art technology solutions, to offer a wholistic approach to protecting your organization.', 'Ms. Rebecca Lange', '', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000170', 'Vedder Price P.C.', 'https://www.vedder.com', 'Vedder Price P.C. is a thriving law firm with a proud tradition of maintaining long-term relationships with our clients, many of whom have been with us since our founding. Vedder’s Financial Institutions Group is a premier banking law group representing banks and other financial services providers in a broad spectrum of matters including:  · M&amp;A and other strategic initiatives  · Regulatory, enforcement and compliance matters  · Fintech/bank partnerships and affiliations  · Securities underwriting/placement  · De novo institution formation  · Executive compensation.', 'Mr. Mark Svalina', 'msvalina@vedder.com', '(312) 609-5043', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000171', 'Verge Network Solutions, LLC', 'https://www.vergenetwork.com', 'Verge leads in telecom innovations for community banks, specializing in advanced phone systems and unified communications. We offer solutions that integrate with existing networks or via our secure private cloud, focusing on cost efficiency and improved customer service. Our services include SD-WAN design and top-tier internet access, ensuring clients receive the best resources for a competitive edge. Choose Verge for a seamless, robust communication experience tailored to the banking industry.', 'Mr. Shayan Zadeh', 'shayan.zadeh@vergenetwork.com', '(713) 955-9110', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000172', 'Vericast', 'https://www.vericast.com', 'Vericast is the FI performance partner. We help banks and credit unions drive growth, improve efficiency, increase engagement and navigate change through the power of data, technology and people. Our advanced analytics, data-driven insights and integrated solution set enable better execution with agility, precision and scale. That''s why thousands of financial institutions look to Vericast and out 150 years of financial services expertise to help them achieve more.', 'AJ Macht', 'Aj.macht@vericast.com', '(678) 500-5330', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000173', 'VerityPay Holdings, LLC', 'https://veritypay.com', '800 Bering Dr Ste 225 Houston, TX 77057-2181 VerityPay is a cutting-edge payment technology platform revolutionizing business-to-consumer 
payments. We empower businesses to pay consumers instantly via text message, providing 
unmatched convenience and efficiency. With a low-cost, secure, and user-friendly solution, 
VerityPay simplifies payments, reduces operational burdens, and enhances customer satisfaction. 
Designed to operate both independently or integrate seamlessly into treasury management 
portfolios, our technology drives digital transformation for businesses and banks alike, offering a 
game-changing solution tailored to the needs of the financial industry.', 'Mr. Robert Bowdon', 'rb@veritypay.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000174', 'ViClarity', 'https://www.viclarity.com/us', 'Centralized Solutions for Good Governance: ViClarity provides a configurable, centralized system that integrates all your governance needs into an intuitive, automated platform, complemented by trusted regulatory compliance support services. This combination of software and services empowers financial institutions to enhance accountability, mitigate risks, ensure compliance, and drive operational excellence all with one partner. To learn more about ViClarity, visit www.viclarity.com/us.', 'Ms. Julie Davidson', 'Julie.davidson@viclarityus.com', '(844) 731-6080', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000175', 'Vikar Technologies, Inc', 'https://www.vikartech.com', '3 Saratoga Way Old Bridge, NJ 08857-3581 Vikar provides automated end-to-end software solutions to community banks. Our Omni-Channel Account Opening Solutions and Loan Origination Software enable seamless collaboration among various stakeholders such as customers, lenders, branch managers, underwriters, KYC teams, and operations teams. This is achieved through a unified interface that supports interactions across different banking services, including loans, deposits, treasury, and wealth management. Vikar''s solutions are designed with an integrated, comprehensive perspective on a bank’s operations and connects seamlessly with core banking systems.', 'Ms. Stephanie Mazzone', 'stephanie@vikartech.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000176', 'VindiX', '', '1984 N 2405 W Clearfield, UT 84015-5772 VindiX: Closing the Wire Transfer Security Gap VindiX adds a simple extra layer of protection to high-value payments. It quietly creates an invisible digital fingerprint of the exact instructions without altering the document. Recipients simply visit a standard webpage and check the file — receiving a green “Verified” if untouched or a red warning if anything has changed. No software or login required. Zero workflow changes. Complete confidence that the instructions are authentic before the wire is sent.', 'Nate Mills', 'nate@vindix.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000177', 'Weaver', 'https://www.weaver.com', 'Weaver is a national full-service accounting firm with offices coast-to-coast, serving clients from Fortune 500 multinational companies to start-ups, financial institutions, investment funds and government at all levels. The firm provides financial institutions with internal audit (either co-sourced or outsourced), SOX/ FDICIA compliance, regulatory compliance reviews, IT audits, risk management and financial statement audits.', 'Mr. James Mihills, CPA', 'james.mihills@weaver.com', '(972) 448-9232', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000178', 'Wells Fargo Advisors', 'https://www.wellsfargoadvisors.com', '', 'Mr. Duke Barnes', 'duke.barnes@wellsfargo.com', '(210) 377-7777', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000179', 'Whitley Penn LLP', 'https://www.whitleypenn.com', 'We are a full service public accounting firm with strong Texas roots. We have been supporting and serving community banks throughout Texas for more than 30 years. The in-depth banking experience of our senior management team allows us to help community banks navigate the changes and challenges they face. Our professionals look at each new challenge with a perspective as unique as you and your business. Whitley Penn is strategically positioned to serve Texas community banks.', 'Mr. Cecil W. Jones', 'cecil.jones@whitleypenn.com', '(214) 393-9300', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000017a', 'Willkie Farr & Gallagher LLP', 'http://www.willkie.com', '2699 Howell St Dallas, TX 75204-1034 Patrick Hanchey is a partner in Willkie’s Corporate &amp; Financial Services Department. He is based in the Dallas office. 

Patrick advises banks and financial institutions on state and federal banking laws, regulatory matters, enforcement actions and other corporate activities, including mergers, acquisitions, capital markets transactions and holding company formations. He has significant experience counseling clients on compliance with complex banking laws and regulations in connection with mergers, acquisitions, capital markets transactions, holding company formations and other corporate activities. In addition, he regularly represents banks, holding companies, and individuals in state and federal enforcement actions, as well as bank officers, directors, and shareholders in government actions and investigations.', 'Mr. Patrick Hanchey', 'phanchey@willkie.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000017b', 'Windsor Advantage', 'https://windsoradvantage.com', '444 N Wells St Ste 205 Chicago, IL 60654-4522 With more than 225 years of cumulative in-house SBA 7(a) and USDA experience, cutting edge systems and rigid controls, the team at Windsor Advantage is uniquely qualified to support its institutional clients to develop and execute a thoughtful and comprehensive SBA and USDA lending program. We also offer loan origination services to our portfolio clients.', 'Mr. Jay Russ', 'jruss@windsoradvantage.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000017c', 'Wipfli LLP', 'https://www.wipfli.com', 'Wipfli LLP ranks among the top 20 accounting and business consulting firms in the nation. For more than 90 years, our financial institutions practice has educated, advised, and assisted financial institutions in the successful navigation of the complex and ever-changing environment they face. Let our professionals assist you with your regulatory compliance, profit improvement, risk management, strategic planning/board development, IT services/cybersecurity, digital transformation, HR consulting, and audit and tax needs.', 'Ms. Summer Gustin', 'summer.gustin@wipfli.com', '(715) 858-6677', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000017d', 'Wolf & Company, P.C.', 'https://www.wolfandco.com', '3rd Floor Wolf &amp; Company is a national CPA and business consulting firm with a regional feel, providing assurance, tax, risk management and business consulting services across the United States. With over a century of experience working with financial institutions, we pride ourselves on personalized client service and unparalleled guidance. Through our collaborative service strategy, we understand our clients’ challenges and opportunities, and work with them to achieve their business goals while navigating potential obstacles.', 'Elisa Pelchat', 'Elisa.Pelchat@wolfandco.com', '(617) 439-9700', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000017e', 'Wolters Kluwer', 'https://www.WoltersKluwer.com', 'Wolters Kluwer Compliance Solutions delivers deep domain knowledge, advanced analytics, and regulatory services that optimize financial outcomes, reduce risk, and improve customer productivity.', 'Mr. Stephen  Bradley', 'stephen.bradley@wolterskluwer.com', '(612) 656-7700', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-00000000017f', 'Woodside Credit, LLC', 'https://www.woodsidecredit.com', '895 Dove St Ste 100 Newport Beach, CA 92660-2944 Since 2003, we’ve originated over $3.5 billion in prime-quality loans for highly qualified borrowers. Our loans are seamlessly packaged into weekly pools for client banks, helping them boost profitability, optimize loan-to-deposit ratios, diversify risk, and achieve exceptional portfolio performance with a 99.9% look-to-book ratio. Discover how Woodside Credit can drive success for your bank.', 'Mr. Mitch Shatzen', 'Mshatzen@woodsidecredit.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000180', 'Works24 Corporation', 'https://www.works24.com', 'Works24 is the leading provider of OnHold music and messaging services, Digital Signage video displays, and overhead music systems to the banking industry. We provide a true partnership that makes it effortless and extremely easy to create custom programs for your marketing and promotions while reinforcing your bank''s unique image.', 'Mr. Ryan Humphrey', 'rhumphrey@works24.com', '(800) 460-4653', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000181', 'Wysh, a Life and Health Company', 'https://www.wysh.com', '720 E Wisconsin Ave Milwaukee, WI 53202-4797 Wysh’s award-winning deposit solution, Life Benefit, revolutionizes and invigorates traditional banking. Life Benefit helps Financial Institutions grow, retain, and differentiate their offering by seamlessly embedding micro-life insurance onto a deposit account. Worth 1-10% of the consumer’s account balance, Life Benefit encourages consumers to plan for their financial future, while enhancing brand loyalty and strengthening FI’s balance sheet. Life Benefit has been recognized as one of the most inclusive life insurance options on the market.', 'Ms. Kseniya Zaslavskaya-Rosado', 'kseniya.zaslavskaya-rosado@wysh.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000182', 'XChange', 'https://www.xchangefi.com/', 'xChange enables community banks and impact investors to easily search for and buy prime impact loans, shop CRA-eligible loans in their assessment areas and build their balance sheets. Our platform allows users to easily filter, toggle, and purchase loans based on their investment criteria.', 'Mr. Ryan Collins', 'rcollins@changemtg.com', '(925) 262-3505', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000183', 'YHB CPAs & Consultants', 'https://yhbcpa.com', '160 Exeter Dr Ste 200 Winchester, VA 22603-8614 YHB’s Financial Services Team empowers community banks with tailored expertise to grow, manage, and protect their assets. With over 300 professionals, we partner with industry leaders to build resilience through personalized audits, risk advisory, and tax optimization. Our bank-focused team delivers strategic consulting that enhances efficiency, ensures compliance, and drives growth. Aligned with each bank’s unique goals, YHB is committed to securing long-term stability and exceptional success in a competitive financial landscape.', 'Mr. Andrew Throckmorton', 'drew-throckmorton@yhbcpa.com', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000184', 'Zest AI', 'https://www.zest.ai/', '3900 W Alameda Ave Ste 1600 Burbank, CA 91505-4387 Since 2009, Zest AI has been innovating and perfecting AI lending technology. A pioneer in the field, serving more than $5.5T in assets with over 500 active models, Zest AI is helping FIs and specialty lenders build thriving lending ecosystems. Zest AI aims to make purpose-built, best-in-class AI technology available to lenders to help broaden access to equitable lending.', 'Mrs. Erin Bennett', 'ecb@zest.ai', '', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000185', 'Zilker Media', 'https://zilkermedia.com', 'Zilker Media is an end-to-end PR and Brand Strategy Agency for thought leaders and the companies they lead. Our award-winning PR agency provides standout corporate and personal branding, strategic public relations representation, and contemporary digital marketing strategies for executives and leaders—helping them become true thought leaders and trusted representatives of their companies.', 'Mrs. Nichole Williamson', 'NICHOLE@ZILKERMEDIA.COM', '(512) 298-4081', 'usr00000-0000-4000-8000-000000000001');
INSERT OR IGNORE INTO vendors (id, name, website, description, contact_name, contact_email, contact_phone, created_by) VALUES ('vnd00000-0000-4000-8000-000000000186', 'Zurich North America', 'https://www.zurichna.com/', '150 Greenwich St Fl 4 New York, NY 10007-2339 Zurich U.S. is part of Zurich Insurance Group, a global insurer with approximately 9,000 employees in North America and 56,000 worldwide. We provide a wide range of property, casualty, and life insurance solutions in more than 210 countries and territories. Zurich has been delivering insurance solutions to financial institutions longer than any other insurance provider in the U.S.', 'Mr. Trey Martino', 't.martino@zurichna.com', '', 'usr00000-0000-4000-8000-000000000001');

